comms.text:
@1 וּקְרָא לְמשֶׁה וּמַלֵּיל יְיָ עִמֵּיהּ מִמַּשְׁכַּן זִמְנָא לְמֵימָר:
@2 מַלֵּיל עִם בְּנֵי יִשְׂרָאֵל וְתֵימַר לְהוֹן אֱנַשׁ אֲרֵי יְקָרֵיב מִנְּכוֹן קֻרְבָּנָא קֳדָם יְיָ מִן בְּעִירָא מִן תּוֹרֵי וּמִן עָנָא תְּקָרְבוּן יָת קֻרְבַּנְכוֹן:
@3 אִם עֲלָתָא קֻרְבָּנֵיהּ מִן תּוֹרֵי דְּכַר שְׁלִים יְקָרְבִנֵּיהּ לִתְרַע מַשְׁכַּן זִמְנָא יְקָרֵב יָתֵיהּ לְרַעֲוָא לֵיהּ קֳדָם יְיָ:
@4 וְיִסְמוֹךְ יְדֵיהּ עַל רֵישׁ עֲלָתָא וְיִתְרְעֵי לֵיהּ לְכַפָּרָא עֲלוֹהִי:
@5 וְיִכּוֹס יָת בַּר תּוֹרֵי קֳדָם יְיָ וִיקָרְבוּן בְּנֵי אַהֲרֹן כָּהֲנַיָּא יָת דְּמָא וְיִזְרְקוּן יָת דְּמָא עַל מַדְבְּחָא סְחוֹר סְחוֹר דִּי בִתְרַע מַשְׁכַּן זִמְנָא:
@6 וְיַשְׁלַח יָת עֲלָתָא וִיפַלֵּג יָתַהּ לְאֶבְרָהָא:
@7 וְיִתְּנוּן בְּנֵי אַהֲרֹן כַּהֲנָא אֶשָּׁתָא עַל מַדְבְּחָא וִיסַדְּרוּן אָעַיָּא עַל אֶשָּׁתָא:
@8 וִיסַדְּרוּן בְּנֵי אַהֲרֹן כָּהֲנַיָּא יָת אֶבְרַיָּא יָת רֵישָׁא וְיָת תַּרְבָּא עַל אָעַיָּא דִּי עַל אֶשָׁתָא דִּי עַל מַדְבְּחָא:
@9 וְגַוֵיהּ וּכְרָעוֹהִי יְחַלֵּל בְּמַיָּא וְיַסֵּק כַּהֲנָא יָת כּוֹלָא לְמַדְבְּחָא עֲלָתָא קֻרְבַּן דְּמִתְקַבֵּל בְּרַעֲוָא קֳדָם יְיָ:
@10 וְאִם מִן עָנָא קֻרְבָּנֵיהּ מִן אִמְּרַיָּא אוֹ מִן בְּנֵי עִזַיָּא לַעֲלָתָא דְּכַר שְׁלִים יְקָרְבִינֵיהּ:
@11 וְיִכּוֹס יָתֵיהּ עַל צִדָּא דְמַדְבְּחָא צִפּוּנָא קֳדָם יְיָ וְיִזְרְקוּן בְּנֵי אַהֲרֹן כָּהֲנַיָּא יָת דְּמֵיהּ עַל מַדְבְּחָא סְחוֹר סְחוֹר:
@12 וִיפַלֵּג יָתֵיהּ לְאֵבָרוֹהִי וְיָת רֵישֵׁיהּ וְיָת תַּרְבֵּיהּ וְיַסְדַּר כַּהֲנָא יָתְהוֹן עַל אָעַיָּא דִּי עַל אֶשָּׁתָא דִּי עַל מַדְבְּחָא:
@13 וְגַוָּא וּכְרָעַיָּא יְחַלֵּל בְּמַיָּא וִיקָרֵב כַּהֲנָא יָת כּוֹלָא וְיַסֵּק לְמַדְבְּחָא עֲלָתָא הוּא קֻרְבַּן דְּמִתְקַבֵּל בְּרַעֲוָא קֳדָם יְיָ:
@14 וְאִם מִן עוֹפָא עֲלָתָא קֻרְבָּנֵיהּ קֳדָם יְיָ וִיקָרֵב מִן שַׁפְנִינַיָּא אוֹ מִן בְּנֵי יוֹנָה יָת קֻרְבָּנֵיהּ:
@15 וִיקָרְבִנֵיהּ כַּהֲנָא לְמַדְבְּחָא וְיִמְלוֹק יָת רֵישֵׁיהּ וְיַסֵּק לְמַדְבְּחָא וְיִתִּמְצֵי דְמֵיהּ עַל כּוֹתֶל מַדְבְּחָא:
@16 וְיַעֲדֵּי יָת זְפָקֵיהּ בְּאוּכְלֵיהּ וְיִרְמֵי יָתַהּ לִסְטַר מַדְבְּחָא קִידוּמָא לַאֲתַר דְּמוֹשְׁדִין קִטְמָא:
@17 וִיפָרֵיק יָתֵיהּ בְּגַדְפוֹהִי לָא יַפְרֵישׁ וְיַסֵּק יָתֵיהּ כַּהֲנָא לְמַדְבְּחָא עַל אָעַיָּא דִּי עַל אֶשָּׁתָא עֲלָתָא הוּא קֻרְבָּן דְּמִתְקַבֵּל בְּרַעֲוָא קֳדָם יְיָ:
@18 וֶאֱנַשׁ אֲרֵי יְקָרֵב קֻרְבַּן מִנְחָתָא קֳדָם יְיָ סוּלְתָּא יְהֵי קֻרְבָּנֵיהּ וִירִיק עֲלָהּ מִשְׁחָא וְיִתֵּן עֲלָהּ לְבוֹנְתָּא:
@19 וְיַיְתִנָּהּ לְוָת בְּנֵי אַהֲרֹן כָּהֲנַיָּא וְיִקְמוֹץ מִתַּמָּן מְלֵי קֻמְצֵיהּ מִסֻּלְתָּא וּמִמִּשְׁחַהּ עַל כָּל לְבוֹנְתָּהּ וְיַסֵּק כַּהֲנָא יָת אַדְכַּרְתָּהּ לְמַדְבְּחָא קֻרְבַּן דְּמִתְקַבֵּל בְּרַעֲוָא קֳדָם יְיָ:
@20 וּדְאִשְׁתָּאַר מִן מִנְחָתָא לְאַהֲרֹן וְלִבְנוֹהִי קוֹדֶשׁ קוּדְשִׁין מִקֻּרְבָּנַיָּא דַיְיָ:
@21 וַאֲרֵי תְּקָרֵיב קֻרְבַּן מִנְחָתָא מַאֲפֵה תַנּוּרָא סוּלְתָּא גְּרִיצָן פַּטִּירָן דְּפִילָן בִּמְשַׁח וְאַסְפּוֹגִין פַּטִּירִין דִּמְשִׁיחִין בִּמְשָׁח:
@22 וְאִם מִנְחָתָא עַל מַסְרֵיתָא קֻרְבָּנָךְ סוּלְתָּא דְּפִילָא בִמְשַׁח פַּטִּיר תְּהֵי:
@23 בְּצַע יָתָהּ בִּיצוּעִין וּתְרִיק עֲלָהּ מִשְׁחָא מִנְחָתָא הִיא:
@24 וְאִם מִנְחָתָא דְרַדְתָּא קֻרְבָּנָךְ סוּלְתָּא בִמְשַׁח תִּתְעֲבֵד:
@25 וְתַיְתֵי יָת מִנְחָתָא דִּי יִתְעֲבֵד מֵאִלֵּין קֳדָם יְיָ וִיקַרְבִינָה לְוָת כַּהֲנָא וִיקַרְבִנַּהּ לְמַדְבְּחָא:
@26 וְיַפְרֵישׁ כַּהֲנָא מִן מִנְחָתָא יָת אַדְכַּרְתָּה וְיַסֵּק לְמַדְבְּחָא קֻרְבַּן דְּמִתְקַבֵּל בְּרַעֲוָא קֳדָם יְיָ:
@27 וּדְאִשְׁתָּאַר מִן מִנְחָתָא לְאַהֲרֹן וְלִבְנוֹהִי קוֹדֶשׁ קוּדְשִׁין מִקֻּרְבָּנַיָּא דַיְיָ:
@28 כָּל מִנְחָתָא דִּי תְקָרְבוּן קֳדָם יְיָ לָא תִתְעֲבֵד חֲמִיעַ אֲרֵי כָל חֲמִיר וְכָל דְּבַשׁ לָא תַסְּקוּן מִנֵּיהּ קֻרְבָּנָא קֳדָם יְיָ:
@29 קֻרְבַּן קַדְמַי תְּקָרְבוּן יָתְהוֹן קֳדָם יְיָ וּלְמַדְבְּחָא לָא יִתַּסְּקוּן לְאִתְקַבָּלָא בְרַעֲוָא:
@30 וְכָל קֻרְבַּן מִנְחָתָךְ בְּמִלְחָא תִמְלַח וְלָא תְבַטֵּל מְלַח קְיַם אֱלָהָךְ מֵעַל מִנְחָתָךְ עַל כָּל קֻרְבָּנָךְ תְּקָרֵב מִלְחָא:
@31 וְאִם תְּקָרֵב מִנְחַת בִּכּוּרִין קֳדָם יְיָ אָבִיב קְלֵי בְנוּר פֵּירוֹכָן רַכִּיכָן תְּקָרֵיב יָת מִנְחַת בִּכּוּרָךְ:
@32 וְתִתֵּן עֲלַהּ מִשְׁחָא וּתְשַׁוֵּי עֲלַהּ לְבוֹנְתָּא מִנְחָתָא הִיא:
@33 וְיַסֵּק כַּהֲנָא יָת אִדְכַּרְתַּהּ מִפֵּרוּכַהּ וּמִמִּשְׁחַהּ עַל כָּל לְבוֹנְתָּהּ קֻרְבָּנָא קֳדָם יְיָ:
@34 וְאִם נִכְסַת קוּדְשַׁיָּא קֻרְבָּנֵיהּ אִם מִן תּוֹרֵי הוּא מְקָרֵב אִם דְּכַר אִם נוּקְבָא שְׁלִים יְקָרְבִינֵיהּ קֳדָם יְיָ:
@35 וְיִסְמוֹךְ יְדֵיהּ עַל רֵישׁ קֻרְבָּנֵיהּ וְיִכְּסִנֵּיהּ בִּתְרַע מַשְׁכַּן זִמְנָא וְיִזְרְקוּן בְּנֵי אַהֲרֹן כָּהֲנַיָּא יָת דְּמָא עַל מַדְבְּחָא סְחוֹר סְחוֹר:
@36 וִיקָרֵב מִנִּכְסַת קוּדְשַׁיָּא קֻרְבָּנָא קֳדָם יְיָ יָת תַּרְבָּא דְּחָפֵי יָת גַּוָּא וְיָת כָּל תַּרְבָּא דִּי עַל גַּוָּא:
@37 וְיָת תַּרְתֵּין כָּלְיָן וְיָת תַּרְבָּא דִי עֲלֵיהֶן דִּי עַל גִּסְסַיָּא וְיָת חַצְרָא דְּעַל כַּבְדָא עַל כָּלְיֵתָא יַעֲדִּנָּהּ:
@38 וְיַסְקוּן יָתֵיהּ בְּנֵי אַהֲרֹן לְמַדְבְּחָא עַל עֲלָתָא דִּי עַל אָעַיָּא דִּי עַל אֶשָּׁתָא קֻרְבַּן דְּמִתְקַבֵּל בְּרַעֲוָא קֳדָם יְיָ:
@39 וְאִם מִן עָנָא קֻרְבָּנֵיהּ לְנִכְסַת קוּדְשַׁיָּא קֳדָם יְיָ דְּכַר אוֹ נֻקְבָּא שְׁלִים יְקָרְבִנֵּיהּ:
@40 אִם אִימָר הוּא מְקָרֵב יָת קֻרְבָּנֵיהּ וִיקָרֵיב יָתֵיהּ קֳדָם יְיָ:
@41 וְיִסְמוֹךְ יָת יְדֵיהּ עַל רֵישׁ קֻרְבָּנֵיהּ וְיִכּוֹס יָתֵיהּ קֳדָם מַשְׁכַּן זִמְנָא וְיִזְרְקוּן בְּנֵי אַהֲרֹן יָת דְּמֵיהּ עַל מַדְבְּחָא סְחוֹר סְחוֹר:
@42 וִיקָרֵב מִנִּכְסַת קוּדְשַׁיָּא קֻרְבָּנָא קֳדָם יְיָ תַּרְבֵּיהּ אֲלִיתָא שְׁלִימְתָּא לָקֳבֵל שְׁזַרְתָּא יֶעְדִנַּהּ וְיָת תַּרְְבָּא דְּחָפֵי יָת גַּוָּא וְיָת כָּל תַּרְבָּא דִּי עַל גַּוָּא:
@43 וְיָת תַּרְתֵּין כָּלְיָן וְיָת תַּרְבָּא דִּי עֲלֵיהֶן דִּי עַל גִּסְסַיָּא וְיָת חַצְרָא דְּעַל כַּבְדָּא עַל כָּלְיֵתָא יֶעְדִּנַּהּ:
@44 וְיַסְּקִנֵּיהּ כַּהֲנָא לְמַדְבְּחָא לְחֵם קֻרְבָּנָא קֳדָם יְיָ:
@45 וְאִם מִן בְּנֵי עִזַּיָּא קֻרְבָּנֵיהּ וִיקָרְבִנֵּיהּ קֳדָם יְיָ:
@46 וְיִסְמוֹךְ יָת יְדֵיהּ עַל רֵישֵׁיהּ וְיִכּוֹס יָתֵיהּ קֳדָם מַשְׁכַּן זִמְנָא וְיִזְרְקוּן בְּנֵי אַהֲרֹן יָת דְּמֵיהּ עַל מַדְבְּחָא סְחוֹר סְחוֹר:
@47 וִיקָרֵב מִנֵּיהּ קֻרְבָּנֵיהּ קֻרְבָּן קֳדָם יְיָ יָת תַּרְבָּא דְּחָפֵי יָת גַּוָּא וְיָת כָּל תַּרְבָּא דִּי עַל גַּוָּא:
@48 וְיָת תַּרְתֵּין כָּלְיָן וְיָת תַּרְבָּא דִּי עֲלֵיהֶן דִּי עַל גִּסְסַיָּא וְיָת חַצְרָא דִּי עַל כַּבְדָא עַל כָּלְיֵתָא יֶעְדִּנַּהּ:
@49 וְיַסְּקִנּוּן כַּהֲנָא לְמַדְבְּחָא לְחֵם קֻרְבָּנָא לְאִתְקַבָּלָא בְרַעֲוָא כָּל תַּרְבָּא קֳדָם יְיָ:
@50 קְיָם עָלָם לְדָרָתֵיכוֹן בְּכֹל מוֹתְבָנֵיכוֹן כָּל תַּרְבָּא וְכָל דְּמָא לָא תֵיכְלוּן:
@51 וּמַלִּיל יְיָ עִם משֶׁה לְמֵימָר:
@52 מַלֵּל עִם בְּנֵי יִשְׂרָאֵל לְמֵימָר אֱנַשׁ אֲרֵי יֵחוֹב בְּשָׁלוּ מִכָּל פִּקּוּדַיָּא דַיְיָ דִּי לָא כַשְׁרִין לְאִתְעֲבָדָא וְיַעְבֵּד מִן חַד מִנְּהוֹן:
@53 אִם כַּהֲנָא רַבָּא יֵחוֹב לְחוֹבַת עַמָּא וִיקָרֵב עַל חוֹבְתֵיהּ דִּי חָב תּוֹר בַּר תּוֹרֵי שְׁלִים קֳדָם יְיָ לְחַטָּאתָא:
@54 וְיַיְתִי יָת תּוֹרָא לִתְרַע מַשְׁכַּן זִמְנָא לָקֳדָם יְיָ וְיִסְמוֹךְ יָת יְדֵיהּ עַל רֵישׁ תּוֹרָא וְיִכּוֹס יָת תּוֹרָא קָדֳם יְיָ:
@55 וְיִסַּב כַּהֲנָא רַבָּא מִדְּמָא דְתוֹרָא וְיָעֵל יָתֵיהּ לְמַשְׁכַּן זִמְנָא:
@56 וְיִטְבּוֹל כַּהֲנָא יָת אֶצְבְּעֵיהּ בִּדְמָא וְיַדִּי מִן דְּמָא שְׁבַע זִמְנִין קֳדָם יְיָ קֳדָם פָּרוּכְתָּא דְקוּדְשָׁא:
@57 וְיִתֵּן כַּהֲנָא מִן דְּמָא עַל קַרְנַת מַדְבַּח דִקְטוֹרֶת בּוּסְמַיָא קֳדָם יְיָ דִּי בְּמַשְׁכַּן זִמְנָא וְיָת כָּל דְּמָא דְתוֹרָא יֵשׁוּד לִיסוֹדָא דְּמַדְבְּחָא דַעֲלָתָא דִּי בִתְרַע מַשְׁכַּן זִמְנָא:
@58 וְיָת כָּל תְּרַב תּוֹרָא דְחַטָּאתָא יַפְרֵשׁ מִנֵּיהּ יָת תַּרְבָּא דְּחָפֵי עַל גַּוָּא וְיָת כָּל תַּרְבָּא דִּי עַל גַּוָּא:
@59 וְיָת תַּרְתֵּין כָּלְיָן וְיָת תַּרְבָּא דִּי עֲלֵיהוֹן דִּי עַל גִּסְסַיָּא וְיָת חִצְרָא דְּעַל כַּבְדָא עַל כָּלְיֵתָא יֶעְדִּנַּהּ:
@60 כְּמָא דִי מִתַּפְרַשׁ מִתּוֹר נִכְסַת קוּדְשַׁיָּא וְיַסֵּקִנּוּן כַּהֲנָא עַל מַדְבְּחָא דַעֲלָתָא:
@61 וְיָת מְשַׁךְ תּוֹרָא וְיָת כָּל בִּסְרֵיהּ עַל רֵישֵׁיהּ וְעַל כְּרָעוֹהִי וְגַוֵּיהּ וְאוּכְלֵיהּ:
@62 וְיַפֵּק יָת כָּל תּוֹרָא מִבָּרָא לְמַשְׁרִיתָא לַאֲתַר דְּכֵי לַאֲתַר בֵּית מֵישַׁד קִטְמָא וְיוֹקִיד יָתֵיהּ עַל אָעַיָּא בְּאֶשָּׁתָא עַל אֲתַר בֵּית מֵישַׁד קִטְמָא יִתּוֹקָד:
@63 וְאִם כָּל כְּנִשְׁתָּא דְיִשְׂרָאֵל יִשְׁתְּלוּן וִיהֵי מְכַסָּא פִתְגָּמָא מֵעֵינֵי קְהָלָא וְיַעְבְּדוּן חָד מִכָּל פִּקּוּדַיָּא דַיְיָ דִּי לָא כָשְׁרִין לְאִתְעֲבָדָא וִיחוֹבוּן:
@64 וְתִתְיְדַע חוֹבְתָא דִּי חָבוּ עֲלַהּ וִיקַרְבוּן קְהָלָא תּוֹר בַּר תּוֹרֵי לְחַטָּאתָא וְיַיְתוּן יָתֵיהּ לָקֳדָם מַשְׁכַּן זִמְנָא:
@65 וְיִסְמְכוּן סָבֵי כְנִשְׁתָּא יָת יְדֵיהוֹן עַל רֵישׁ תּוֹרָא קֳדָם יְיָ וְיִכּוֹס יָת תּוֹרָא קֳדָם יְיָ:
@66 וְיָעֵל כַּהֲנָא רַבָּא מִן דְּמָא דְתוֹרָא לְמַשְׁכַּן זִמְנָא:
@67 וְיִטְבּוֹל כַּהֲנָא אִצְבְּעֵיהּ מִן דְּמָא וְיַדִּי שְׁבַע זִמְנִין קֳדָם יְיָ קֳדָם פָּרֻכְתָּא:
@68 וּמִן דְּמָא יִתֵּן עַל קַרְנַת מַדְבְּחָא דִּי קֳדָם יְיָ דִּי בְּמַשְׁכַּן זִמְנָא וְיָת כָּל דְּמָא יֵשׁוֹד לִיסוֹדָא דְּמַדְבְּחָא דַעֲלָתָא דִּי בִתְרַע מַשְׁכַּן זִמְנָא:
@69 וְיָת כָּל תַּרְבֵּיהּ יַפְרֵשׁ מִנֵּיהּ וְיַסֵּק לְמַדְבְּחָא:
@70 וְיַעְבֵּד לְתוֹרָא כְּמָא דִי עֲבַד לְתוֹרָא דְחַטָּאתָא כֵּן יַעְבֵּד לֵיהּ וִיכַפֵּר עֲלֵיהוֹן כַּהֲנָא וְיִשְׁתְּבֵק לְהוֹן:
@71 וְיַפֵּק יָת תּוֹרָא לְמִבָּרָא לְמַשְׁרִיתָא וְאוֹקִיד יָתֵיהּ כְּמָא דִי אוֹקִיד יָת תּוֹרָא קַדְמָאָה חַטַּאת קְהָלָא הוּא:
@72 אִם רַבָּא יֵחוֹב וְיַעְבֵּד חַד מִכָּל פִּקּוּדַיָּא דַיְיָ אֱלָהֵיהּ דִּי לָא כַשְׁרִין לְאִתְעֲבָדָא בְּשָׁלוּ וְיֵחוֹב:
@73 אוֹ אִתְיְדַע לֵיהּ חוֹבְתֵיהּ דִּי חַב בַּהּ וְיַיְתִי יָת קֻרְבָּנֵיהּ צְפִיר בַּר עִזִּין דְּכַר שְׁלִים:
@74 וְיִסְמוֹךְ יְדֵיהּ עַל רֵישָׁא דִצְפִירָא וְיִכּוֹס יָתֵיהּ בַּאֲתַר דְּיִכּוֹס יָת עֲלָתָא לָקֳדָם יְיָ חַטָּאתָא הוּא:
@75 וְיִסַּב כַּהֲנָא מִדְּמָא דְחַטָּאתָא בְּאֶצְבְּעֵיהּ וְיִתֵּן עַל קַרְנַת מַדְבְּחָא דַעֲלָתָא וְיָת דְּמֵיהּ יֵשׁוֹד לִיסוֹדָא דְמַדְבְּחָא דַעֲלָתָא:
@76 וְיָת כָּל תַּרְבֵּיהּ יַסֵּק לְמַדְבְּחָא כִּתְרַב נִכְסַת קוּדְשַׁיָּא וִיכַפֵּר עֲלוֹהִי כַּהֲנָא מֵחוֹבְתֵיהּ וְיִשְׁתְּבֵק לֵיהּ:
@77 וְאִם אֱנַשׁ חַד יֵחוֹב בְּשָׁלוּ מֵעַמָּא דְאַרְעָא בְּמֶעְבְּדַהּ חַד מִפִּקּוּדַיָּא דַיְיָ דִּי לָא כַשְׁרִין לְאִתְעֲבָדָא וְיֵחוֹב:
@78 אוֹ אִתְיְדַע לֵיהּ חוֹבְתֵיהּ דִּי חָב וְיַיְתִי קֻרְבָּנֵיהּ צְפִירַת עִזִּין שְׁלֶמְתָּא נְקוּבְתָּא עַל חוֹבְתֵיהּ דִּי חָב:
@79 וְיִסְמוֹךְ יָת יְדֵיהּ עַל רֵישׁ חַטָּאתָא וְיִכּוֹס יָת חַטָּאתָא בַּאֲתַר דַּעֲלָתָא:
@80 וְיִסַּב כַּהֲנָא מִדְמַהּ בְּאֶצְבְּעֵיהּ וְיִתֵּן עַל קַרְנַת מַדְבְּחָא דַעֲלָתָא וְיָת כָּל דְּמַהּ יֵשׁוֹד לִיסוֹדָא דְּמַדְבְּחָא:
@81 וְיָת כָּל תַּרְבַּהּ יֶעְדֵּי כְּמָא דִי מִתַּעְדָּא תְרַב מֵעַל נִכְסַת קוּדְשַׁיָּא וְיַסֵּק כַּהֲנָא לְמַדְבְּחָא לְאִתְקַבָּלָא בְרַעֲוָא קֳדָם יְיָ וִיכַפֵּר עֲלוֹהִי כַּהֲנָא וְיִשְׁתְּבֵק לֵיהּ:
@82 וְאִם אִימַר יַיְתִי קֻרְבָּנֵיהּ לְחַטָּאתָא נֻקְבָּא שְׁלֶמְתָּא יַיְתִנַּהּ:
@83 וְיִסְמוֹךְ יָת יְדֵיהּ עַל רֵישׁ חַטָּאתָא וְיִכּוֹס יָתַהּ לְחַטָּאתָא בְּאַתְרָא דִּי יִכּוֹס יָת עֲלָתָא:
@84 וְיִסַּב כַּהֲנָא מִדְּמָא דְחַטָּאתָא בְּאֶצְבְּעֵיהּ וְיִתֵּן עַל קַרְנַת מַדְבְּחָא דַעֲלָתָא וְיָת כָּל דְּמַהּ יֵשׁוֹד לִיסוֹדָא דְּמַדְבְּחָא:
@85 וְיָת כָּל תַּרְבַּהּ יֶעְדֵּי כְּמָא דִי מִתַּעְדָּא תְרַב אִמְּרָא מִנִּכְסַת קוּדְשַׁיָּא וְיַסֵּק כַּהֲנָא יָתְהוֹן לְמַדְבְּחָא עַל קֻרְבְּנַיָּא דַיְיָ וִיכַפֵּר עֲלוֹהִי כַּהֲנָא עַל חוֹבְתֵיהּ דִּי חָב וְיִשְׁתְּבֵק לֵיהּ:
@86 וֶאֱנַשׁ אֲרֵי יֵחוֹב וְיִשְׁמַע קַל מוֹמֵי וְהוּא סָהִיד אוֹ חֲזָא אוֹ יְדָע אִם לָא יְחַוִּי וִיקַבֵּל חוֹבֵיהּ:
@87 אוֹ אֱנַשׁ דִּי יִקְרַב בְּכֹל מִדַּעַם מְסָאָב אוֹ בְנִבְלַת חַיְתָא מְסָאָבָא אוֹ בְּנִבְלַת בְּעִירָא מְסָאָבָא אוֹ בְּנִבְלַת רִחֲשָׁא מְסָאָב וִיהֵי מְכַסָּא מִנֵּיהּ וְהוּא מְסָאָב וְחָב:
@88 אוֹ אֲרֵי יִקְרַב בְּסוֹאֲבַת אֱנָשָׁא לְכָל סוֹבְתֵיהּ דִּי יִסְתָּאַב בַּהּ וִיהֵי מְכַסָּא מִנֵּיהּ וְהוּא יָדַע וְחָב:
@89 אוֹ אֱנַשׁ אֲרֵי יְקַיֵּם לְפָרָשָׁא בְסִפְוָן לְאַבְאָשָׁא אוֹ לְאוֹטָבָא לְכֹל דִּי יְפָרֵשׁ אֱנָשָׁא בְּקִיּוּם וִיהֵי מְכַסָּא מִנֵּיהּ וְהוּא יָדַע וְחָב לַחֲדָא מֵאִלֵּין:
@90 וִיהֵי אֲרֵי יֵחוֹב לַחֲדָא מֵאִלֵּין וִיוַדִּי דִּי חָב עֲלַהּ:
@91 וְיַיְתִי יָת אַשְׁמֵיהּ קֳדָם יְיָ עַל חוֹבְתֵיהּ דִּי חָב נְקוּבְתָא מִן עָנָא אִמְּרָתָא אוֹ צְפִירַת עִזִּין לְחַטָאתָא וִיכַפֵּר עֲלוֹהִי כַּהֲנָא מֵחוֹבְתֵיהּ:
@92 וְאִם לָא תִמְטֵי יְדֵיהּ כְּמִסַּת שֵׂיתָא וְיַיְתִי יָת חוֹבְתֵיהּ דִּי חָב תַּרְתֵּין שַׁפְנִינִין אוֹ תְרֵין בְּנֵי יוֹנָה קֳדָם יְיָ חַד לְחַטָּאתָא וְחַד לַעֲלָתָא:
@93 וְיַיְתִי יָתְהוֹן לְוָת כַּהֲנָא וִיקָרֵב יָת דִּי לְחַטָּאתָא קַדְמֵיתָא וְיִמְלוֹק יָת רֵישֵׁיהּ מִלָּקֳבֵל קְדָלֵיהּ וְלָא יַפְרֵשׁ:
@94 וְיַדִּי מִדְּמָא דְחַטָּאתָא עַל כֹּתֶל מַדְבְּחָא וּדְאִשְׁתָּאַר בִּדְמָא יִתִּמְצֵי לִיסוֹדָא דְמַדְבְּחָא חַטָּאתָא הוּא:
@95 וְיָת תִּנְיָנָא יַעְבֵּד עֲלָתָא כִּדְחָזֵי וִיכַפֵּר עֲלוֹהִי כַּהֲנָא מֵחוֹבְתֵיהּ דִּי חָב וְיִשְׁתְּבֵק לֵיהּ:
@96 וְאִם לָא תַדְבֵּק יְדֵיהּ לְתַּרְתֵּין שַׁפְנִינִין אוֹ לִתְרֵין בְּנֵי יוֹנָה וְיַיְתִי יָת קֻרְבָּנֵיהּ דִּי חָב חַד מִן עַסְרָא בִתְלַת סְאִין סֻלְתָּא לְחַטָּאתָא לָא יְשַׁוִּי עֲלַהּ מִשְׁחָא וְלָא יִתֵּן עֲלַהּ לְבֻנְתָּא אֲרֵי חַטָּאתָא הִיא:
@97 וְיַיְתִנַּהּ לְוָת כַּהֲנָא וְיִקְמוֹץ כַּהֲנָא מִנַּהּ מְלֵי קֻמְצֵיהּ יָת אִדְכַּרְתַּהּ וְיַסֵּק לְמַדְבְּחָא עַל קֻרְבָּנַיָּא דַיְיָ חַטָּאתָא הִיא:
@98 וִיכַפֵּר עֲלוֹהִי כַּהֲנָא עַל חוֹבְתֵיהּ דִּי חָב מֵחֲדָא מֵאִלֵּין וְיִשְׁתְּבֵק לֵיהּ וּתְהֵי לְכַהֲנָא כְּמִנְחָתָא:
@99 וּמַלִּיל יְיָ עִם משֶׁה לְמֵימָר:
@100 אֱנַשׁ אֲרֵי יְשַׁקַּר שְׁקַר וְיֵחוֹב בְּשָׁלוּ מִקוּדְשַׁיָּא דַיְיָ וְיַיְתִי יָת אַשְׁמֵיהּ קֳדָם יְיָ דְכַר שְׁלִים מִן עָנָא בְּפֻרְסָנֵיהּ כְּסַף סִלְעִין בְּסִלְעֵי קוּדְשָׁא לַאֲשָׁמָא:
@101 וְיָת דִּי חָב מִן קוּדְשָׁא יְשַׁלֵּם וְיָת חֻמְשֵׁיהּ יוֹסֵף עֲלוֹהִי וְיִתֵּן יָתֵיהּ לְכַהֲנָא וְכַהֲנָא יְכַפֵּר עֲלוֹהִי בְּדִכְרָא דַאֲשָׁמָא וְיִשְׁתְּבֵק לֵיהּ:
@102 וְאִם אֱנַשׁ אֲרֵי יֵחוֹב וְיַעְבֵּד חֲדָא מִכָּל פִּקּוֹדַיָּא דַיְיָ דִּי לָא כָשְׁרִין לְאִתְעֲבָדָא וְלָא יָדַע וְיֵחוֹב וִיקַבֵּל חוֹבֵיהּ:
@103 וְיַיְתִי דְּכַר שְׁלִים מִן עָנָא בְּפֻרְסָנֵיהּ לַאֲשָׁמָא לְוָת כַּהֲנָא וִיכַפֵּר עֲלוֹהִי כַהֲנָא עַל שָׁלוּתֵיהּ דְּאִשְׁתְּלִי וְהוּא לָא יָדַע וְיִשְׁתְּבֵק לֵיהּ:
@104 אֲשָׁמָא הוּא עַל חוֹבְתֵיהּ דְּהוּא חָב אֲשָׁמָא יְקָרֵב קֳדָם יְיָ:
@105 וּמַלִּיל יְיָ עִם משֶׁה לְמֵימָר:
@106 אֱנַשׁ אֲרֵי יֵחוֹב וִישַׁקַּר שְׁקַר קֳדָם יְיָ וִיכַדֵב בְּחַבְרֵיהּ בּפִקְּדוֹנָא אוֹ בְשֻׁתָּפוּת יְדָא אוֹ בִגְזֵלָא אוֹ אַנִּיס יָת חַבְרֵיהּ:
@107 אוֹ אַשְׁכַּח אֲבֵדְתָּא וִיכַדֵּב בַּהּ וְאִשְׁתְּבַע עַל שִׁקְרָא עַל חֲדָא מִכֹּל דִּי יַעְבֵּד אֱנָשָׁא לְמֵיחַב בְּהֵן:
@108 וִיהֵי אֲרֵי יֶחֱטֵי וְיֵחוֹב וְיָתֵב יָת גְּזֵלָא דִּי גְזַל אוֹ יָת עֻשְׁקָא דִּי עֲשַׁק אוֹ יָת פִּקְּדוֹנָא דִּי אִתְפָּקַּד לְוָתֵיהּ אוֹ יָת אֲבֵדְתָּא דִּי אַשְׁכַּח:
@109 אוֹ מִכֹּל דִּי יִשְׁתְּבַע עֲלוֹהִי לְשִׁקְרָא וִישַׁלֵּם יָתֵיהּ בְּרֵישֵׁיהּ וְחֻמְשֵׁיהּ יוֹסֵף עֲלוֹהִי לְדִי הוּא דִילֵיהּ יִתְּנִנֵּיהּ בְּיוֹמָא דְחוֹבְתֵיהּ:
@110 וְיָת אַשְׁמַהּ יַיְתִי לָקֳדָם יְיָ דְּכַר שְׁלִים מִן עָנָא בְּפֻרְסָנֵיהּ לַאֲשָׁמָא לְוָת כַּהֲנָא:
@111 וִיכַפֵּר עֲלוֹהִי כַהֲנָא קֳדָם יְיָ וְיִשְׁתְּבֵק לֵיהּ עַל חֲדָא מִכֹּל דִּי יַעְבֵּד לְמֵיחַב בַּהּ:

@1 **ויקרא אל משה.** לְכָל דִּבְּרוֹת וּלְכָל אֲמִירוֹת וּלְכָל צִוּוּיִים קָדְמָה קְרִיאָה, לְשׁוֹן חִבָּה, לָשׁוֹן שֶׁמַּלְאֲכֵי הַשָּׁרֵת מִשְׁתַּמְּשִׁין בּוֹ, שֶׁנֶּאֱמַר וְקָרָא זֶה אֶל זֶה (ישעיהו ו'), אֲבָל לִנְבִיאֵי אֻמּוֹת הָעוֹלָם נִגְלָה עֲלֵיהֶן בִּלְשׁוֹן עֲרָאִי וְטֻמְאָה, שֶׁנֶּאֱמַר וַיִּקָּר אֱלֹהִים אֶל בִּלְעָם (במדבר כ"ג):
@1 **ויקרא אל משה.** הַקּוֹל הוֹלֵךְ וּמַגִּיעַ לְאָזְנָיו וְכָל יִשְֹרָאֵל לֹא שׁוֹמְעִין; יָכוֹל אַף לְהַפְסָקוֹת הָיְתָה קְרִיאָה, תַּ"ל וַיְדַבֵּר — לְדִבּוּר הָיְתָה קְרִיאָה וְלֹא לְהַפְסָקוֹת, וּמֶה הָיוּ הַפְסָקוֹת מְשַׁמְּשׁוֹת? לִתֵּן רֶוַח לְמֹשֶׁה לְהִתְבּוֹנֵן בֵּין פָּרָשָׁה לְפָרָשָׁה וּבֵין עִנְיָן לְעִנְיָן; קַ"וָ לְהֶדְיוֹט הַלּוֹמֵד מִן הַהֶדְיוֹט:
@1 **אליו.** לְמַעֵט אֶת אַהֲרֹן; רַ' יְהוּדָה אוֹמֵר י"ג דִּבְּרוֹת נֶאֶמְרוּ בַּתּוֹרָה לְמֹשֶׁה וּלְאַהֲרֹן וּכְנֶגְדָּן נֶאֶמְרוּ י"ג מִעוּטִין, לְלַמֶּדְךָ שֶׁלֹּא לְאַהֲרֹן נֶאֶמְרוּ אֶלָּא לְמֹשֶׁה שֶׁיֹּאמַר לְאַהֲרֹן, וְאֵלּוּ הֵן י"ג מִעוּטִין: לְדַבֵּר אִתּוֹ, מִדַּבֵּר אֵלָיו, וַיְדַבֵּר אֵלָיו (במדבר ז'), וְנוֹעַדְתִּי לְךָ (שמות כ"ה) — כֻּלָּן בְּתוֹרַת כֹּהֲנִים. יָכוֹל יִשְׁמְעוּ אֶת קוֹל הַדִּבּוּר תַּ"לֹ קוֹל לוֹ, קוֹל אֵלָיו, מֹשֶׁה שׁוֹמֵעַ וְכָל יִשְֹרָאֵל לֹא שָׁמְעוּ:
@1 **מאהל מועד.** מְלַמֵּד שֶׁהָיָה הַקּוֹל נִפְסָק וְלֹא הָיָה יוֹצֵא חוּץ לָאֹהֶל; יָכוֹל מִפְּנֵי שֶׁהַקּוֹל נָמוּךְ, תַּ"ל אֶת הַקּוֹל, מַהוּ הַקּוֹל? הוּא הַקּוֹל הַמְפֹרָשׁ בִּתְהִלִּים קוֹל ה' בַּכֹּחַ קוֹל ה' בֶּהָדָר קוֹל ה' שֹׁבֵר אֲרָזִים (תהילים כ"ט), אִם כֵּן לָמָּה נֶאֱמַר מֵאֹהֶל מוֹעֵד? מְלַמֵּד שֶׁהָיָה הַקּוֹל נִפְסָק. כַּיּוֹצֵא בּוֹ וְקוֹל כַּנְפֵי הַכְּרוּבִים נִשְׁמַע עַד הֶחָצֵר הַחִיצֹנָה (יחזקאל י'), יָכוֹל שֶׁהַקּוֹל נָמוּךְ תַּ"ל כְּקוֹל אֵל שַׁדַּי בְּדַבְּרוֹ, אִם כֵּן לָמָּה נֶאֱמַר עַד הֶחָצֵר הַחִיצֹנָה? שֶׁכֵּוָּן שֶׁמַּגִּיעַ שָׁם הָיָה נִפְסָק:
@1 **מאהל מועד לאמר.** יָכוֹל מִכָּל הַבַּיִת, תַּ"ל מֵעַל הַכַּפֹּרֶת, יָכוֹל מֵעַל הַכַּפֹּרֶת כֻּלָּהּ, תַּ"ל מִבֵּין שְׁנֵי הַכְּרֻבִים:
@1 **לאמר.** צֵא וֶאֱמֹר לָהֶם דִּבְרֵי כִּבּוּשִׁין — בִּשְׁבִילְכֶם הוּא נִדְבָּר עִמִּי; שֶׁכֵּן מָצִינוּ שֶׁכָּל ל"ח שָׁנָה שֶׁהָיוּ יִשְֹרָאֵל בַּמִּדְבָּר כִּמְנֻדִּים, מִן הַמְרַגְּלִים וָאֵילַךְ, לֹא נִתְיַחֵד הַדִּבּוּר עִם מֹשֶׁה, שֶׁנֶּאֱמַר וַיְהִי כַאֲשֶׁר תַּמּוּ כָּל אַנְשֵׁי הַמִּלְחָמָה לָמוּת … וַיְדַבֵּר ה' אֵלַי לֵאמֹר (דברים ב'), אֵלַי הָיָה הַדִּבּוּר. דָּ"אַ צֵא וֶאֱמֹר לָהֶן דְּבָרַי וַהֲשִׁיבֵנִי אִם יְקַבְּלוּם, כְּמָה שֶׁנֶּאֱמַר וַיָּשֶׁב מֹשֶׁה אֶת דִּבְרֵי הָעָם וְגוֹ' (שמות י"ט):
@2 **אדם כי יקריב מכם.** כְּשֶׁיַּקְרִיב; בְּקָרְבְּנוֹת נְדָבָה דִּבֵּר הָעִנְיָן:
@2 **אדם.** לָמָּה נֶאֱמַר? מָה אָדָם הָרִאשׁוֹן לֹא הִקְרִיב מִן הַגָּזֵל — שֶׁהַכֹּל הָיָה שֶׁלּוֹ — אַף אַתֶּם לֹא תַּקְרִיבוּ מִן הַגָּזֵל (ויקרא רבה):
@2 **הבהמה.** יָכוֹל אַף חַיָּה בִּכְלָל, תַּ"לֹ בָּקָר וָצֹאן:
@2 **מן הבהמה.** וְלֹא כֻּלָּהּ — לְהוֹצִיא אֶת הָרוֹבֵעַ וְאֶת הַנִּרְבָּע:
@2 **מן הבקר.** לְהוֹצִיא אֶת הַנֶּעֱבָד:
@2 **מן הצאן.** לְהוֹצִיא אֶת הַמֻּקְצָה:
@2 **ומן הצאן.** לְהוֹצִיא אֶת הַנּוֹגֵחַ שֶׁהֵמִית; כְּשֶׁהוּא אוֹמֵר לְמַטָּה מִן הָעִנְיָן מִן הַבָּקָר — שֶׁאֵין תַּ"ל — לְהוֹצִיא אֶת הַטְּרֵפָה (ספרא):
@2 **תקריבו.** מְלַמֵּד שֶׁשְּׁנַיִם מִתְנַדְּבִים עוֹלָה בְּשֻׁתָּפוּת:
@2 **קרבנכם.** מְלַמֵּד שֶׁהִיא בָּאָה נִדְבַת צִבּוּר, הִיא עוֹלַת קַיִץ הַמִּזְבֵּחַ, הַבָּאָה מִן הַמּוֹתָרוֹת (שבועות י"ב):
@3 **זכר.** וְלֹא נְקֵבָה; כְּשֶׁהוּא אוֹמֵר זָכָר לְמַטָּה — שֶׁאֵין תַּ"לֹ — זָכָר וְלֹא טֻמְטוּם וְאַנְדְּרוֹגִינוֹס:
@3 **תמים.** בְּלֹא מוּם:
@3 **אל פתח אהל מועד.** מְטַפֵּל בַּהֲבָאָתוֹ עַד הָעֲזָרָה; מַהוּ אוֹמֵר יַקְרִיב יַקְרִיב? אֲפִלּוּ נִתְעָרְבָה עוֹלַת רְאוּבֵן בְּעוֹלַת שִׁמְעוֹן יַקְרִיב כָּל אֶחָד לְשֵׁם מִי שֶׁהוּא, וְכֵן עוֹלָה בְּחֻלִּין, יִמָּכְרוּ הַחֻלִּין לְצָרְכֵי עוֹלוֹת, וַהֲרֵי הֵן כֻּלָּן עוֹלוֹת, וְתִקְרַב כָּל אֶחָד לְשֵׁם מִי שֶׁהוּא; יָכוֹל אֲפִלּוּ נִתְעָרְבָה בִּפְסוּלִין אוֹ בְּשֶׁאֵינוֹ מִינוֹ, תַּלְמוּד לוֹמַר "יַקְרִיבֶנּוּ" (ספרא):
@3 **יקריב אתו.** מְלַמֵּד שֶׁכּוֹפִין אוֹתוֹ, יָכוֹל בְּעַל כָּרְחוֹ, תַּלְמוּד לוֹמַר "לִרְצוֹנוֹ", הָא כֵּיצַד? כּוֹפִין אוֹתוֹ עַד שֶׁיֹּאמַר רוֹצֶה אֲנִי (שם):
@3 **לפני ה' וסמך.** אֵין סְמִיכָה בְּבָמָה (שם):
@4 **על ראש העלה.** לְהָבִיא עוֹלַת חוֹבָה לִסְמִיכָה וּלְהָבִיא עוֹלַת הַצֹּאן (שם):
@4 **העלה.** פְּרָט לְעוֹלַת הָעוֹף (שם):
@4 **ונרצה לו.** עַל מָה הוּא מְרַצֶּה לוֹ? אִם תֹּאמַר עַל כָּרֵתוֹת וּמִיתוֹת בֵּית דִּין אוֹ מִיתָה בִּידֵי שָׁמַיִם אוֹ מַלְקוּת, הֲרֵי עָנְשָׁן אָמוּר, הָא אֵינוֹ מְרַצֶּה אֶלָּא עַל עֲשֵֹה וְעַל לָאו שֶׁנִּתַּק לַעֲשֵֹה (שם):
@5 **ושחט והקריבו, הכהנים.** מִקַּבָּלָה וָאֵילַךְ מִצְוַת כְּהֻנָּה — לִמֵּד עַל הַשְּׁחִיטָה שֶׁכְּשֵׁרָה בְּזָר (שם):
@5 **לפני ה'.** בַּעֲזָרָה:
@5 **והקריבו.** זוֹ קַבָּלָה, שֶׁהִיא הָרִאשׁוֹנָה, וּמַשְׁמָעָהּ לְשׁוֹן הוֹלָכָה, לָמַדְנוּ שְׁתֵּיהֶן:
@5 **בני אהרן.** יָכוֹל חֲלָלִים, תַּ"ל הַכֹּהֲנִים:
@5 **את הדם וזרקו את הדם.** מַה תַּ"ל דָּם דָּם שְׁנֵי פְּעָמִים? לְהָבִיא אֶת שֶׁנִּתְעָרֵב בְּמִינוֹ אוֹ בְּשֶׁאֵינוֹ מִינוֹ, יָכוֹל אַף בִּפְסוּלִים אוֹ בְּחַטָּאוֹת הַפְּנִימִיּוֹת אוֹ בְּחַטָּאוֹת הַחִיצוֹנִיּוֹת, שֶׁאֵלּוּ לְמַעְלָה וְהִיא לְמַטָּה, תַּ"ל בְּמָקוֹם אַחֵר דָּמוֹ (זבחים פ"א):
@5 **וזרקו.** עוֹמֵד לְמַטָּה וְזוֹרֵק מִן הַכְּלִי לְכֹתֶל הַמִּזְבֵּחַ לְמַטָּה מִחוּט הַסִּקְרָא כְּנֶגֶד הַזָּוִיּוֹת, לְכָךְ נֶאֱמַר סָבִיב — שֶׁיְּהֵא הַדָּם נָתוּן בְּאַרְבַּע רוּחוֹת הַמִּזְבֵּחַ; אוֹ יָכוֹל יַקִּיפֶנּוּ כְּחוּט, תַּ"ל וְזָרְקוּ וְאִי אֶפְשַׁר לְהַקִּיף בִּזְרִיקָה, אִי וְזָרְקוּ יָכוֹל בִּזְרִיקָה אַחַת, תַּ"ל סָבִיב, הָא כֵּיצַד? נוֹתֵן שְׁתֵּי מַתָּנוֹת שֶׁהֵן אַרְבַּע (ספרא):
@5 **אשר פתח אהל מועד.** וְלֹא בִּזְמַן שֶׁהוּא מְפֹרָק (שם):
@6 **והפשיט וגו'.** מַה תַּלְמוּד לוֹמַר הָעוֹלָה? לְרַבּוֹת אֶת כָּל הָעוֹלוֹת לְהֶפְשֵׁט וְנִתּוּחַ:
@6 **אתה לנתחיה.** וְלֹא נְתָחֶיהָ לִנְתָחִים (ספרא):
@7 **ונתנו … אש.** אַעַ"פִּי שֶׁהָאֵשׁ יוֹרֶדֶת מִן הַשָּׁמַיִם מִצְוָה לְהָבִיא מִן הַהֶדְיוֹט (שם):
@7 **בני אהרן הכהן.** כְּשֶׁהוּא בְּכִהוּנוֹ, הָא אִם עָבַד בְּבִגְדֵי כֹּהֵן הֶדְיוֹט עֲבוֹדָתוֹ פְּסוּלָה:
@8 **בני אהרן הכהנים.** כְּשֶׁהֵם בְּכִהוּנָם, הָא כֹּהֵן הֶדְיוֹט שֶׁעָבַד בִּשְׁמוֹנָה בְּגָדִים עֲבוֹדָתוֹ פְּסוּלָה (זבחים י"ח):
@8 **את הנתחים את הראש.** לְפִי שֶׁאֵין הָרֹאשׁ בִּכְלַל הֶפְשֵׁט, שֶׁכְּבָר הֻתַּז בִּשְׁחִיטָה, לְפִיכָךְ הֻצְרַךְ לִמְנוֹתוֹ לְעַצְמוֹ (חולין כ"ז):
@8 **ואת הפדר.** לָמָּה נֶאֱמַר? לְלַמֶּדְךָ שֶׁמַּעֲלֵהוּ עִם הָרֹאשׁ וּמְכַסֶּה בּוֹ אֶת בֵּית הַשְּׁחִיטָה, וְזֶהוּ דֶּרֶךְ כָּבוֹד שֶׁל מַעְלָה (שם):
@8 **אשר על המזבח.** שֶׁלֹּא יִהְיוּ הַגְּזִירִין יוֹצְאִין חוּץ לַמַּעֲרָכָה (ספרא):
@9 **עלה.** לְשֵׁם עוֹלָה יַקְטִירֶנּוּ:
@9 **אשה.** כְּשֶׁיִּשְׁחֲטֶנּוּ יְהֵי שׁוֹחֲטוֹ לְשֵׁם הָאֵשׁ; וְכָל אִשֶּׁה לְשׁוֹן אֵשׁ, פוש"ייר בְּלַעַז:
@9 **ניחוח.** נַחַת רוּחַ לְפָנַי, שֶׁאָמַרְתִּי וְנַעֲשָֹה רְצוֹנִי (שם):
@10 **ואם מן הצאן.** וי"ו מוֹסִיף עַל עִנְיָן רִאשׁוֹן, וְלָמָּה הֻפְסַק? לִתֵּן רֶוַח לְמֹשֶׁה לְהִתְבּוֹנֵן בֵּין פָּרָשָׁה לְפָרָשָׁה (שם):
@10 **מן הצאן, מן הכשבים, מן העזים.** הֲרֵי אֵלּוּ ג' מִעוּטִין — פְּרָט לְזָקֵן וּלְחוֹלֶה וְלִמְזֹהָם (שם):
@11 **על ירך המזבח.** עַל צַד הַמִּזְבֵּחַ:
@11 **צפנה לפני ה'.** וְאֵין צָפוֹן בְּבָמָה (שם):
@14 **מן העוף.** וְלֹא כָּל הָעוֹף; לְפִי שֶׁנֶּאֱמַר תָּמִים זָכָר בַּבָּקָר בַּכְּשָׂבִים וּבָעִזִּים — תַּמּוּת וְזַכְרוּת בִּבְהֵמָה וְאֵין תַּמּוּת וְזַכְרוּת בְּעוֹפוֹת — יָכוֹל אַף מְחֻסַּר אֵבֶר, תַּ"ל מִן הָעוֹף (שם):
@14 **תרים.** גְּדוֹלִים וְלֹא קְטַנִּים:
@14 **בני יונה.** קְטַנִּים וְלֹא גְּדוֹלִים:
@14 **מן התרים או מן בני היונה.** פְּרָט לִתְחִלַּת הַצִּהוּב שֶׁבָּזֶה וְשֶׁבָּזֶה שֶׁהוּא פָּסוּל, שֶׁגָּדוֹל הוּא אֵצֶל בְּנֵי יוֹנָה וְקָטָן אֵצֶל תּוֹרִים (חולין כ"ב):
@15 **והקריבו.** אֲפִלּוּ פְּרֵדָה אַחַת יָבִיא (ספרא):
@15 **הכהן, ומלק.** אֵין מְלִיקָה בִּכְלִי אֶלָּא בְּעַצְמוֹ שֶׁל כֹּהֵן, קוֹצֵץ בְּצִפָּרְנוֹ מִמּוּל הָעֹרֶף וְחוֹתֵךְ מַפְרַקְתּוֹ עַד שֶׁמַּגִּיעַ לַסִּימָנִין וְקוֹצְצָן (שם):
@15 **ונמצה דמו.** לְשׁוֹן מִיץ אַפַּיִם (משלי ל'), כִּי אָפֵס הַמֵּץ (ישעיהו ט"ז), כּוֹבֵשׁ בֵּית הַשְּׁחִיטָה עַל קִיר הַמִּזְבֵּחַ וְהַדָּם מִתְמַצֶּה וְיוֹרֵד (זבחים ס"ה):
@15 **ומלק, והקטיר, ונמצה.** אֶ"לֹ כֵּן מֵאַחַר שֶׁהוּא מַקְטִיר הוּא מוֹצֶה? אֶלָּא מַה הַקְטָרָה הָרֹאשׁ בְּעַצְמוֹ וְהַגּוּף בְּעַצְמוֹ, אַף מְלִיקָה כֵּן. וּפְשׁוּטוֹ שֶׁל מִקְרָא מְסֹרָס הוּא — וּמָלַק וְהִקְטִיר, וְקֹדֶם הַקְטָרָה וְנִמְצָה דָמוֹ כְּבָר:
@16 **מראתו.** מְקוֹם הָרְעִי, זֶה הַזֶּפֶק (ספרא):
@16 **בנצתה.** עִם בְּנֵי מֵעֶיהָ, וְנוֹצָה לְשׁוֹן דָּבָר הַמָּאוּס, כְּמוֹ כִּי נָצוּ גַּם נָעוּ (איכה ד'), וְזֶהוּ שֶׁתִּרְגֵּם אֻנְקְלוֹס בְּאוּכְלֵיהּ; וְזֶהוּ מִדְרָשׁוֹ שֶׁל אַבָּא יוֹסֵי בֶּן חָנָן שֶׁאָמַר נוֹטֵל אֶת הַקֻּרְקְבָן עִמָּהּ; וְרַבּוֹתֵינוּ זִ"לִ אָמְרוּ קוֹדֵר סְבִיב הַזֶּפֶק בְּסַכִּין כְּעֵין אֲרֻבָּה וְנוֹטְלוֹ עִם הַנּוֹצָה שֶׁעַל הָעוֹר (ספרא); בְּעוֹלַת בְּהֵמָה שֶׁאֵינָהּ אוֹכֶלֶת אֶלָּא בְּאֵבוּס בְּעָלֶיהָ, נֶאֱמַר וְהַקֶּרֶב וְהַכְּרָעַיִם יִרְחַץ בַּמָּיִם וְהִקְטִיר, וּבָעוֹף שֶׁנָּזוֹן מִן הַגָּזֵל, נֶאֱמַר וְהִשְלִיךְ אֶת הַמֵּעַיִם, שֶׁאָכַל מִן הַגָּזֵל (ויקרא רבה ג'):
@16 **אצל המזבח קדמה.** בְּמִזְרָחוֹ שֶׁל כֶּבֶשׁ (ספרא):
@16 **אל מקום הדשן.** מָקוֹם שֶׁנּוֹתְנִין שָׁם תְּרוּמַת הַדֶּשֶׁן בְּכָל בֹּקֶר וְדִשּׁוּן מִזְבֵּחַ הַפְּנִימִי וְהַמְּנוֹרָה, וְכֻלָּם נִבְלָעִים שָׁם בִּמְקוֹמָן:
@17 **ושסע.** אֵין שִׁסּוּעַ אֶלָּא בַּיָּד, וְכֵן הוּא אוֹמֵר בְּשִׁמְשׁוֹן וַיְשַׁסְּעֵהוּ כְּשַׁסַּע הַגְּדִי וְגוֹ' (שופטים י"ד):
@17 **בכנפיו.** עִם כְּנָפָיו — אֵינוֹ צָרִיךְ לִמְרֹט כַּנְפֵי נוֹצָתוֹ:
@17 **בכנפיו.** נוֹצָה מַמָּשׁ; וַהֲלֹא אֵין לְךָ הֶדְיוֹט שֶׁמֵּרִיחַ רֵיחַ כְּנָפַיִם נִשְֹרָפִים וְאֵין נַפְשׁוֹ קָצָה עָלָיו, וְלָמָּה אָמַר הַכָּתוּב יַקְרִיב? כְּדֵי שֶׁיְּהֵא הַמִּזְבֵּחַ שָֹבֵעַ וּמְהֻדָּר בְּקָרְבָּנוֹ שֶׁל עָנִי (ויק"ר ג'):
@17 **לא יבדיל.** אֵינוֹ מְפָרְקוֹ לְגַמְרֵי, לִשְׁתֵּי חֲתִיכוֹת, אֶלָּא קוֹרְעוֹ מִגַּבּוֹ; נֶאֱמַר בָּעוֹף רֵיחַ נִיחוֹחַ וְנֶאֱמַר בַּבְּהֵמָה רֵיחַ נִיחוֹחַ, לוֹמַר לְךָ אֶחָד הַמַּרְבֶּה וְאֶחָד הַמַּמְעִיט וּבִלְבַד שֶׁיְּכַוֵּן אֶת לִבּוֹ לַשָּׁמַיִם (ספרא):
@18 **ונפש כי תקריב.** לֹא נֶאֱמַר נֶפֶשׁ בְּכָל קָרְבְּנוֹת נְדָבָה אֶלָּא בַּמִּנְחָה, מִי דַּרְכּוֹ לְהִתְנַדֵּב מִנְחָה? עָנִי. אָמַר הַקָּבָּ"ה, מַעֲלֶה אֲנִי עָלָיו כְּאִלּוּ הִקְרִיב נַפְשׁוֹ (מנחות ק"ד):
@18 **סלת יהיה קרבנו.** הָאוֹמֵר הֲרֵי עָלַי מִנְחָה סְתָם, מֵבִיא מִנְחַת סֹלֶת, שֶׁהִיא הָרִאשׁוֹנָה שֶׁבַּמְּנָחוֹת וְנִקְמֶצֶת כְּשֶׁהִיא סֹלֶת, כְּמוֹ שֶׁמְּפֹרָשׁ בָּעִנְיָן; לְפִי שֶׁנֶּאֶמְרוּ כָּאן חֲמִשָּׁה מִינֵי מְנָחוֹת, וְכֻלָּן בָּאוֹת אֲפוּיוֹת קֹדֶם קְמִיצָה חוּץ מִזּוֹ, לְכָךְ קְרוּיָה מִנְחַת סֹלֶת:
@18 **סלת.** אֵין סֹלֶת אֶלָּא מִן הַחִטִּין, שֶׁנֶּאֱמַר סֹלֶת חִטִּים (שמות כ"ט), וְאֵין מִנְחָה פְּחוּתָה מֵעִשָּׂרוֹן, שֶׁנֶּאֱמַר וְעִשָּׂרוֹן סֹלֶת … לְמִנְחָה (ויקרא י"ד) — עִשָּׂרוֹן לְכָל מִנְחָה:
@18 **ויצק עליה שמן.** עַל כֻּלָּהּ:
@18 **ונתן עליה לבנה.** עַל מִקְצָתָהּ — מַנִּיחַ קֹמֶץ לְבוֹנָה עָלֶיהָ לְצַד אֶחָד. וּמָה רָאִיתָ לוֹמַר כֵּן? שֶׁאֵין רִבּוּי אַחַר רִבּוּי בַּתּוֹרָה אֶלָּא לְמַעֵט; דָּ"אַ: שֶׁמֶן עַל כֻּלָּהּ, מִפְּנֵי שֶׁהוּא נִבְלָל עִמָּהּ וְנִקְמָץ עִמָּהּ, כְּמוֹ שֶׁנֶּאֱמַר מִסָּלְתָּהּ וּמִשַּׁמְנָהּ, וּלְבוֹנָה עַל מִקְצָתָהּ, שֶׁאֵינָהּ נִבְלֶלֶת עִמָּהּ וְלֹא נִקְמֶצֶת עִמָּהּ, שֶׁנֶּאֱמַר עַל כָּל לְבֹנָתָהּ, שֶׁלְּאַחַר שֶׁקָּמַץ מְלַקֵּט אֶת הַלְּבוֹנָה כֻּלָּהּ מֵעָלֶיהָ וּמַקְטִירָהּ (ספרא):
@18 **ויצק, ונתן, והביאה.** מְלַמֵּד שֶׁיְּצִיקָה וּבְלִילָה כְּשֵׁרִים בְּזָר (שם):
@19 **הכהנים וקמץ.** מִקְּמִיצָה וָאֵילָךְ מִצְוַת כְּהֻנָּה (שם):
@19 **וקמץ משם.** מִמָּקוֹם שֶׁרַגְלֵי הַזָּר עוֹמְדוֹת; לְלַמֶּדְךָ שֶׁהַקְּמִיצָה כְּשֵׁרָה בְּכָל מָקוֹם בָּעֲזָרָה, אַף בְּי"א אַמָּה שֶׁל מְקוֹם דְּרִיסַת רַגְלֵי יִשְֹרָאֵל (יומא ט"ז):
@19 **מלא קמצו.** יָכוֹל מְבֹרָץ — מְבַצְבֵּץ וְיוֹצֵא לְכָל צַד, תַּ"לֹ בְּמָקוֹם אַחֵר וְהֵרִים מִמֶּנּוּ בְּקֻמְצוֹ (ויקרא ו') — לֹא יְהֵא כָּשֵׁר אֶלָּא מַה שֶּׁבְּתוֹךְ הַקֹּמֶץ, אִי בְּקֻמְצוֹ יָכוֹל חָסֵר, תַּ"לֹ מְלֹא, הָא כֵּיצַד? חוֹפֶה שְׁלוֹשׁ אֶצְבְּעוֹתָיו עַל פַּס יָדוֹ, וְזֶהוּ קֹמֶץ בְּמַשְׁמַע לָשׁוֹן הָעִבְרִית (מנחות י"א):
@19 **על כל לבנתה.** לְבַד כָּל הַלְּבוֹנָה יְהֵא הַקֹּמֶץ מָלֵא:
@19 **לבנתה והקטיר.** אַף הַלְּבוֹנָה בְּהַקְטָרָה:
@19 **מלא קמצו מסלתה ומשמנה.** הָא אִם קָמַץ וְעָלָה בְּיָדוֹ גַּרְגֵּר מֶלַח אוֹ קֹרֶט לְבוֹנָה פְּסוּלָה (שם ו'):
@19 **אזכרתה.** הַקֹּמֶץ הָעוֹלֶה לְגָבוֹהַּ הוּא זִכְרוֹן הַמִּנְחָה — שֶׁבּוֹ נִזְכָּר בְּעָלֶיהָ לְטוֹבָה וּלְנַחַת רוּחַ:
@20 **לאהרן ולבניו.** כֹּהֵן גָּדוֹל נוֹטֵל חֵלֶק בָּרֹאשׁ שֶׁלֹּא בְּמַחֲלֹקֶת וְהַהֶדְיוֹט בְּמַחֲלֹקֶת (ספרא):
@20 **קדש קדשים.** הִיא לָהֶם:
@20 **מאשי ה'.** אֵין לָהֶם חֵלֶק בָּהּ אֶלָּא לְאַחַר מַתְּנוֹת הָאִשִּׁים (שם):
@21 **וכי תקריב וגו'.** שֶׁאָמַר הֲרֵי עָלַי מִנְחַת מַאֲפֵה תַּנּוּר; וְלִמֵּד הַכָּתוּב שֶׁיָּבִיא אוֹ חַלּוֹת אוֹ רְקִיקִין, הַחַלּוֹת בְּלוּלוֹת וְהָרְקִיקִין מְשׁוּחִין; וְנֶחְלְקוּ רַבּוֹתֵינוּ בִּמְשִׁיחָתָן, יֵשׁ אוֹמְרִים מוֹשְׁחָן וְחוֹזֵר וּמוֹשְׁחָן עַד שֶׁכָּלֶה כָּל הַשֶּׁמֶן שֶׁבַּלֹּג — שֶׁכָּל הַמְּנָחוֹת טְעוּנוֹת לֹג שֶׁמֶן — וְיֵשׁ אוֹמְרִים מוֹשְׁחָן כְּמִין "כִי" וּשְׁאָר הַשֶּׁמֶן נֶאֱכָל בִּפְנֵי עַצְמוֹ לַכֹּהֲנִים (מנחות ע"ה); מַה תַּ"ל בַּשֶּׁמֶן בַּשֶּׁמֶן שְׁנֵי פְּעָמִים? לְהַכְשִׁיר שֶׁמֶן שֵׁנִי וּשְׁלִישִׁי הַיּוֹצֵא מִן הַזֵּיתִים, וְאֵין צָרִיךְ שֶׁמֶן רִאשׁוֹן אֶלָּא לַמְּנוֹרָה שֶׁנֶּאֱמַר בּוֹ זָךְ (שמות כ"ז), וְשָׁנִינוּ בִּמְנָחוֹת כָּל הַמְּנָחוֹת הָאֲפוּיוֹת לִפְנֵי קְמִיצָתָן וְנִקְמָצוֹת עַל יְדֵי פְּתִיתָה, כֻּלָּן בָּאוֹת עֶשֶֹר עֶשֶֹר חַלּוֹת, וְהָאָמוּר בָּה רְקִיקִין בָּאָה עֲשָׂרָה רְקִיקִין (מנחות ע"ו):
@22 **ואם מנחה על המחבת.** שֶׁאָמַר הֲרֵי עָלַי מִנְחַת מַחֲבַת; וּכְלִי הוּא שֶׁהָיָה בַּמִּקְדָּשׁ, שֶׁאוֹפִין בּוֹ מִנְחָה זוֹ עַל הָאוּר בְּשֶׁמֶן, וְהַכְּלִי אֵינוֹ עָמֹק אֶלָּא צָף, וּמַעֲשֵׂי הַמִּנְחָה שֶׁבְּתוֹכוֹ קָשִׁין, שֶׁמִּתּוֹךְ שֶׁהִיא צָפָה, הָאוּר שׂוֹרֵף אֶת הַשֶּׁמֶן. וְכֻלָּן טְעוּנוֹת שָׁלוֹשׁ מַתְּנוֹת שֶׁמֶן — יְצִיקָה וּבְלִילָה וּמַתַּן שֶׁמֶן בִּכְלִי קֹדֶם לַעֲשִֹיָּתָן (שם ע"ד):
@22 **סלת בלולה בשמן.** מְלַמֵּד שֶׁבּוֹלְלָן בְּעוֹדָן סֹלֶת (מנחות ע"ד):
@23 **פתות אתה פתים.** לְרַבּוֹת כָּל הַמְּנָחוֹת הַנֶּאֱפוֹת קֹדֶם קְמִיצָה לִפְתִיתָה (שם ע"ה):
@23 **ויצקת עליה שמן מנחה הוא.** לְרַבּוֹת כָּל הַמְּנָחוֹת לִיצִיקָה; יָכוֹל אַף מִנְחָה מַאֲפֵה תַּנּוּר כֵּן, תַּ"ל עָלֶיהָ; אוֹצִיא אֶת הַחַלּוֹת וְלֹא אוֹצִיא אֶת הָרְקִיקִין, תַּ"ל הִוא (שם):
@24 **מרחשת.** כְּלִי הוּא שֶׁהָיָה בַּמִּקְדָּשׁ, עָמֹק, וּמִתּוֹךְ שֶׁהִיא עֲמֻקָּה, שַׁמְנָהּ צָבוּר וְאֵין הָאוּר שׂוֹרְפוֹ, לְפִיכָךְ מַעֲשֵׂי מִנְחָה הָעֲשׂוּיִין לְתוֹכָהּ רוֹחֲשִׁין; כָּל דָּבָר רַךְ עַל יְדֵי מַשְׁקֶה נִרְאֶה כְּרוֹחֵשׁ וּמְנַעֲנֵעַ (ספרא):
@25 **אשר יעשה מאלה.** מֵאֶחָד מִן הַמִּינִים הַלָּלוּ:
@25 **והקריבה.** בְּעָלֶיהָ **אל הכהן** :
@25 **והגישה.** הַכֹּהֵן:
@25 **והגישה אל המזבח.** מַגִּישָׁהּ לְקֶרֶן דְּרוֹמִית מַעֲרָבִית שֶׁל מִזְבֵּחַ (זבחים ס"ג):
@26 **את אזכרתה.** הִיא הַקֹּמֶץ:
@28 **וכל דבש.** כָּל מְתִיקַת פְּרִי קְרוּיָה דְּבַשׁ:
@29 **קרבן ראשית תקריבו אתם.** מַה יֵּשׁ לְךָ לְהָבִיא מִן הַשְּׂאוֹר וּמִן הַדְּבַשׁ? קָרְבַּן רֵאשִׁית — שְׁתֵּי הַלֶּחֶם שֶׁל עֲצֶרֶת הַבָּאִים מִן הַשְּׂאוֹר, שֶׁנֶּאֱמַר חָמֵץ תֵּאָפֶינָה (ויקרא כ"ג), וּבִכּוּרִים מִן הַדְּבַשׁ, כְּמוֹ בִּכּוּרֵי תְּאֵנִים וּתְמָרִים (מנחות נ"ח):
@30 **מלח ברית.** שֶׁהַבְּרִית כְּרוּתָה לַמֶּלַח מִשֵּׁשֶׁת יְמֵי בְּרֵאשִׁית, שֶׁהֻבְטְחוּ הַמַּיִם הַתַּחְתּוֹנִים לִקָּרֵב בַּמִּזְבֵּחַ בַּמֶּלַח וְנִסּוּךְ הַמַּיִם בֶּחָג:
@30 **על כל קרבנך.** עַל עוֹלַת בְּהֵמָה וָעוֹף וְאֵמוּרֵי כָּל הַקָּדָשִׁים כֻּלָּן (מנחות כ'):
@31 **ואם תקריב.** הֲרֵי אִם מְשַׁמֵּשׁ בִּלְשׁוֹן כִּי, שֶׁהֲרֵי אֵין זֶה רְשׁוּת, שֶׁהֲרֵי בְּמִנְחַת הָעֹמֶר הַכָּתוּב מְדַבֵּר שֶׁהִיא חוֹבָה, וְכֵן וְאִם יִהְיֶה הַיֹּבֵל וְגוֹ' (במדבר ל"ו):
@31 **מנחת בכורים.** בְּמִנְחַת הָעֹמֶר הַכָּתוּב מְדַבֵּר שֶׁהִיא בָּאָה אָבִיב — בִּשְׁעַת בִּשּׁוּל הַתְּבוּאָה, וּמִן הַשְּׂעוֹרִים הִיא בָּאָה, נֶאֱמַר כָּאן אָבִיב וְנֶאֱמַר לְהַלָּן (שמות ט'), הַשְּׂעֹרָה אָבִיב:
@31 **קלוי באש.** שֶׁמְּיַבְּשִׁין אוֹתָהּ עַל הָאוּר בְּאַבּוּב שֶׁל קַלָּאִים, שֶׁאִלּוּלֵי כֵן אֵינָהּ נִטְחֶנֶת בָּרֵחַיִם, לְפִי שֶׁהִיא לַחָה:
@31 **גרש כרמל.** גְּרוּסָה בְּעוֹדָהּ לַחָה:
@31 **גרש.** גֶּרֶשׂ לְשׁוֹן שְׁבִירָה וּטְחִינָה, גּוֹרְסָהּ בְּרֵחַיִם שֶׁל גָּרוֹסוֹת, כְּמוֹ וַיַּגְרֵס בֶּחָצָץ (איכה ג'), וְכֵן גָּרְסָה נַפְשִׁי (תהילים קי"ט):
@31 **כרמל.** בְּעוֹד הַכַּר מָלֵא, שֶׁהַתְּבוּאָה לַחָה וּמְלֵאָה בְּקַשִּׁין שֶׁלָּהּ, וְעַל כֵּן נִקְרָאִים הַמְּלִילוֹת כַּרְמֶל, וְכֵן כַּרְמֶל בְּצִקְלוֹנוֹ (מלכים ב ד'):
@34 **שלמים.** שֶׁמְּטִילִים שָׁלוֹם בָּעוֹלָם; דָּ"אַ: שְׁלָמִים שֶׁיֵּשׁ בָּהֶם שָׁלוֹם לַמִּזְבֵּחַ וְלַכֹּהֲנִים וְלַבְּעָלִים (ספרא):
@36 **ואת כל החלב וגו'.** לְהָבִיא חֵלֶב שֶׁעַל הַקֵּבָה דִּבְרֵי רַבִּי יִשְׁמָעֵאל, רַבִּי עֲקִיבָא אוֹמֵר לְהָבִיא חֵלֶב שֶׁעַל הַדַּקִּין (שם):
@37 **הכסלים.** פלנק"ש בְּלַעַז; שֶׁהַחֵלֶב שֶׁעַל הַכְּלָיוֹת כְּשֶׁהַבְּהֵמָה חַיָּה הוּא בְּגֹבַהּ הַכְּסָלִים מִלְּמַטָּה, וְזֶה הַחֵלֶב שֶׁתַּחַת הַמָּתְנַיִם — שֶׁקּוֹרִין בְּלַעַז לונבי"לוש — לֹבֶן הַנִּרְאֶה לְמַעְלָה בְּגֹבַהּ הַכְּסָלִים, וּבְתַחְתִּיתוֹ הַבָּשָֹר חוֹפֵהוּ:
@37 **היתרת.** הוּא דֹּפֶן הַמָּסָךְ שֶׁקּוֹרִין איברי"ש, וּבְלָשׁוֹן אֲרַמִּי חִצְרָא דְּכַבְדָּא:
@37 **על הכבד.** שֶׁיִּטֹּל מִן הַכָּבֵד עִמָּהּ מְעַט, וּבְמָקוֹם אַחֵר הוּא אוֹמֵר וְאֶת הַיֹּתֶרֶת מִן הַכָּבֵד (ויקרא ט'):
@37 **על הכבד על הכליות.** לְבַד מִן הַכָּבֵד וּלְבַד מִן הַכְּלָיוֹת יְסִירֶנָּה לְזוֹ:
@38 **על העלה.** מִלְּבַד הָעוֹלָה; לִמְּדָנוּ שֶׁתִּקְדֹּם עוֹלַת תָּמִיד לְכָל קָרְבָּן עַל הַמַּעֲרָכָה (זבחים פ"ט):
@40 **אם כשב.** לְפִי שֶׁיֵּשׁ בְּאֵמוּרֵי הַכֶּשֶׂב מַה שֶּׁאֵין בְּאֵמוּרֵי הָעֵז, שֶׁהַכֶּשֶׂב אַלְיָתוֹ קְרֵבָה, לְכָךְ נֶחְלְקוּ לִשְׁתֵּי פָּרָשִׁיּוֹת (ספרא):
@41 **וזרקו.** שְׁתֵּי מַתָּנוֹת שֶׁהֵן אַרְבַּע; וְעַל יְדֵי הַכְּלִי הוּא זוֹרֵק, וְאֵינוֹ נוֹתֵן בָּאֶצְבַּע אֶלָּא חַטָּאת (זבחים נ"ה):
@42 **חלבו.** הַמֻּבְחָר שֶׁבּוֹ, וּמַהוּ? זֶה הָאַלְיָה תְּמִימָה:
@42 **לעמת העצה.** לְמַעְלָה מִן הַכְּלָיוֹת הַיּוֹעֲצוֹת:
@44 **לחם אשה לה'.** לַחְמוֹ שֶׁל אֵשׁ לְשֵׁם גָּבוֹהַּ:
@44 **לחם.** לְשׁוֹן מַאֲכָל, וְכֵן נַשְׁחִיתָה עֵץ בְּלַחְמוֹ (ירמיהו י"א), עֲבַד לְחֶם רַב (דניאל ה'), לִשְֹחוֹק עֹשִֹׁים לֶחֶם (קהלת י'):
@50 **חקת עולם.** יָפֶה מְפֹרָשׁ בְּתוֹרַת כֹּהֲנִים כָּל הַפָּסוּק הַזֶּה:
@52 **מכל מצות ה'.** פֵּרְשׁוּ רַבּוֹתֵינוּ אֵין חַטָּאת בָּאָה אֶלָּא עַל דָּבָר שֶׁזְּדוֹנוֹ לָאו וְכָרֵת (ספרא):
@52 **מאחת מהנה.** מִמִּקְּצָת אַחַת מֵהֶן, כְּגוֹן הַכּוֹתֵב בְּשַׁבָּת שם מִשִּׁמְעוֹן, נח מִנָּחוֹר, דן מִדָּנִיֵּאל (שם):
@53 **אם הכהן המשיח יחטא לאשמת העם.** מִדְרָשׁוֹ: אֵינוֹ חַיָּב אֶלָּא בְּהֶעְלֵם דָּבָר עִם שִׁגְגַת מַעֲשֶֹה, כְּמוֹ שֶׁנֶּאֱמַר לְאַשְׁמַת הָעָם וְנֶעְלַם דָּבָר מֵעֵינֵי הַקָּהָל וְעָשׂוּ (שם); וּפְשׁוּטוֹ לְפִי אַגָּדָה: כְּשֶׁכֹּהֵן גָּדוֹל חוֹטֵא, אַשְׁמַת הָעָם הוּא זֶה, שֶׁהֵן תְּלוּיִין בּוֹ לְכַפֵּר עֲלֵיהֶם וּלְהִתְפַּלֵּל בַּעֲדָם, וְנַעֲשֶׂה מְקֻלְקָל:
@53 **פר.** יָכוֹל זָקֵן, תַּלְמוּד לוֹמַר בֶּן, אִי בֶּן יָכוֹל קָטָן, תַּלְמוּד לוֹמַר פַּר, הָא כֵּיצַד? זֶה פַּר בֶּן שָׁלוֹשׁ (שם):
@55 **אל אהל מועד.** לַמִּשְׁכָּן, וּבְבֵית עוֹלָמִים לַהֵיכָל:
@56 **את פני פרכת הקדש.** כְּנֶגֶד מְקוֹם קְדֻשָּׁתָהּ — מְכֻוָּן כְּנֶגֶד בֵּין הַבַּדִּים, וְלֹא הָיוּ נוֹגְעִים דָּמִים בַּפָּרֹכֶת, וְאִם נָגְעוּ נָגְעוּ:
@57 **ואת כל דם.** שְׁיָרֵי הַדָּם (זבחים כ"ה):
@58 **ואת כל חלב פר.** חֶלְבּוֹ הָיָה לוֹ לוֹמַר, מַה תַּלְמוּד לוֹמַר פַּר? לְרַבּוֹת פַּר שֶׁל יוֹם הַכִּפּוּרִים לִכְלָיוֹת וְלַחֲלָבִים וְיוֹתֶרֶת (ספרא):
@58 **החטאת.** לְהָבִיא שְֹעִירֵי עֲ"זָ לִכְלָיוֹת וְלַחֲלָבִים וּלְיוֹתֶרֶת (שם):
@58 **ירים ממנו.** מִן הַמְחֻבָּר — שֶׁלֹּא יְנַתְּחֶנּוּ קֹדֶם הֲסָרַת חֶלְבּוֹ, תּוֹרַת כֹּהֲנִים:
@60 **כאשר יורם.** מֵאוֹתָן אֵמוּרִין הַמְפֹרָשִׁין בְּשׁוֹר זֶבַח הַשְּׁלָמִים; וְכִי מַה פֵּרֵשׁ בְּזֶבַח הַשְּׁלָמִים שֶׁלֹא פֵּרֵשׁ כָּאן? אֶלָּא לְהַקִּישׁוֹ לִשְׁלָמִים, מַה שְּׁלָמִים לִשְׁמָן אַף זֶה לִשְׁמוֹ, וּמָה שְׁלָמִים שָׁלוֹם לָעוֹלָם, אַף זֶה שָׁלוֹם לָעוֹלָם; וּבִשְׁחִיטַת קֳדָשִׁים מַצְרִיכוֹ לִלְמֹד הֵימֶנּוּ שֶׁאֵין לְמֵדִין לָמֵד מִן הַלָּמֵד בָּקֳדָשִׁים, בְּפֶרֶק אֵיזֶהוּ מְקוֹמָן (זבחים מ"ט):
@60 **על הכבד על הכליות. על ראשו ועל כרעיו.** כֻּלָּן לְשׁוֹן תּוֹסֶפֶת הֵן, כְּמוֹ מִלְּבַד:
@62 **אל מקום טהור.** לְפִי שֶׁיֵּשׁ מִחוּץ לָעִיר מָקוֹם מוּכָן לְטֻמְאָה — לְהַשְׁלִיךְ אֲבָנִים מְנֻגָּעוֹת וּלְבֵית הַקְּבָרוֹת — הֻצְרַךְ לוֹמַר מִחוּץ לַמַּחֲנֶה זֶה — שֶׁהוּא חוּץ לָעִיר — שֶׁיְּהֵא הַמָּקוֹם טָהוֹר:
@62 **מחוץ למחנה.** חוּץ לְשָׁלוֹשׁ מַחֲנוֹת; וּבֵית עוֹלָמִים חוּץ לָעִיר, כְּמוֹ שֶׁפֵּרְשׁוּהוּ רַבּוֹתֵינוּ בְּמַסֶּכֶת יוֹמָא (דף ס"ח) וּבְסַנְהֶדְרִין (דף מ"ב):
@62 **אל שפך הדשן.** מָקוֹם שֶׁשּׁוֹפְכִין בּוֹ הַדֶּשֶׁן הַמְסֻלָּק מִן הַמִּזְבֵּחַ, כְּמוֹ שֶׁנֶּאֱמַר וְהוֹצִיא אֶת הַדֶּשֶׁן אֶל מִחוּץ לַמַּחֲנֶה (ויקרא ו'):
@62 **על שפך הדשן ישרף.** שֶׁאֵין תַּלְמוּד לוֹמַר, אֶלָּא לְלַמֵּד שֶׁאֲפִלּוּ אֵין שָׁם דֶּשֶׁן (ספרא):
@63 **עדת ישראל.** אֵלּוּ סַנְהֶדְרִין (שם):
@63 **ונעלם דבר.** טָעוּ לְהוֹרוֹת בְּאַחַת מִכָּל כָּרֵתוֹת שֶׁבַּתּוֹרָה שֶׁהוּא מֻתָּר (הוריות ח'):
@63 **הקהל ועשו.** שֶׁעָשׂוּ צִבּוּר עַל פִּיהֶם:
@67 **את פני הפרכת.** וּלְמַעְלָה הוּא אוֹמֵר אֶת פְּנֵי פָּרֹכֶת הַקֹּדֶשׁ מָשָׁל לְמֶלֶךְ שֶׁסָּרְחָה עָלָיו מְדִינָה, אִם מִעוּטָהּ סָרְחָה, פָּמַלְיָא שֶׁלּוֹ מִתְקַיֶּמֶת וְאִם כֻּלָּהּ סָרְחָה, אֵין פָּמַלְיָא שֶׁלּוֹ מִתְקַיֶּמֶת, אַף כָּאן, כְּשֶׁחָטָא כֹּהֵן מָשִׁיחַ עֲדַיִן שֵׁם קְדֻשַּׁת הַמָּקוֹם עַל הַמִּקְדָּשׁ, מִשֶּׁחָטְאוּ כֻּלָּם, חַס וְשָׁלוֹם נִסְתַּלְּקָה הַקְּדֻשָּׁה (זבחים מ"א):
@68 **יסוד מזבח העלה אשר פתח אהל מועד.** זֶה יְסוֹד מַעֲרָבִי שֶׁהוּא כְּנֶגֶד הַפֶּתַח (שם נ"א):
@69 **ואת כל חלבו ירים.** אַף עַל פִּי שֶׁלֹּא פֵּרֵשׁ כָּאן יוֹתֶרֶת וּשְׁתֵּי כְּלָיוֹת, לְמֵדִין הֵם מִוְּעָשָׂה לַפָּר כַּאֲשֶׁר עָשָׂה וְגוֹ' וּמִפְּנֵי מָה לֹא נִתְפָּרְשׁוּ בּוֹ? תָּנָא דְּבֵי רַבִּי יִשְׁמָעֵאל מָשָׁל לְמֶלֶךְ שֶׁזָּעַם עַל אוֹהֲבוֹ וּמִעֵט בְּסִרְחוֹנוֹ מִפְּנֵי חִבָּתוֹ (שם מ"א):
@70 **ועשה לפר** זֶה **כאשר עשה לפר החטאת.** כְּמוֹ שֶׁמְּפֹרָשׁ בְּפַר כֹּהֵן מָשִׁיחַ — לְהָבִיא יוֹתֶרֶת וּשְׁתֵּי כְּלָיוֹת שֶׁפֵּרֵשׁ שָׁם, מַה שֶּׁלֹא פֵּרֵשׁ כָּאן, וְלִכְפֹּל בְּמִצְוַת הָעֲבוֹדוֹת, לְלַמֵּד שֶׁאִם חִסֵּר אַחַת מִכָּל הַמַּתָּנוֹת פָּסוּל; לְפִי שֶׁמָּצִינוּ בַּנִּתָּנִין עַל הַמִּזְבֵּחַ הַחִיצוֹן שֶׁנְּתָנָן בְּמַתָּנָה אַחַת כִּפֵּר, הֻצְרַךְ לוֹמַר כָּאן שֶׁמַּתָּנָה אַחַת מֵהֶן מְעַכֶּבֶת (שם ל"ט):
@72 **אשר נשיא יחטא.** לְשׁוֹן אַשְׁרֵי — אַשְׁרֵי הַדּוֹר שֶׁהַנָּשִׂיא שֶׁלּוֹ נוֹתֵן לֵב לְהָבִיא כַּפָּרָה עַל שִׁגְגָתוֹ, קַל וָחֹמֶר שֶׁמִּתְחָרֵט עַל זְדוֹנוֹתָיו (ספרא):
@73 **או הודע.** כְּמוֹ אִם הוֹדַע הַדָּבָר; הַרְבֵּה אוֹ יֵשׁ שֶׁמְּשַׁמְּשִׁין בִּלְשׁוֹן אִם, וְאִם בִּמְקוֹם אוֹ, וְכֵן אוֹ נוֹדַע כִּי שׁוֹר נַגָּח הוּא (שמות כ"א):
@73 **הודע אליו.** כְּשֶׁחָטָא הָיָה סָבוּר שֶׁהוּא הֶתֵּר, וּלְאַחַר מִכָּאן נוֹדַע לוֹ שֶׁאִסּוּר הָיָה:
@74 **במקום אשר ישחט את העלה.** בַּצָּפוֹן שֶׁהוּא מְפֹרָשׁ בָּעוֹלָה:
@74 **חטאת הוא.** לִשְׁמוֹ כָּשֵׁר, שֶׁלֹּא לִשְׁמוֹ פָּסוּל (ספרא):
@75 **ואת דמו.** שְׁיָרֵי הַדָּם:
@76 **כחלב זבח השלמים.** כְּאוֹתָן אֵמוּרִין הַמְפֹרָשִׁים בְּעֵז הָאָמוּר אֵצֶל שְׁלָמִים:
@81 **כאשר הוסר חלב מעל זבח השלמים.** כְּאֵמוּרֵי עֵז הָאֲמוּרִים בַּשְּׁלָמִים:
@83 **ושחט אתה לחטאת.** שֶׁתְּהֵא שְׁחִיטָתָהּ לְשֵׁם חַטָּאת (זבחים ז'):
@85 **כאשר יוסר חלב הכשב.** שֶׁנִּתְרַבּוּ אֵמוּרָיו בָּאַלְיָה, אַף חַטָּאת כְּשֶׁהִיא בָּאָה כִּבְשָׂה טְעוּנָה אַלְיָה עִם הָאֵמוּרִין:
@85 **על אשי ה'.** עַל מְדוּרוֹת הָאֵשׁ הָעֲשׂוּיוֹת לַשֵּׁם, פוא"ייליש בְּלַעַז:
@86 **ושמעה קול אלה.** בְּדָבָר שֶׁהוּא עֵד בּוֹ — שֶׁהִשְׁבִּיעוּהוּ שְׁבוּעָה, שֶׁאִם יוֹדֵעַ לוֹ בְּעֵדוּת, שֶׁיָּעִיד לוֹ (ספרא):
@87 **או נפש אשר תגע וגו'.** וּלְאַחַר הַטֻּמְאָה הַזּוֹ יֹאכַל קָדָשִׁים אוֹ יִכָּנֵס לַמִּקְדָּשׁ, שֶׁהוּא דָּבָר שֶׁזְּדוֹנוֹ כָּרֵת; בְּמַסֶּכֶת שְׁבוּעוֹת (דף י"ד) נִדְרַשׁ כֵּן:
@87 **ונעלם ממנו.** הַטֻּמְאָה:
@87 **ואשם.** בַּאֲכִילַת קֹדֶשׁ אוֹ בְּבִיאַת מִקְדָּשׁ:
@88 **בטמאת אדם.** זוֹ טֻמְאַת מֵת:
@88 **לכל טמאתו.** לְרַבּוֹת טֻמְאַת מַגַּע זָבִין וְזָבוֹת:
@88 **אשר יטמא.** לְרַבּוֹת הַנּוֹגֵעַ בְּבוֹעֵל נִדָּה:
@88 **בה.** לְרַבּוֹת בּוֹלֵעַ נִבְלַת עוֹף טָהוֹר (ספרא):
@88 **ונעלם.** וְלֹא יָדַע שֶׁשָּׁכַח הַטֻּמְאָה:
@88 **ואשם.** בַּאֲכִילַת קֹדֶשׁ אוֹ בְּבִיאַת מִקְדָּשׁ:
@89 **בשפתים.** וְלֹא בַּלֵּב (שם):
@89 **להרע.** לְעַצְמוֹ:
@89 **או להיטיב.** לְעַצְמוֹ, כְּגוֹן אֹכַל וְלֹא אֹכַל, אִישַׁן וְלֹא אִישַׁן (שבועות כ"ז):
@89 **לכל אשר יבטא.** לְרַבּוֹת לְשֶׁעָבַר:
@89 **ונעלם ממנו.** וְעָבַר עַל שְׁבוּעָתוֹ, כָּל אֵלֶּה בְּקָרְבָּן עוֹלֶה וְיוֹרֵד, כַּמְּפֹרָשׁ כָּאן, אֲבָל שְׁבוּעָה שֶׁיֵּשׁ בָּהּ כְּפִירַת מָמוֹן אֵינָהּ בְּקָרְבָּן זוֹ אֶלָּא בְּאָשָׁם:
@93 **והקריב את אשר לחטאת ראשונה.** חַטָּאת קוֹדֶמֶת לָעוֹלָה (ספרא); לְמָה הַדָּבָר דּוֹמֶה? לִפְרַקְלִיט שֶׁנִּכְנָס לְרַצּוֹת, רִצָּה פְּרַקְלִיט, נִכְנָס דּוֹרוֹן אַחֲרָיו (זבחים ז'):
@93 **ולא יבדיל.** אֵינוֹ מוֹלֵק אֶלָּא סִימָן אֶחָד (חולין כ"א):
@93 **ערף.** הוּא גֹּבַהּ הָרֹאשׁ הַמַּשְׁפִּיעַ לְצַד הַצַּוָּאר:
@93 **ממול ערפו.** מוּל הָרוֹאֶה אֶת הָעֹרֶף, וְהוּא אֹרֶךְ כָּל אֲחוֹרֵי הַצַּוָּאר (שם י"ט):
@94 **והזה מדם החטאת.** בָּעוֹלָה לֹא הִטְעִין אֶלָּא מִצּוּי, וּבַחַטָּאת הַזָּאָה וּמִצּוּי, אוֹחֵז בָּעֹרֶף וּמַתִּיז, וְהַדָּם נִתָּז וְהוֹלֵךְ לַמִּזְבֵּחַ:
@94 **חטאת הוא.** לִשְׁמָהּ כְּשֵׁרָה, שֶׁלֹא לִשְׁמָהּ פְּסוּלָה (ספרא):
@95 **כמשפט.** כַּדָּת הָאָמוּר בְּעוֹלַת הָעוֹף שֶׁל נְדָבָה בְּרֹאשׁ הַפָּרָשָׁה:
@96 **כי חטאת הוא.** וְאֵין בַּדִּין שֶׁיְּהֵא קָרְבָּנוֹ מְהֻדָּר (מנחות ו'):
@97 **חטאת הוא.** נִקְמְצָה וְנִקְטְרָה לִשְׁמָהּ כְּשֵׁרָה, שֶׁלֹּא לִשְׁמָהּ פְּסוּלָה:
@98 **על חטאתו אשר חטא.** כָּאן שִׁנָּה הַכָּתוּב, שֶׁהֲרֵי בַּעֲשִׁירוּת וּבְדַלּוּת נֶאֱמַר מֵחַטָּאתוֹ, וְכָאן בְּדַלֵּי דַּלּוּת נֶאֱמַר עַל חַטָּאתוֹ, דִּקְדְּקוּ רַבּוֹתֵינוּ מִכָּאן, שֶׁאִם חָטָא כְּשֶׁהוּא עָשִׁיר וְהִפְרִישׁ מָעוֹת לְכִשְׂבָּה אוֹ שְׂעִירָה וְהֶעֱנִי, יָבִיא מִמִּקְצָתָן שְׁתֵּי תּוֹרִים, הִפְרִישׁ מָעוֹת לִשְׁתֵּי תּוֹרִים וְהֶעֱנִי, יָבִיא מִמִּקְצָתָן עֲשִׂירִית הָאֵפָה, הִפְרִישׁ מָעוֹת לַעֲשִׂירִית הָאֵפָה וְהֶעֱשִׁיר, יוֹסִיף עֲלֵיהֶן וְיָבִיא קָרְבַּן עָשִׁיר, לְכָךְ נֶאֱמַר כָּאן עַל חַטָּאתוֹ:
@98 **מאחת מאלה.** מֵאַחַת מִשָּׁלוֹשׁ כַּפָּרוֹת הָאֲמוּרוֹת בָּעִנְיָן — אוֹ בַּעֲשִׁירוּת אוֹ בְּדַלּוּת אוֹ בְּדַלֵּי דַּלּוּת; וּמָה תַּלְמוּד לוֹמַר? שֶׁיָּכוֹל הַחֲמוּרִים שֶׁבָּהֶם יִהְיוּ בְּכִשְׂבָּה אוֹ שְׂעִירָה, וְהַקַּלִּין יִהְיוּ בְּעוֹף, וְהַקַּלִּין שֶׁבַּקַּלִין יִהְיוּ בַּעֲשִׂירִית הָאֵפָה, תַּלְמוּד לוֹמַר מֵאַחַת מֵאֵלֶּה, לְהַשְׁווֹת קַלִּין לַחֲמוּרִין לְכִשְׂבָּה וּשְׂעִירָה אִם הִשִּׂיגָה יָדוֹ, וְאֶת הַחֲמוּרִין לַקַּלִּין לַעֲשִׂירִית הָאֵפָה בְּדַלֵּי דַּלּוּת (ספרא):
@98 **והיתה לכהן כמנחה.** לְלַמֵּד עַל מִנְחַת חוֹטֵא שֶׁיִּהְיוּ שְׁיָרֶיהָ נֶאֱכָלִין, זֶהוּ לְפִי פְּשׁוּטוֹ; וְרַבּוֹתֵינוּ דָּרְשׁוּ: "וְהָיְתָה לַכֹּהֵן" — וְאִם חוֹטֵא זֶה כֹּהֵן הוּא, תְּהֵא כִּשְׁאָר מִנְחַת נִדְבַת כֹּהֵן, שֶׁהִיא בְּכָלִיל תִּהְיֶה לֹא תֵאָכֵל (ספרא):
@100 **כי תמעל מעל.** אֵין מְעִילָה בְּכָל מָקוֹם אֶלָּא שִׁנּוּי, וְכֵן הוּא אוֹמֵר וַיִּמְעֲלוּ בֵאלֹהֵי אֲבֹתֵיהֶם וַיִּזְנוּ אַחֲרֵי אֱלֹהֵי עַמֵּי הָאָרֶץ (דהי"א ה'), וְכֵן הוּא אוֹמֵר בְּסוֹטָה וּמָעֲלָה בוֹ מָעַל (במדבר ה'):
@100 **וחטאה בשגגה מקדשי ה'.** שֶׁנֶּהֱנָה מִן הַהֶקְדֵּשׁ; וְהֵיכָן הֻזְהַר? נֶאֱמַר כָּאן חֵטְא, וְנֶאֱמַר לְהַלָּן חֵטְא בִּתְרוּמָה, וְלֹא יִשְֹאוּ עָלָיו חֵטְא (ויקרא כ"ב), מַה לְּהַלָּן הִזְהִיר, אַף כָּאן הִזְהִיר; אִי מַה לְּהַלָּן לֹא הִזְהִיר אֶלָּא עַל הָאוֹכֵל, אַף כָּאן לֹא הִזְהִיר אֶלָּא עַל הָאוֹכֵל, תַּ"לֹ תִמְעֹל מַעַל — רִבָּה (ספרא):
@100 **מקדשי ה'.** הַמְיֻחָדִים לַשֵּׁם, יָצְאוּ קָדָשִׁים קַלִּים (שם):
@100 **איל.** לְשׁוֹן קָשֶׁה, כְּמוֹ וְאֶת אֵילֵי הָאָרֶץ לָקָח (יחזקאל י"ז), אַף כָּאן קָשֶׁה — בֶּן שְׁתֵּי שָׁנִים (ספרא):
@100 **בערכך כסף שקלים.** שֶׁיְּהֵא שָׁוֶה שְׁתֵּי סְלָעִים:
@101 **ואת אשר חטא מן הקדש ישלם.** קֶרֶן וְחֹמֶשׁ לַהֶקְדֵּשׁ:
@102 **ולא ידע ואשם, והביא.** הָעִנְיָן הַזֶּה מְדַבֵּר בְּמִי שֶׁבָּא סְפֵק כָּרֵת לְיָדוֹ וְלֹא יָדַע אִם עָבַר עָלָיו אִם לָאו, כְּגוֹן חֵלֶב וְשֻׁמָּן לְפָנָיו, וּכְסָבוּר שְׁתֵּיהֶן הֶתֵּר וְאָכַל אֶת הָאֶחָד, אָמְרוּ לוֹ אַחַת שֶׁל חֵלֶב הָיְתָה, וְלֹא יָדַע אִם זוֹ שֶׁל חֵלֶב אָכַל, הֲרֵי זֶה מֵבִיא אָשָׁם תָּלוּי, וּמֵגֵן עָלָיו כָּל זְמַן שֶׁלֹּא נוֹדַע לוֹ שֶׁוַּדַּאי חָטָא, וְאִם נוֹדַע לוֹ לְאַחַר זְמַן, יָבִיא חַטָּאת (כריתות כ"ב):
@102 **ולא ידע ואשם ונשא עונו.** רַבִּי יוֹסֵי הַגְּלִילִי אוֹמֵר, הֲרֵי הַכָּתוּב עָנַשׁ אֶת מִי שֶׁלֹּא יָדַע, עַל אַחַת כַּמָּה וְכַמָּה שֶׁיַּעֲנִישׁ אֶת מִי שֶׁיָּדַע, רַבִּי יוֹסֵי אוֹמֵר, אִם נַפְשְׁךָ לֵידַע מַתַּן שְֹכָרָן שֶׁל צַדִּיקִים, צֵא וּלְמַד מֵאָדָם הָרִאשׁוֹן שֶׁלֹּא נִצְטַוָּה אֶלָּא עַל מִצְוַת לֹא תַעֲשֶׂה וְעָבַר עָלֶיהָ, רְאֵה כַּמָּה מִיתוֹת נִקְנְסוּ עָלָיו וּלְדוֹרוֹתָיו. וְכִי אֵיזוֹ מִדָּה מְרֻבָּה שֶׁל טוֹבָה אוֹ שֶׁל פֻּרְעָנוּת? הֱוֵי אוֹמֵר מִדָּה טוֹבָה, אִם מִדַּת פֻּרְעָנוּת מְעוּטָה, רְאֵה כַּמָּה מִיתוֹת נִקְנְסוּ לוֹ וּלְדוֹרוֹתָיו, מִדָּה טוֹבָה הַמְרֻבָּה הַיּוֹשֵׁב לוֹ מִן הַפִּגּוּלִין וְהַנּוֹתָרוֹת וְהַמִּתְעַנֶּה בְּיוֹם הַכִּפּוּרִים — עַאַכַּ"וְ שֶׁיִּזְכֶּה לוֹ וּלְדוֹרוֹתָיו וּלְדוֹרוֹת דּוֹרוֹתָיו עַד סוֹף כָּל הַדּוֹרוֹת; רַבִּי עֲקִיבָא אוֹמֵר, הֲרֵי הוּא אוֹמֵר עַל פִּי שְׁנַיִם עֵדִים אוֹ שְׁלֹשָׁה וְגוֹ' (דברים י"ז), אִם מִתְקַיֶּמֶת הָעֵדוּת בִּשְׁנַיִם, לָמָּה פֵּרֵט לְךָ הַכָּתוּב ג'? אֶלָּא לְהָבִיא שְׁלִישִׁי לְהַחֲמִיר עָלָיו וְלַעֲשׂוֹת דִּינוֹ כַּיּוֹצֵא בָּאֵלּוּ לְעִנְיַן עֹנֶשׁ בַּהֲזָמָה; אִם כָּךְ עָנַשׁ הַכָּתוּב לַנִּטְפָּל לְעוֹבְרֵי עֲבֵרָה כְּעוֹבְרֵי עֲבֵרָה, עַל אַחַת כַּמָּה וְכַמָּה שֶׁיְּשַׁלֵּם שָֹכָר טוֹב לַנִּטְפָּל לְעוֹשֵׂי מִצְוָה כְּעוֹשֵׂי מִצְוָה (סנהדרין ט'); רַבִּי אֶלְעָזָר בֶּן עֲזַרְיָה אוֹמֵר, כִּי תִקְצֹר קְצִירְךָ בְשָׂדֶךָ וְשָׁכַחְתָּ עֹמֶר בַּשָּׂדֶה הֲרֵי הוּא אוֹמֵר לְמַעַן יְבָרֶכְךָ וְגוֹ' (דברים כ"ד) — קָבַע הַכָּתוּב בְּרָכָה לְמִי שֶׁבָּאת עַל יָדוֹ מִצְוָה בְּלֹא יָדַע — אֱמֹר מֵעַתָּה, הָיְתָה סֶלַע צְרוּרָה בִּכְנָפָיו וְנָפְלָה הֵימֶנּוּ וּמְצָאָהּ הֶעָנִי וְנִתְפַּרְנֵס בָּהּ, הֲרֵי הַקָּבָּ"ה קוֹבֵעַ לוֹ בְּרָכָה (ספרא):
@103 **בערכך לאשם.** בָּעֵרֶךְ הָאָמוּר לְמַעְלָה:
@103 **אשר שגג והוא לא ידע.** הָא אִם יָדַע לְאַחַר זְמַן, לֹא נִתְכַּפֵּר לוֹ בְּאָשָׁם זֶה עַד שֶׁיָּבִיא חַטָּאת, הָא לְמָה זֶה דּוֹמֶה? לְעֶגְלָה עֲרוּפָה שֶׁנִּתְעָרְפָה וְאַחַר כָּךְ נִמְצָא הַהוֹרֵג, הֲרֵי זֶה יֵהָרֵג (שם):
@104 **אשם הוא אשם אשם.** הָרִאשׁוֹן כֻּלּוֹ קָמוּץ, שֶׁהוּא שֵׁם דָּבָר, וְהָאַחֲרוֹן חֶצְיוֹ קָמָץ וְחֶצְיוֹ פַּתָּח שֶׁהוּא לְשׁוֹן פָּעַל; וְאִם תֹּאמַר מִקְרָא שֶׁלֹּא לְצֹרֶךְ הוּא, כְּבָר דָּרוּשׁ הוּא בְּתוֹרַת כֹּהֲנִים, **אשם אשם** — לְהָבִיא אֲשַׁם שִׁפְחָה חֲרוּפָה שֶׁיְּהֵא אַיִל בֶּן שְׁתֵּי סְלָעִים, יָכוֹל שֶׁאֲנִי מְרַבֶּה אֲשַׁם נָזִיר וַאֲשַׁם מְצֹרָע, תַּלְמוּד לוֹמַר הוּא (שם):
@106 **נפש כי תחטא.** אָמַר רַבִּי עֲקִיבָא, מַה תַּ"ל וּמָעֲלָה מַעַל בַּה'? לְפִי שֶׁכָּל הַמַּלְוֶה וְהַלֹּוֶה וְהַנּוֹשֵֹׁא וְהַנּוֹתֵן אֵינוֹ עוֹשֶׂה אֶלָּא בְּעֵדִים וּבִשְׁטָר, לְפִיכָךְ בִּזְמַן שֶׁהוּא מְכַחֵשׁ, מְכַחֵשׁ בָּעֵדִים וּבַשְּׁטָר, אֲבָל הַמַּפְקִיד אֵצֶל חֲבֵרוֹ אֵינוֹ רוֹצֶה שֶׁתֵּדַע בּוֹ נְשָׁמָה אֶלָּא שְׁלִישִׁי שֶׁבֵּינֵיהֶם, לְפִיכָךְ כְּשֶׁהוּא מְכַחֵשׁ מְכַחֵשׁ בַּשְּׁלִישִׁי שֶׁבֵּינֵיהֶם (שם):
@106 **בתשומת יד.** שֶׁשָּׂם בְּיָדוֹ מָמוֹן לְהִתְעַסֵּק אוֹ בְּמִלְוֶה:
@106 **או בגזל.** שֶׁגָּזַל מִיָּדוֹ כְּלוּם:
@106 **או עשק.** הוּא שְֹכַר שָֹכִיר (שם):
@107 **וכחש בה.** שֶׁכָּפַר **על אחת מכל** אֵלֶּה **אשר יעשה האדם לחטא** וּלְהִשָּׁבַע עַל שֶׁקֶר לִכְפִירַת מָמוֹן:
@108 **כי יחטא ואשם.** כְּשֶׁיַּכִּיר בְּעַצְמוֹ לָשׁוּב בִּתְשׁוּבָה, וּבְדַעְתּוֹ לְהִתְוַדּוֹת כִּי חָטָא וְאָשֵׁם:
@109 **בראשו.** הוּא הַקֶּרֶן, רֹאשׁ הַמָּמוֹן:
@109 **וחמשתיו.** רִבְּתָה הַתּוֹרָה חֲמִישִׁיּוֹת הַרְבֵּה לְקֶרֶן אַחַת, שֶׁאִם כָּפַר בַּחֹמֶשׁ וְנִשְׁבַּע וְהוֹדָה, חוֹזֵר וּמֵבִיא חֹמֶשׁ עַל אוֹתוֹ חֹמֶשׁ, וְכֵן מוֹסִיף וְהוֹלֵךְ עַד שֶׁיִּתְמַעֵט הַקֶּרֶן הַנִּשְׁבָּע לוֹ פָּחוֹת מִשָּׁוֶה פְּרוּטָה (בבא קמא ק"ג):
@109 **לאשר הוא לו.** לְמִי שֶׁהַמָּמוֹן שֶׁלּוֹ (שם):

@1 **הקדמה:** הַסֵּפֶר הַזֶּה הוּא תּוֹרַת כֹּהֲנִים וְהַלְוִיִּם, יְבָאֵר בּוֹ עִנְיְנֵי הַקָּרְבָּנוֹת כֻּלָּן וּמִשְׁמֶרֶת הַמִּשְׁכָּן, כִּי כַּאֲשֶׁר הָיָה סֵפֶר אֶחָד בְּעִנְיַן הַגָּלוּת וְהַגְּאֻלָּה מִמֶּנּוּ, וְהִשְׁלִימוֹ בְּעִנְיַן אֹהֶל מוֹעֵד וּכְבוֹד הַשֵּׁם אֲשֶׁר מָלֵא אֶת הַמִּשְׁכָּן, צִוָּהוּ בַּקָּרְבָּנוֹת וּבִשְׁמִירַת הַמִּשְׁכָּן, שֶׁיִּהְיוּ הַקָּרְבָּנוֹת כַּפָּרָה לָהֶן וְלֹא יִגְרְמוּ הָעֲוֹנוֹת לְסִלּוּק הַשְּׁכִינָה. וְצִוָּה בַּכֹּהֲנִים הַנִּגָּשִׁים אֶל ה' שֶׁיִּתְקַדְּשׁוּ, שֶׁהִזְהִיר עַל טֻמְאַת מִקְדָּשׁ וְקָדָשָׁיו, וְגַם שֶׁלֹּא יֶהֶרְסוּ לַעֲלֹת אֶל ה', כְּמוֹ שֶׁאָמַר "דַּבֵּר אֶל אַהֲרֹן אָחִיךָ וְאַל יָבֹא בְכָל עֵת אֶל הַקֹּדֶשׁ מִבֵּית לַפָּרֹכֶת אֶל פְּנֵי הַכַּפֹּרֶת אֲשֶׁר עַל הָאָרֹן וְלֹא יָמוּת כִּי בֶּעָנָן אֵרָאֶה עַל הַכַּפֹּרֶת", כְּאַזְהָרַת "פֶּן יֶהֶרְסוּ אֶל ה' לִרְאוֹת וְנָפַל מִמֶּנּוּ רָב". ואח"כ יַגְבִּיל הַמִּשְׁכָּן כְּהַגְבָּלַת הַר סִינַי בְּעֵת הֱיוֹת שָׁם כְּבוֹד אֱלֹהֵי יִשְׂרָאֵל.
@1 וְהִנֵּה רֹב הַסֵּפֶר הַזֶּה בַּקָּרְבָּנוֹת, בְּתוֹרַת הַקָּרְבָּן וְהַמַּקְרִיבִין וּבַמָּקוֹם שֶׁיִּתְקָרֵב בּוֹ, וְיָבוֹאוּ בּוֹ קְצָת מִצְוֹת נִגְרָרוֹת עִם אֵלֶּה. כִּי מִתְּחִלָּה צִוָּה בְּקָרְבְּנוֹת הַנְּדָבָה, וְאָסַר הַחֵלֶב וְהַדָּם בַּעֲבוּרָם, וְאַחֲרֵי כֵן בְּקָרְבְּנוֹת הַחֵטְא, וְנִגְרָר אַחַר זֶה לְהַזְכִּיר הַמַּאֲכָלִים הָאֲסוּרִים, בַּעֲבוּר שֶׁהֵם מְטַמְּאִים וְהָאוֹכֵל אוֹ הַנּוֹגֵעַ בָּהֶן בְּכָל קֹדֶשׁ לֹא יִגָּע וְאֶל הַמִּקְדָּשׁ לֹא יָבֹא, וְאִם נִכְנַס שָׁם בְּטֻמְאָה יִהְיֶה חַיָּב קָרְבָּן עוֹלֶה וְיוֹרֵד שֶׁהִזְכִּירוֹ כְּבָר. וְהֻצְרַךְ לְהַזְכִּיר תּוֹרַת הַמְּצֹרָע וּמִשְׁפְּטֵי הַיּוֹלֶדֶת וְהַזָּב וְהַזָּבָה לְחַיֵּיב אוֹתָם בְּקָרְבָּן וּלְהַזְהִיר עוֹד מִטֻּמְאָתָם, כַּאֲשֶׁר אָמַר בְּסוֹפָם "וְהִזַּרְתֶּם אֶת בְּנֵי יִשְׂרָאֵל מִטֻּמְאָתָם וְלֹא יָמֻתוּ בְּטֻמְאָתָם בְּטַמְּאָם אֶת מִשְׁכָּנִי אֲשֶׁר בְּתוֹכָם". וְנִגְרָר אַחַר זֶה שֶׁיַּזְהִיר עַל הָעֲרָיוֹת, כִּי מִשְׁכָּבָם מְטַמֵּא וַעֲוֹנָם יִקָּרֵא טֻמְאָה, גּוֹרֶמֶת לְסִלּוּק הַשְּׁכִינָה וּלְגָלוּת. וְעוֹד כִּי הַשּׁוֹגֵג בָּהֶן מְחֻיָּב הַחַטָּאת שֶׁהִזְכִּיר כְּבָר בּוֹ "אִם נֶפֶשׁ אַחַת תֶּחֱטָא בִשְׁגָגָה". וְאַחֲרֵי כֵן הִזְכִּיר מִצְוַת הַשַּׁבָּת וּמוֹעֲדֵי ה', בַּעֲבוּר הַקָּרְבָּן, כְּמוֹ שֶׁאָמַר "אֵלֶּה מוֹעֲדֵי ה' אֲשֶׁר תִּקְרְאוּ אֹתָם מִקְרָאֵי קֹדֶשׁ לְהַקְרִיב אִשֶּׁה לַה' עֹלָה וּמִנְחָה זֶבַח וּנְסָכִים דְּבַר יוֹם בְּיוֹמוֹ". וְרֹב פָּרָשִׁיּוֹת הַסֵּפֶר הַזֶּה יְדַבֵּר בָּהֶן עִם הַכֹּהֲנִים, "דַּבֵּר אֶל אַהֲרֹן וְאֶל בָּנָיו" "צַו אֶת אַהֲרֹן וְאֶת בָּנָיו". וּבְפָרָשַׁת קְדוֹשִׁים תִּהְיוּ קְצָת מִצְוֹת לִבְנֵי יִשְׂרָאֵל, רֻבָּן נִגְרָרוֹת עִם עִנְיְנֵי הַקָּרְבָּנוֹת אוֹ בְּדוֹמִים לָהֶם, וּבִמְקוֹמָם אֲפָרֵשׁ בְּעֶזְרָתוֹ שֶׁל הב"ה.
@1 אָמַר הַכָּתוּב בְּכָאן **וַיִּקְרָא אֶל מֹשֶׁה וַיְדַבֵּר ה' אֵלָיו** וְלֹא כֵן בִּשְׁאָר הַמְּקוֹמוֹת, בַּעֲבוּר שֶׁלֹּא הָיָה מֹשֶׁה יָכוֹל לָבֹא אֶל אֹהֶל מוֹעֵד לִהְיוֹתוֹ נִגַּשׁ אֶל הַמָּקוֹם אֲשֶׁר שָׁם הָאֱלֹהִים, רַק בִּקְרִיאָה שֶׁיִּקְרָא אוֹתוֹ, שֶׁכְּבָר נֶאֱמַר לְמֹשֶׁה (שמות כה כב) "וְנוֹעַדְתִּי לְךָ שָׁם וְדִבַּרְתִּי אִתְּךָ מֵעַל הַכַּפֹּרֶת" (אשר אועד לך שמה), וְכֵיוָן שֶׁיָּדַע שֶׁהַשֵּׁם יוֹשֵׁב הַכְּרוּבִים שָׁם נִתְיָרֵא לָבֹא בָּאֹהֶל כְּלָל עַד שֶׁיִּקְרָא אֵלָיו, כַּאֲשֶׁר עָשָׂה בְּהַר סִינַי, שֶׁאָמַר (שם כד טז) "וַיִּקְרָא אֶל מֹשֶׁה בַּיּוֹם הַשְּׁבִיעִי מִתּוֹךְ הֶעָנָן". אוֹ שֶׁלֹּא הָיָה מֹשֶׁה יוֹדֵעַ שֶׁהַכָּבוֹד בָּאֹהֶל וְשֶׁיִּהְיֶה לוֹ הַדִּבּוּר מִשָּׁם, כִּי לֹא כִּסָּהוּ הֶעָנָן עַד יוֹם הַשְּׁמִינִי כְּדַעַת רַבּוֹתֵינוּ (ת"כ להלן טא), וְאַחֲרֵי הַקְּרִיאָה בָּא מֹשֶׁה בָּאֹהֶל לִפְנַי וְלִפְנִים, כְּמוֹ שֶׁדָּרְשׁוּ (תורת כהנים אחרי פרשה טז א), אַהֲרֹן בְּבַל יָבֹא וְאֵין מֹשֶׁה בְּבַל יָבֹא. וְאֵין זֶה דֶּרֶךְ פְּשָׁט בַּכָּתוּב הַזֶּה, וּכְבָר פֵּרַשְׁתִּיו לְמַעְלָה (שמות מ לד). וְרַבּוֹתֵינוּ אָמְרוּ (תורת כהנים פרשה א ז), כִּי לְכָל הַדִּבְּרוֹת וּלְכָל הָאֲמִירוֹת וּלְכָל הַצִּוּוּיִים קָדְמָה קְרִיאָה, כְּלוֹמַר שֶׁיֹּאמַר אֵלָיו "מֹשֶׁה מֹשֶׁה", וְיֹאמַר "הִנֵּנִי", וְזֶה דֶּרֶךְ חִבָּה וְזֵרוּז לְמֹשֶׁה. וְהִנֵּה עַל דַּעְתָּם הִזְכִּיר זֶה בְּכָאן בַּעֲבוּר שֶׁהוּא תְּחִלַּת הַדִּבּוּר אֲשֶׁר הָיָה אֵלָיו מֵאֹהֶל מוֹעֵד, לְלַמֵּד עַל כֻּלָּם, כִּי כֵן יִהְיֶה מִשְׁפָּטוֹ כָּל הַיָּמִים בְּכָל הַתּוֹרָה, וּ"מֵאֹהֶל מוֹעֵד" לְדַעְתָּם הוּא מֻקְדָּם, וַיִּקְרָא אֵלָיו מֵאֹהֶל מוֹעֵד וַיְדַבֵּר ה' אֵלָיו בָּאֹהֶל, כִּי מֹשֶׁה שָׁם הָיָה. וְשִׁעוּר הַכָּתוּב כְּפִי פְּשׁוּטוֹ וּמַשְׁמָעוֹ, וַיִּקְרָא ה' אֶל מֹשֶׁה וַיְדַבֵּר אֵלָיו מֵאֹהֶל מוֹעֵד. וְעַל דֶּרֶךְ הָאֱמֶת הוּא כְּמוֹ "וְאֶל מֹשֶׁה אָמַר עֲלֵה אֶל ה'" (שמות כד א), וְסוֹדוֹ יָדוּעַ מִמַּעֲמַד הַר סִינַי וּבַעֲשֶׂרֶת הַדִּבְּרוֹת, וּכְבָר רָמַזְתִּי לוֹ (שם):
@2 **אָדָם כִּי יַקְרִיב מִכֶּם קָרְבָּן לַה' מִן הַבְּהֵמָה** שִׁעוּר הַכָּתוּב הַזֶּה, אָדָם מִכֶּם כִּי יַקְרִיב מִן הַבְּהֵמָה קָרְבָּן לַה' מִן הַבָּקָר וּמִן הַצֹּאן תַּקְרִיבוּ. וְהָעִנְיָן בַּעֲבוּר שֶׁיְּצַוֶּה אַחֲרֵי כֵן בְּקָרְבַּן הָעוֹף וּבְקָרְבַּן הַמִּנְחָה, אָמַר כָּאן כְּשֶׁיַּקְרִיב אָדָם קָרְבַּן בְּהֵמָה יַקְרִיב מֵאֵלֶּה הַשְּׁנַיִם, וְלֹא חַיָּה וְלֹא שְׁאָר בְּהֵמוֹת. וְהִנֵּה זֶה לָאו הַבָּא מִכְּלַל עֲשֵׂה בְּמַקְרִיב חַיָּה, כְּמוֹ שֶׁאָמְרוּ בִּזְבָחִים פֶּרֶק שְׁלִישִׁי (לד), הַמַּעֲלֶה אֵבְרֵי חַיָּה, ר' יוֹחָנָן אוֹמֵר עוֹבֵר בַּעֲשֵׂה:
@2 **תַּקְרִיבוּ** מְלַמֵּד שֶׁשְּׁנַיִם מִתְנַדְּבִים עוֹלָה בְּשֻׁתָּפוּת. **קָרְבַּנְכֶם** מְלַמֵּד שֶׁהִיא בָּאָה נִדְבַת צִבּוּר, הִיא עוֹלַת קַיִץ הַמִּזְבֵּחַ הַבָּאָה מִן הַמּוֹתָרוֹת, לְשׁוֹן רַשִׁ"י (רש"י על ויקרא א':ב'). פֵּרֵשׁ הָרַב כֵּן לוֹמַר שֶׁאִם יִתְנַדְּבוּ רַבִּים לְהָבִיא עוֹלָה, עוֹלַת הַשֻּׁתָּפִין הִיא, מַה בֵּין שְׁנַיִם הַמִּשְׁתַּתְּפִין בְּקָרְבָּן וּבֵין עֲשָׂרָה וְאֶלֶף שֶׁנִּשְׁתַּתְּפוּ בּוֹ. אֲבָל קַיִץ הַמִּזְבֵּחַ הַבָּאָה מִן הַמּוֹתָרוֹת, לֵב ב"ד מַתְנֶה עֲלֵיהֶן, וּלְפִיכָךְ הִיא עוֹלַת צִבּוּר. וְהִנֵּה לְדַעְתּוֹ כָּל עוֹלָה שֶׁיָּבִיאוּ רַבִּים חוּץ מִן הַמּוֹתָרוֹת, דִּינָהּ כְּדִין עוֹלַת הַשֻּׁתָּפִין, וּטְעוּנָה סְמִיכָה בְּכֻלָּם וּנְסָכִים קְרֵבִים מִשֶּׁלָּהֶם. וְאוּלַי לְדַעְתּוֹ עוֹלַת הָעוֹף שֶׁהִיא בָּאָה נִדְבַת שְׁנַיִם וְאֵינָהּ בָּאָה נִדְבַת צִבּוּר, וְכֵן הַשְּׁלָמִים שֶׁאָמְרוּ בָּהֶם שֶׁהַשֻּׁתָּפִין מְבִיאִין אוֹתָם נְדָבָה וְאֵין הַצִּבּוּר מְבִיאִים אוֹתָם נְדָבָה (תורת כהנים פרק טז ה), בְּכֻלָּן יְכוֹלִין הָרַבִּים לְהִתְנַדֵּב לָהֶם בַּתְּחִלָּה, דְּעוֹלַת הַשֻּׁתָּפִין הִיא נִקְרֵאת וְשַׁלְמֵי שֻׁתָּפִין הֵם נִקְרָאִין, וְלֹא מִעֲטוּ אֶלָּא שֶׁלֹּא יָבִיאוּ אוֹתָן מִן הַקֻּפּוֹת. וְאֶפְשָׁר שֶׁנֹּאמַר שֶׁאִם רָצוּ צִבּוּר לְהַפְרִישׁ בַּתְּחִלָּה לִנְדָבָה וְיִגְבּוּ אוֹתָהּ כַּאֲשֶׁר יִגְבּוּ הַשְּׁקָלִים לִתְמִידִין וּמוּסָפִין, שֶׁתִּהְיֶה נִדְבַת צִבּוּר בְּעוֹלַת בְּהֵמָה, וְאֵין בָּהּ סְמִיכָה שֶׁנִּתְרַבָּה מִן הַכָּתוּב הַזֶּה, וְכָל זְמַן שֶׁיִּתְנַדְּבוּ בּוֹ רֹב יִשְׂרָאֵל הִיא נִדְבַת צִבּוּר, וְאֵינָהּ בְּעוֹלַת הָעוֹף וְלֹא בִּשְׁלָמִים, וּמִעוּטָן נִדּוֹנִין כִּיחִידִים, וְהוּא הָעִקָּר:
@4 **וְסָמַךְ יָדוֹ** בִּשְׁתֵּי יָדָיו, כִּי מָצָאנוּ "וְסָמַךְ אַהֲרֹן וּבָנָיו אֶת יְדֵיהֶם עַל רֹאשׁ הַפָּר" (שמות כט י), "וְסָמְכוּ אַהֲרֹן וּבָנָיו אֶת יְדֵיהֶם עַל רֹאשׁ הָאָיִל" (שם טו), וְדָרְשׁוּ בּוֹ יְדֵי כָּל יָחִיד וְיָחִיד, וְהִנֵּה הִיא בִּשְׁתֵּי יָדָיו. וּבְשָׂעִיר הַמִּשְׁתַּלֵּחַ מְפֹרָשׁ "וְסָמַךְ אַהֲרֹן אֶת שְׁתֵּי יָדָיו עַל רֹאשׁ הַשָּׂעִיר" (ויקרא ט"ז:כ"א), וְלֹא יָדַעְתִּי אִם כֵּן לָמָּה כָּתַב בְּכָל שְׁאָר הַסְּמִיכוֹת "אֶת יָדוֹ". וְאוּלַי לְהוֹצִיא מִמֶּנּוּ מַה שֶׁדָּרְשׁוּ (מנחות צג), "יָדוֹ" וְלֹא יַד שְׁלוּחוֹ, כִּי שֶׁמָּא הָיָה בַּמַּשְׁמָע "יָדָיו" לְהָבִיא אֶת שְׁתֵּיהֶן, וְלֹא נְמַעֵט בּוֹ הַשָּׁלִיחַ, אֲבָל עַכְשָׁו שֶׁהַסְּמִיכָה בִּשְׁתֵּי יָדָיו, לֹא כָּתַב לְשׁוֹן יָחִיד אֶלָּא לְמַעֵט הַשָּׁלִיחַ, שֶׁאַף עַל פִּי שֶׁשְּׁלוּחוֹ כְּמוֹתוֹ בִּשְׁאָר הַמְּקוֹמוֹת, לֹא נָדוּן כֵּן בִּסְמִיכָה. וּבְתוֹרַת כֹּהֲנִים (אחרי פרשה טז כא) "וְסָמַךְ אַהֲרֹן אֶת שְׁתֵּי יָדָיו" (ויקרא טז כא), מְלַמֵּד שֶׁהַסְּמִיכָה בִּשְׁתֵּי יָדַיִם, בִּנְיַן אָב לְכָל הַסְּמִיכוֹת שֶׁיִּהְיוּ בִּשְׁתֵּי יָדַיִם:
@4 **וְנִרְצָה לוֹ לְכַפֵּר עָלָיו** עַל מָה הוּא מְרַצֶּה לוֹ, אִם תֹּאמַר עַל כָּרֵתוֹת וּמִיתוֹת ב"ד אוֹ מִיתָה בִּידֵי שָׁמַיִם אוֹ מַלְקוּת, הֲרֵי עָנְשָׁן אָמוּר, הָא אֵינוֹ מְרַצֶּה אֶלָּא עַל עֲשֵׂה וְעַל לָאו שֶׁנִּתָּק לַעֲשֵֹה, לְשׁוֹן רַשִׁ"י (רש"י על ויקרא א':ד'). וּבָרַיְתָא הִיא בְּתוֹרַת כֹּהֲנִים (פרק ד ח). וַאֲנִי תָּמֵהַּ, וְכִי הֵיכָן עָנְשָׁן אָמוּר, כִּי הַקָּרְבָּנוֹת בַּשּׁוֹגְגִין הֵן מְרַצִּין. וְנוּכַל לוֹמַר שֶׁיְּכַפְּרוּ עַל חַיָּבֵי מִיתָה בִּידֵי שָׁמַיִם שׁוֹגְגִין וְעַל חַיָּבֵי מַלְקוּת שׁוֹגְגִין וְעַל חַיָּבֵי מִיתוֹת ב"ד שׁוֹגְגִין בְּאוֹתָן שֶׁאֵין חַיָּבִין עֲלֵיהֶם חַטָּאת, כְּגוֹן מַכֵּה אָבִיו וְאִמּוֹ וּמְקַלֵּל, כְּשֵׁם שֶׁהַחַטָּאת מְכַפֶּרֶת בְּחַיָּבֵי כְּרֵתוֹת שׁוֹגְגִין. וְאוּלַי בַּעֲבוּר שֶׁפֵּרֵשׁ הַכָּתוּב בְּחַיָּבֵי מִיתוֹת ב"ד וּבְחַיָּבֵי כְּרֵתוֹת עָנְשָׁן בְּמֵזִיד וּבְשׁוֹגֵג, וּפֵרֵשׁ בְּחַיָּבֵי מִיתָה בִּידֵי שָׁמַיִם עָנְשָׁן בְּמֵזִיד לְמִיתָה וּבְחַיָּבֵי לָאוִין לְמַלְקוּת וְלֹא פֵּרֵשׁ בָּהֶם שׁוּם עֹנֶשׁ בְּשׁוֹגֵג, נִרְאָה לָהֶם לַחֲכָמִים שֶׁכָּל הָעֹנֶשׁ שֶׁבָּהֶם פֵּרְשׁוֹ הַכָּתוּב, כִּי לָמָּה יְפָרֵשׁ עָנְשָׁן שֶׁל אֵלּוּ בְּמֵזִיד וּבְשׁוֹגֵג וִיפָרֵשׁ עֹנֶשׁ הָאֲחֵרִים בְּמֵזִיד וְלֹא יְפָרֵשׁ אוֹתוֹ בְּשׁוֹגֵג וְיֹאמַר שֶׁיְּהֵא מְחֻיָּב לְהָבִיא בָּהֶן עוֹלָה, וּלְכָךְ רָאוּ שֶׁאֵין בְּחַיָּבֵי מִיתָה בִּידֵי שָׁמַיִם וּבְחַיָּבֵי מַלְקוּת אֶלָּא עָנְשָׁן הַמְפֹרָשׁ בָּהֶן בְּמֵזִיד, אֲבָל בְּשׁוֹגֵג אֵין עֲלֵיהֶם שׁוּם נְשִׂיאוּת חֵטְא וְאֵין צְרִיכִין רִצּוּי כְּלָל. וְזֶהוּ שֶׁאָמְרוּ "כְּבָר עָנְשָׁן אָמוּר", שֶׁכָּל הָעֹנֶשׁ שֶׁרָצָה לְהַטִּיל עֲלֵיהֶם כְּבָר אֲמָרוֹ הַכָּתוּב, אֲבָל עַל עֲשֵׂה וְעַל לֹא תַעֲשֶׂה הַנִּתָּק לַעֲשֵׂה הַמְּזִידִין שֶׁלֹּא הִזְכִּיר בָּהֶם שׁוּם עֹנֶשׁ, וְאִי אֶפְשָׁר שֶׁלֹּא יֵעָנֵשׁ בָּהֶם, בָּזֶה יֵרָצֶה בָּעוֹלָה הַזּוֹ אִם יְבִיאֶנָּה בְּנִדְבַת נַפְשׁוֹ. וְיִתָּכֵן לוֹמַר כִּי בַּעֲבוּר שֶׁלֹּא הִזְכִּיר בְּקָרְבְּנוֹת הַנְּדָבָה "לְכַפֵּר עָלָיו עַל שִׁגְגָתוֹ אֲשֶׁר שָׁגָג" כַּאֲשֶׁר בְּקָרְבְּנוֹת הַחֵטְא, וְאָמַר "וְנִרְצָה", הָיָה לְרַבּוֹתֵינוּ בַּמַּשְׁמָעוּת הַזֶּה שֶׁיְּכַפֵּר עַל הַמְּזִידִים שֶׁאֵינָם רְצוּיִים לְפָנָיו, כִּי הַשּׁוֹגֵג אע"פ שֶׁחָטָא רְצוּי הַשֵּׁם הוּא, אִם כֵּן אִי אֶפְשָׁר לוֹ לְכַפֵּר עַל הַמְּזִידִים זוּלָתִי עַל עֲשֵׂה וְעַל לֹא תַעֲשֶׂה שֶׁנִּתָּק לַעֲשֵׂה שֶׁלֹּא נִזְכַּר בָּהֶם עֹנֶשׁ, אֶלָּא שֶׁאֵינָם רְצוּיִים לַמֶּלֶךְ בַּעֲבוּר שֶׁעָבְרוּ עַל מִצְוָתוֹ, וּבַמֶּה יִתְרַצּוּ אֶל אֲדוֹנֵיהֶם, בַּדּוֹרוֹן הַזֶּה. וְרָאִיתִי בְּאַגָּדָה בְּוַיִּקְרָא רַבָּה (ז ג), תָּנֵי רַבִּי שִׁמְעוֹן בֶּן יוֹחַאי, אֵין הָעוֹלָה בָּאָה אֶלָּא עַל הִרְהוּרֵי עֲבֵרַת הַלֵּב. אָמַר רַבִּי לֵוִי, מִקְרָא מָלֵא הוּא, "וְהָעוֹלָה עַל רוּחֲכֶם הָיֹה לֹא תִהְיֶה" (יחזקאל כ לב), הָעוֹלָה מְכַפֶּרֶת עַל הָעוֹלָה עַל רוּחֲכֶם. וְכֵן בְּאִיּוֹב הוּא אוֹמֵר, "וְהֶעֱלָה עֹלוֹת מִסְפַּר כֻּלָּם כִּי אָמַר אִיּוֹב אוּלַי חָטְאוּ בָנַי וּבֵרֲכוּ אֱלֹהִים בִּלְבָבָם" (איוב א ה), הָדָא אָמְרָה אֵין הָעוֹלָה בָּאָה אֶלָּא עַל הִרְהוּרֵי הַלֵּב. וְהַטַּעַם שֶׁלְּפִי שֶׁהוּא חֵטְא שֶׁאֵין מַכִּיר בּוֹ אֶלָּא ה' לְפִיכָךְ כֻּלָּהּ כָּלִיל לַה'. וּלְשׁוֹן "וְנִרְצָה לוֹ" יַחְזֹר אֶל הַשֵּׁם הַנִּכְבָּד הַנִּזְכָּר, שֶׁיִּתְרַצֶּה לוֹ בַּקָּרְבָּן הַזֶּה לְכַפֵּר עָלָיו, מִלְּשׁוֹן "וּבַמֶּה יִתְרַצֶּה זֶה אֶל אֲדֹנָיו" (שמואל א כט ד), "וְאוֹר פָּנֶיךָ כִּי רְצִיתָם" (תהלים מד ד), וְכֵן רַבִּים. וְיִתָּכֵן כִּי "וְנִרְצָה" כִּנּוּי לַחֵטְא, שֶׁנִּרְצָה לוֹ חֶטְאוֹ לְכַפֵּר עָלָיו, מִלְּשׁוֹן "כִּי נִרְצָה עֲוֹנָהּ" (ישעיהו מ ב), "עַד רָצְתָה הָאָרֶץ אֶת שַׁבְּתוֹתֶיהָ" (דהי"ב לו כא), "וְהֵם יִרְצוּ אֶת עֲוֹנָם" (ויקרא כו מג), לְשׁוֹן הַשְׁלָמָה. וְיִתָּכֵן שֶׁהוּא כָּעִנְיָן הָרִאשׁוֹן, כְּאִלּוּ הֶעָוֹן רָצוּי לִפְנֵי הַשֵּׁם, לֹא יִחַר אַפּוֹ בּוֹ עוֹד:
@5 **וְשָׁחַט וְהִקְרִיבוּ הַכֹּהֲנִים** מִקַּבָּלָה וְאֵילָךְ מִצְוַת כְּהֻנָּה, לִמֵּד עַל הַשְּׁחִיטָה שֶׁכְּשֵׁרָה בְּזָר. **וְהִקְרִיבוּ** זוֹ קַבָּלָה, וּמַשְׁמָעָהּ לְשׁוֹן הוֹלָכָה, לָמַדְנוּ שֶׁשְּׁתֵּיהֶן בִּבְנֵי אַהֲרֹן, לְשׁוֹן רַשִׁ"י (רש"י על ויקרא א':ה'). וְאֵינֶנּוּ נָכוֹן, אֶלָּא מִדְרַשׁ רַבּוֹתֵינוּ (תורת כהנים פרשה ד ד) "וְהִקְרִיבוּ" זוֹ קַבָּלַת הַדָּם, שֶׁאֵין לְשׁוֹן "וְהִקְרִיבוּ" קְרִיבַת הַדָּם לַמִּזְבֵּחַ שֶׁהִיא הַהוֹלָכָה, אֲבָל הוּא לְשׁוֹן קָרְבָּן, שֶׁיַּעֲשׂוּ מִן הַדָּם קָרְבָּן וְהוּא לְקַבְּלוֹ וּלְזָרְקוֹ עַל הַמִּזְבֵּחַ, כִּי הִזְכִּיר בְּבַעַל הַקָּרְבָּן הֲבָאָה וּסְמִיכָה וּשְׁחִיטָה, וְאַחֲרֵי הַשְּׁחִיטָה הִזְכִּיר "בְּנֵי אַהֲרֹן" מִיָּד, אִם כֵּן אַף הַקַּבָּלָה עַצְמָהּ מִצְוַת כְּהֻנָּה וְאֵינָהּ אֶלָּא בְּכֹהֵן כָּשֵׁר וּבִכְלִי שָׁרֵת, וְכָל שֶׁכֵּן הוֹלָכָה וּזְרִיקָה. וְעוֹד שֶׁהוֹלָכַת הָאֵבָרִים לַכֶּבֶשׁ פְּסוּלָה בְּזָר, שֶׁכָּךְ דָּרְשׁוּ (זבחים ד) "וְהִקְרִיב הַכֹּהֵן אֶת הַכֹּל וְהִקְטִיר הַמִּזְבֵּחָה" (ויקרא א':י"ג), זוֹ הוֹלָכַת אֵבָרִים לַכֶּבֶשׁ. אִם כֵּן אַף הוֹלָכַת הַדָּם צְרִיכָה כֹּהֵן בְּכִהוּנוֹ:
@6 **וְהִפְשִׁיט אֶת הָעוֹלָה** מִצְוָה שֶׁיַּפְשִׁיטֶנָּה כֻּלָּהּ וְאַחֲרֵי כֵּן יְנַתַּח אוֹתָהּ. וְאָמַר "וְהִפְשִׁיט וְנִתַּח" כִּי בְּבַעַל הַקָּרְבָּן יְדַבֵּר, כַּאֲשֶׁר אָמַר (ויקרא א':ד') "וְסָמַךְ וְשָׁחַט", כִּי הַהֶפְשֵׁט וְהַנִּתּוּחַ אֵינָן עֲבוֹדוֹת וּכְשֵׁרוֹת בְּזָר, וּלְכָךְ חָזַר אַחַר כָּךְ וְאָמַר "וְנָתְנוּ בְּנֵי אַהֲרֹן" (ויקרא א':ז'). וְכֵן רְחִיצַת הַקְּרָבַיִם כְּשֵׁרָה בְּזָר, וּלְכָךְ אָמַר "וְקִרְבּוֹ וּכְרָעָיו יִרְחַץ בַּמָּיִם" (ויקרא א':ט') בַּעַל הַקָּרְבָּן, וְאַחֲרֵי כֵן "וְהִקְטִיר הַכֹּהֵן". וְאָמַר לְשׁוֹן רַבִּים "וְנָתְנוּ" "וְעָרְכוּ" כִּי בְּכָל מִצְוֹת הַכְּהֻנָּה יֹאמַר כֵּן, בַּעֲבוּר שֶׁהַכֹּהֲנִים רַבִּים יֵאָסְפוּ בְּבֵית הַשֵּׁם לַעֲשׂוֹת הָעוֹלָה, וּבְרָב עָם הַדְרַת מֶלֶךְ (משלי יד כח), אֲבָל אֵינֶנּוּ עִכּוּב, שֶׁהֲרֵי לִמֵּד לְמַטָּה (ויקרא א':י"ב) "וְעָרַךְ הַכֹּהֵן אֹתָם":
@6 **וְהִפְשִׁיט וְנִתַּח וְנָתְנוּ בְּנֵי אַהֲרֹן אֵשׁ** אֵין זֶה הַסֵּדֶר, שֶׁהָרָאוּי שֶׁיַּעַרְכוּ הַכֹּהֲנִים הַמַּעֲרָכָה וְאַחֲרֵי כֵן יְנַתְּחוּ הָעוֹלָה, וְכָךְ הָיָה סֵדֶר הַמַּעֲרָכָה בְּתָמִיד (יומא לג). וְכֵן מַה שֶׁאָמַר (ויקרא א':ח') "וְעָרְכוּ בְּנֵי אַהֲרֹן הַכֹּהֲנִים אֵת הַנְּתָחִים אֶת הָרֹאשׁ וְאֶת הַפָּדֶר עַל הָעֵצִים אֲשֶׁר עַל הָאֵשׁ" וְאַחֲרֵי כֵן "וְהַקֶּרֶב וְהַכְּרָעַיִם יִרְחַץ בַּמָּיִם" (ויקרא א':ט') אֵין הַצַּוָּאָה שֶׁיַּעֲשֶׂה כַּסֵּדֶר הַזֶּה, כִּי הָעֲרִיכָה הִיא הַקְטָרַת הַנְּתָחִים שֶׁצִּוָּה לְמַטָּה (ויקרא א':ט') "וְהִקְטִיר הַכֹּהֵן אֶת הַכֹּל", וְאִם כֵּן אֵין הַסֵּדֶר שֶׁיַּעֲלֶה הַנְּתָחִים וְהָרֹאשׁ וְהַפֶּדֶר עַל הָאֵשׁ שֶׁבַּמִּזְבֵּחַ וְאַחֲרֵי כֵן יִרְחַץ הַקֶּרֶב וְהַכְּרָעַיִם וְיַקְטִירֵם, אֲבָל תְּחִלָּה יְנַתַּח וְיִרְחַץ וְאַחֲרֵי כֵן יַעֲלֶה הַכֹּל עַל הָאֵשׁ וְיַקְטִיר. אֲבָל עִנְיַן הַכָּתוּב שֶׁהִקְדִּים זְרִיקַת הַדָּם, לְלַמֵּד שֶׁהִיא קוֹדֶמֶת לְכָל דָּבָר, וְאַחֲרֵי כֵן צִוָּה בְּהַקְטָרַת הָאֵבָרִים, וְאָמַר שֶׁיַּפְשִׁיט וִינַתַּח לְהַעֲרִיךְ אוֹתָם עַל הָאֵשׁ אַחֲרֵי רְחִיצַת הַקֶּרֶב וְהַכְּרָעַיִם, וְאָז יַקְטִיר הַכֹּל כְּאַחַת, וְזֶהוּ שֶׁאָמַר "אֶת הַכֹּל". וְהַכַּוָּנָה שֶׁשָּׁנָה הַכָּתוּב בָּאֵבָרִים לוֹמַר "וְעָרְכוּ עֵצִים עַל הָאֵשׁ וְהִקְטִיר", לְלַמֵּד שֶׁאַחַר שֶׁיְּסַדְּרֵם עַל הָאֵשׁ לֹא יַנִּיחֵם עַד שֶׁיְּבַעֵר בָּהֶם הָאֵשׁ וְיֹאכַל אוֹתָם וְתַעֲלֶה מֵהֶם הַקְּטֹרֶת. וְכֵן מַה שֶׁהִקְדִּים הֶפְשֵׁט וְנִתּוּחַ לְמַעֲרֶכֶת הָאֵשׁ, לְלַמֵּד שֶׁאֵין בְּעוֹלַת הַנְּדָבָה חוֹבָה לְהַקְדִּים לָהּ מַעֲרָכָה כְּעוֹלַת הַתָּמִיד שֶׁנִּצְטַוִּינוּ (ויקרא ו':ה') "וּבִעֵר עָלֶיהָ הַכֹּהֵן עֵצִים בַּבֹּקֶר בַּבֹּקֶר", וְהִיא קוֹדֶמֶת לְכָל דְּבַר הַמִּזְבֵּחַ כְּמוֹ שֶׁמְּפֹרָשׁ בְּמַסֶּכֶת יוֹמָא (יומא ל"ג):
@8 **אֶת הַפָּדֶר** תִּרְגֵּם אוּנְקְלוֹס (תרגום אונקלוס על ויקרא א':ח') "תַּרְבָּא", וְכֵן דִּבְרֵי כָּל הַמְפָרְשִׁים פֶּה אֶחָד. וְאֵין לַמִּלָּה חָבֵר. וּלְפִי דַּעְתִּי שֶׁאֵינֶנּוּ שֵׁם לַחֲלָבִים כֻּלָּם, רַק לַחֵלֶב הַדַּק הַפָּרוּס וּמַבְדִּיל בֵּין הַקְּרָבַיִם, וְהַמִּלָּה מִן הַהֲפוּכִים, פֶּדֶר - פֶּרֶד, שֶׁמַּפְרִיד בֵּין הַקְּרָבַיִם הָעֶלְיוֹנִים לַתַּחְתּוֹנִים. וּלְכָךְ אָמְרוּ רַבּוֹתֵינוּ (יומא כו), שֶׁיְּהֵא פּוֹרֵס הַפֶּדֶר עַל בֵּית הַשְּׁחִיטָה, שֶׁזֶּהוּ דֶּרֶךְ כָּבוֹד שֶׁל מַעְלָה, שֶׁהַחֵלֶב הַהוּא רָאוּי לְפָרְסוֹ וּלְכַסּוֹת בּוֹ. וְכֵן נָהֲגוּ חֲשׁוּבֵי הָאֻמּוֹת לְפָרְסוֹ עַל הַצָּלִי. וְאִם יִהְיֶה שֵׁם לַחֲלָבִים כֻּלָּם, יִקָּרֵא הַחֵלֶב כֵּן בַּעֲבוּר שֶׁהוּא הַשֻּׁמָּן הַנִּפְרָד מִן הַבָּשָׂר, וְכֵן הוּא כִּנּוּיוֹ בְּפִי חַכְמֵי הַטֶּבַע כַּאֲשֶׁר אַזְכִּיר (רמב"ן על ויקרא ג':ט'):
@9 **עוֹלָה** לְשֵׁם עוֹלָה, **אִשֶּׁה** כְּשֶׁיִּשְׁחָטֶנּוּ יְהֵא שׁוֹחֵט לְשֵׁם הָאֵשׁ, וְכָל אִשֶּׁה לְשׁוֹן אֵשׁ. **נִיחוֹחַ** נַחַת רוּחַ לְפָנַי שֶׁאָמַרְתִּי וְנַעֲשָׂה רְצוֹנִי, לְשׁוֹן רַשִׁ"י (רש"י על ויקרא א':ט'). וְלֹא פֵּרֵשׁ הָרַב מַהוּ לְשֵׁם הָאֵשׁ. וּבַגְּמָרָא (זבחים מו) אָמְרוּ, לְאַפּוֹקֵי כְּבָבָא דְּלָא. וּפֵרְשׁוּ בּוֹ שֶׁיִּשְׁחָטֶנּוּ עַל מְנָת לְהַעֲלוֹתוֹ עַל גַּבֵּי אֵשׁ בּוֹעֶרֶת בַּמַּעֲרָכָה, לֹא לְהַעֲלוֹת עַל גַּבֵּי גֶּחָלִים עוֹמְמוֹת שֶׁמִּתְכַּבּוֹת וְהוֹלְכוֹת. וְלִי נִרְאֶה שֶׁצָּרִיךְ לְכַוֵּן שֶׁתֹּאכְלֶנּוּ הָאֵשׁ לְגַמְרֵי, לֹא שֶׁיִּצָּלֶה שָׁם מְעַט, וְהוּא מִלְּשׁוֹנָם בְּבֵן סוֹרֵר וּמוֹרֶה (סנהדרין ע), כִּבְשַׂר כִּיבָא דְּאָכְלֵי גַּנָּבֵי, וּבְמַסֶּכֶת עֵרוּבִין (כט) וְנִכְבִּיב וְנֵכוּל. וְיֵשׁ גּוֹרְסִים שָׁם (זבחים מו) לְאַפּוֹקֵי גְּבָבָא דְּלָא, שֶׁיִּתְכַּוֵּן לְהַעֲלוֹתוֹ עַל גַּבֵּי אֵשׁ שֶׁל עֵצִים, כְּדִכְתִיב "עַל הָעֵצִים אֲשֶׁר עַל הָאֵשׁ", וְלֹא יַחְשֹׁב לְהַעֲלוֹתוֹ עַל גַּבֵּי אֵשׁ שֶׁל קַשׁ וְשֶׁל גְּבָבָא, כְּעִנְיָן שֶׁשָּׁנִינוּ (שבת לו), כִּירָה שֶׁהִסִּיקוּהָ בְּקַשׁ וּבִגְבָבָא. וְהִנֵּה בַּכָּתוּב הַזֶּה טַעַם הַקָּרְבָּנוֹת שֶׁהֵם אִשֵּׁה רֵיחַ נִיחֹחַ לַה'. וְאָמַר הָרַב בְּמוֹרֶה הַנְּבֻכִים (ג מו) כִּי טַעַם הַקָּרְבָּנוֹת בַּעֲבוּר שֶׁהַמִּצְרִים וְהַכַּשְׂדִּים אֲשֶׁר הָיוּ יִשְׂרָאֵל גֵּרִים וְתוֹשָׁבִים בְּאַרְצָם מֵעוֹלָם, הָיוּ עוֹבְדִים לַבָּקָר וְלַצֹּאן, כִּי הַמִּצְרִים עוֹבְדִים לַטָּלֶה וְהַכַּשְׂדִּים עוֹבְדִים לַשֵּׁדִים אֲשֶׁר יֵרָאוּ לָהֶם בִּדְמוּת שְׂעִירִים, וְאַנְשֵׁי הוֹדוּ עַד הַיּוֹם לֹא יִשְׁחֲטוּ בָּקָר לְעוֹלָם. בַּעֲבוּר כֵּן צִוָּה לִשְׁחֹט אֵלֶּה הַשְּׁלֹשָׁה מִינִין לַשֵּׁם הַנִּכְבָּד, כְּדֵי שֶׁיִּוָּדַע כִּי הַדָּבָר שֶׁהָיוּ חוֹשְׁבִים כִּי הֵם בְּתַכְלִית הָעֲבֵרָה, הוּא אֲשֶׁר יַקְרִיבוּ לַבּוֹרֵא וּבוֹ יִתְכַּפְּרוּ הָעֲוֹנוֹת, כִּי כֵן יִתְרַפְּאוּ הָאֱמוּנוֹת הָרָעוֹת שֶׁהֵם מַדְוֵי הַנֶּפֶשׁ, כִּי כָל מַדְוֶה וְכָל חֹלִי לֹא יִתְרַפֵּא כִּי אִם בְּהֶפְכּוֹ, אֵלֶּה דְּבָרָיו וּבָהֶם הֶאֱרִיךְ. וְהִנֵּה הֵם דִּבְרֵי הֲבַאי, יְרַפְּאוּ שֶׁבֶר גָּדוֹל וְקֻשְׁיָא רַבָּה עַל נְקַלָּה, יַעֲשׂוּ שֻׁלְחַן ה' מְגֹאָל, שֶׁאֵינֶנּוּ רַק לְהוֹצִיא מִלִּבָּן שֶׁל רְשָׁעִים וְטִפְּשֵׁי עוֹלָם, וְהַכָּתוּב אָמַר כִּי הֵם לֶחֶם אִשֶּׁה לְרֵיחַ נִיחֹחַ, וְגַם כִּי לְפִי שְׁטוּתָם שֶׁל מִצְרִים לֹא תִּתְרַפֵּא מַחֲלָתָם בָּזֶה אֲבָל תּוֹסִיף מַכְאוֹב, כִּי מַחְשֶׁבֶת הָרְשָׁעִים הַנִּזְכָּרִים לַעֲבֹד לְמַזַּל טָלֶה וּמַזַּל שׁוֹר שֶׁיֵּשׁ לָהֶם כֹּחַ בָּהֶם כְּפִי מַחְשַׁבְתָּם, וְלָכֵן לֹא יֹאכְלוּ אוֹתָם לִכְבוֹד כֹּחָם וִיסוֹדָם, אֲבָל אִם יִזְבְּחוּ אוֹתָם לַשֵּׁם הַנִּכְבָּד זֶה כָּבוֹד לָהֶם וּמַעֲלָה, וְהֵם עַצְמָם כָּךְ הֵם נוֹהֲגִים, כְּמוֹ שֶׁאָמַר (ויקרא יז ז) "וְלֹא יִזְבְּחוּ עוֹד אֶת זִבְחֵיהֶם לַשְּׂעִירִם", וְעוֹשֵׂי הָעֵגֶל זָבְחוּ לוֹ. וְהָרַב מַזְכִּיר שֶׁהָיוּ מַקְרִיבִים לַלְּבָנָה בְּכָל רָאשֵׁי חָדְשֵׁיהֶם, וְלַשֶּׁמֶשׁ בַּעֲלוֹתָהּ בַּמַּזָּלוֹת הַיְּדוּעִים לָהֶם בְּסִפְרֵיהֶם, וְיוֹתֵר תִּתְרַפֵּא הַמַּחֲלָה בְּאָכְלֵנוּ מֵהֶם לָשֹׂבַע, שֶׁהוּא אָסוּר לָהֶם וּמְגֻנֶּה בְּעֵינֵיהֶם וְלֹא יַעֲשׂוּ כֵן לְעוֹלָם. וְהִנֵּה נֹחַ בְּצֵאתוֹ מִן הַתֵּבָה עִם שְׁלֹשֶׁת בָּנָיו, אֵין בָּעוֹלָם כַּשְׂדִּי אוֹ מִצְרִי, הִקְרִיב קָרְבָּן וַיִּיטַב בְּעֵינֵי ה', וְאָמַר בּוֹ (בראשית ח כא) "וַיָּרַח ה' אֶת רֵיחַ הַנִּיחֹחַ", וּמִמֶּנּוּ אָמַר אֶל לִבּוֹ "לֹא אֹסִף לְקַלֵּל עוֹד אֶת הָאֲדָמָה בַּעֲבוּר הָאָדָם" (שם). "וְהֶבֶל הֵבִיא גַם הוּא מִבְּכֹרוֹת צֹאנוֹ וּמֵחֶלְבֵהֶן וַיִּשַׁע ה' אֶל הֶבֶל וְאֶל מִנְחָתוֹ" (שם ד ד), וְלֹא הָיָה עֲדַיִן בָּעוֹלָם שֶׁמֶץ ע"ז כְּלָל. וּבִלְעָם אָמַר "אֶת שִׁבְעַת הַמִּזְבְּחֹת עָרַכְתִּי וָאַעַל פָּר וָאַיִל בַּמִּזְבֵּחַ" (במדבר כג ד), וְאֵין דַּעְתּוֹ עַתָּה לִשְׁלֹל מִמֶּנּוּ אֱמוּנוֹת רָעוֹת וְלֹא נִצְטַוָּה בְּכָךְ, אֲבָל עָשָׂה כֵן לְקָרְבָה אֶל הָאֱלֹהִים כְּדֵי שֶׁיָּחוּל עָלָיו הַדִּבּוּר. וּלְשׁוֹן הַקָּרְבָּנוֹת "אֶת קָרְבָּנִי לַחְמִי לְאִשַּׁי רֵיחַ נִיחֹחִי" (שם כח ב), וְחָלִילָה שֶׁלֹּא יְהֵא בָּהֶם שׁוּם תּוֹעֶלֶת וְרָצוֹן, רַק שׁוֹלְלוּת ע"ז מִדַּעַת הַשּׁוֹטִים. וְיוֹתֵר רָאוּי לִשְׁמֹעַ הַטַּעַם שֶׁאוֹמְרִים בָּהֶם כִּי בַּעֲבוּר שֶׁמַּעֲשֵׂי בְּנֵי אָדָם נִגְמָרִים בְּמַחְשָׁבָה וּבְדִבּוּר וּבְמַעֲשֶׂה, צִוָּה הַשֵּׁם כִּי כַּאֲשֶׁר יֶחֱטָא יָבִיא קָרְבָּן יִסְמֹךְ יָדָיו עָלָיו כְּנֶגֶד הַמַּעֲשֶׂה, וְיִתְוַדֶּה בְּפִיו כְּנֶגֶד הַדִּבּוּר, וְיִשְׂרֹף בָּאֵשׁ הַקֶּרֶב וְהַכְּלָיוֹת שֶׁהֵם כְּלֵי הַמַּחֲשָׁבָה וְהַתַּאֲוָה, וְהַכְּרָעַיִם כְּנֶגֶד יָדָיו וְרַגְלָיו שֶׁל אָדָם הָעוֹשִׂים כָּל מְלַאכְתּוֹ, וְיִזְרֹק הַדָּם עַל הַמִּזְבֵּחַ כְּנֶגֶד דָּמוֹ בְּנַפְשׁוֹ, כְּדֵי שֶׁיַּחְשֹׁב אָדָם בַּעֲשׂוֹתוֹ כָּל אֵלֶּה כִּי חָטָא לֵאלֹהָיו בְּגוּפוֹ וּבְנַפְשׁוֹ וְרָאוּי לוֹ שֶׁיִּשָּׁפֵךְ דָּמוֹ וְיִשָּׂרֵף גּוּפוֹ, לוּלֵא חֶסֶד הַבּוֹרֵא שֶׁלָּקַח מִמֶּנּוּ תְּמוּרָה וְכֹפֶר הַקָּרְבָּן הַזֶּה, שֶׁיְּהֵא דָּמוֹ תַּחַת דָּמוֹ נֶפֶשׁ תַּחַת נֶפֶשׁ, וְרָאשֵׁי אֵיבְרֵי הַקָּרְבָּן כְּנֶגֶד רָאשֵׁי אֵיבָרָיו, וְהַמָּנוֹת לְהַחֲיוֹת בָּהֶן מוֹרֵי הַתּוֹרָה שֶׁיִּתְפַּלְּלוּ עָלָיו. וְקָרְבַּן הַתָּמִיד בַּעֲבוּר שֶׁלֹּא יִנָּצְלוּ הָרַבִּים מֵחֲטוֹא תָּמִיד. וְאֵלֶּה דְּבָרִים מִתְקַבְּלִים מוֹשְׁכִים אֶת הַלֵּב כְּדִבְרֵי אַגָּדָה. וְעַל דֶּרֶךְ הָאֱמֶת יֵשׁ בַּקָּרְבָּנוֹת סוֹד נֶעֱלָם, תִּכָּנֵס בּוֹ מִמַּה שֶׁאָמְרוּ רַבּוֹתֵינוּ בְּסִפְרֵי (פנחס קמג) וּבְסוֹף מְנָחוֹת (קי), אָמַר שִׁמְעוֹן בֶּן עַזַּאי, בֹּא וּרְאֵה מַה כְּתִיב בְּפ' הַקָּרְבָּנוֹת, שֶׁלֹּא נֶאֱמַר בָּהֶם לֹא "אֵל" וְלֹא "אֱלֹהֶיךָ" וְלֹא "אֱלֹהִים" וְלֹא "שַׁדַּי" וְלֹא "צְבָאוֹת", אֶלָּא יוֹ"ד הֵ"א שֵׁם הַמְּיֻחָד, שֶׁלֹּא לִתֵּן פִּתְחוֹן פֶּה לְבַעַל הַדִּין לַחְלֹק. וְשֶׁמָּא תֹּאמַר לַאֲכִילָה הוּא צָרִיךְ, תַּלְמוּד לוֹמַר "אִם אֶרְעַב לֹא אֹמַר לָךְ כִּי לִי תֵבֵל וּמְלֹאָהּ" (תהלים נ יב), לֹא אָמַרְתִּי לָכֶם זְבוֹחוּ אֶלָּא כְּדֵי שֶׁיֵּאָמֵר וְיֵעָשֶׂה רְצוֹנִי. וּבִתְחִלַּת תּוֹרַת כֹּהֲנִים (פרשה ב ה), רַבִּי יוֹסֵי אוֹמֵר, כָּל מָקוֹם שֶׁנֶּאֱמַר "קָרְבָּן" אָמוּר בְּיוֹ"ד הֵ"א, שֶׁלֹּא לִתֵּן פִּתְחוֹן פֶּה לָאֶפִּיקוֹרְסִים לִרְדּוֹת. אֵלּוּ דִּבְרֵיהֶם זַ"ל. וֶאֱמֶת כִּי בְּפָרָשַׁת הַקָּרְבָּנוֹת לֹא נֶאֱמַר לֹא "אֵל" וְלֹא "אֱלֹהִים", אֲבָל מָצָאנוּ "וְהַעֲלִיתָ עָלָיו עוֹלֹת לַה' אֱלֹהֶיךָ" (דברים כז ו), וּכְתִיב "לֶחֶם אֱלֹהֵיהֶם הֵם מַקְרִיבִם" (ויקרא כ"א:ו'), "וְקִדַּשְׁתּוֹ כִּי אֶת לֶחֶם אֱלֹהֶיךָ הוּא מַקְרִיב" (שם ח), וְכָתוּב בַּמִּזְמוֹר הַנִּזְכָּר "זְבַח לֵאלֹהִים תּוֹדָה" (תהלים נ יד), וְעוֹד כָּתוּב (דהי"ב כט ו-ז) "כִּי מָעֲלוּ אֲבֹתֵינוּ וְעָשׂוּ הָרַע בְּעֵינֵי ה' אֱלֹהֵינוּ גַּם סָגְרוּ דַּלְתוֹת הָאוּלָם וַיְכַבּוּ אֶת הַנֵּרוֹת וּקְטֹרֶת לֹא הִקְטִירוּ וְעֹלָה לֹא הֶעֱלוּ בַקֹּדֶשׁ לֵאלֹהֵי יִשְׂרָאֵל". אֲבָל הָעִנְיָן כֻּלּוֹ מְבֹאָר בַּתּוֹרָה, שֶׁנֶּאֱמַר (במדבר כח ב) "אֶת קָרְבָּנִי לַחְמִי לְאִשַּׁי", וְאָמַר (ויקרא ג':י"א) "לֶחֶם אִשֶּׁה", שֶׁהֵם לֶחֶם לְאִשֶּׁה וּמִמֶּנּוּ לָאִשִּׁים, וְ"אִשֶּׁה" לְשׁוֹן אֵשׁ. וְאָמַר ר"א (אבן עזרא על ויקרא א':ט') "אִשֶּׁה" שֵׁם הַתֹּאַר, וְטַעְמוֹ קָרְבַּן אֵשׁ, וְהוּא תֹּאַר לְמִלַּת "הַכֹּל", וּבַמִּנְחָה שֶׁאָמַר (ויקרא ב':ב') "וְהִקְטִיר הַכֹּהֵן אֶת אַזְכָּרָתָהּ אִשֵּׁה רֵיחַ נִיחֹחַ לַה'" יִהְיֶה תֹּאַר לַקֹּמֶץ. וְאֵינוֹ כֵן, אֲבָל "אִשֶּׁה" שֵׁם, כְּמוֹ אֵשׁ, וְ"עוֹלָה אִשֶּׁה" כְּמוֹ עוֹלַת אֵשׁ רֵיחַ נִיחוֹחַ לַה', וְכֵן כֻּלָּם, כִּי טַעְמָם כְּמוֹ "לֶחֶם אִשֶּׁה" (להלן ג יא טז). אֲבָל לֹא אָמַר אֵשׁ וְאָמַר אִשֶּׁה כְּמַשְׁמָעוֹ כַּאֲשֶׁר הֶרְאָה אֹתְךָ בָּהָר בְּמַתַּן תּוֹרָה. וְהִנֵּה הַקָּרְבָּן בְּמִדַּת הַדִּין, וְהַזְּבִיחָה לְשֵׁם ה' לְבַדּוֹ, שֶׁלֹּא יִתְכַּוֵּן לְדָבָר אַחֵר בָּעוֹלָם רַק לְשֵׁם ה' לְבַדּוֹ. וְזֶה טַעַם "עוֹלָה הוּא אִשֶּׁה", וּלְכָךְ אָמַר הַכָּתוּב (ויקרא כ"א:ו') "כִּי אֶת אִשֵּׁי ה' לֶחֶם אֱלֹהֵיהֶם הֵם מַקְרִיבִם וְהָיוּ קֹדֶשׁ", כִּי לְאִשֵּׁי ה' קָרְבַּן אֱלֹהִים. וּלְכָךְ אָמְרוּ שֶׁלֹּא הִזְכִּיר בַּצַּוָּאוֹת שֶׁל קָרְבָּנוֹת לֹא "אֵל" וְלֹא "אֱלֹהִים" אֶלָּא "אִשֵּׁה רֵיחַ נִיחוֹחַ לַה'" כִּי הַכַּוָּנָה לַה' לְבַדּוֹ תִּהְיֶה, לֹא יְכַוֵּן הַמַּקְרִיב וְלֹא יַעֲלֶה בְּמַחְשַׁבְתּוֹ רַק לַשֵּׁם הַמְּיֻחָד. וְהוּא מַאֲמַר הַחֲכָמִים (סנהדרין ס), רִיקֵן כָּל הָעֲבוֹדוֹת כֻּלָּן לַשֵּׁם הַמְיֻחָד. וּבְתוֹרַת כֹּהֲנִים (סוף פרק ו), "לַה'" לְשֵׁם מִי שֶׁעָשָׂה אֶת הָעוֹלָם. וְהוּא מַה שֶׁאָמַר הַמִּזְמוֹר "זְבַח לֵאלֹהִים תּוֹדָה וְשַׁלֵּם לְעֶלְיוֹן נְדָרֶיךָ" (תהלים נ יד) "כִּי ה' עֶלְיוֹן נוֹרָא מֶלֶךְ גָּדוֹל עַל כָּל הָאָרֶץ" (שם מז ג), וְאֵין נוֹדְרִין אֶלָּא לִשְׁמוֹ הַמְיֻחָד, וְהוּא מַה שֶׁאָמַר "אֱלֹהִים אֱלֹהֶיךָ אָנֹכִי לֹא עַל זְבָחֶיךָ אוֹכִיחֶךָ" (תהלים נ ז ח), כַּאֲשֶׁר אָמַר "אָנֹכִי ה' אֱלֹהֶיךָ" (שמות כ ב). וְזֶה טַעַם הַמִּזְמוֹר כֻּלּוֹ, שֶׁאָמַר "אֵל אֱלֹהִים ה' דִּבֶּר וַיִּקְרָא אָרֶץ" וְגוֹ' (תהלים נ א), שֶׁהִזְכִּיר שֵׁם מָלֵא עַל עוֹלָם מָלֵא, וְהִזְכִּיר בָּהֶם הַקָּרְבָּנוֹת, וְהוּא שֶׁנֶּאֱמַר (ישעיהו ס ז) "יַעֲלוּ עַל רָצוֹן מִזְבְּחִי וּבֵית תִּפְאַרְתִּי אֲפָאֵר", לֵאמֹר שֶׁיִּהְיוּ הַקָּרְבָּנוֹת עַל הָרָצוֹן שֶׁהוּא מִזְבְּחוֹ וּבֵית תִּפְאַרְתּוֹ יְפָאֵר בַּעֲלוֹתָם לְרֵיחַ נִיחוֹחַ. וְהִנֵּה "נִיחוֹחַ" מִן "נָחָה רוּחַ אֵלִיָּהוּ עַל אֱלִישָׁע" (מלכים ב ב טו), "וַתָּנַח עֲלֵיהֶם הָרוּחַ" (במדבר יא כו), וְכָל קָרְבָּן לְשׁוֹן קְרִיבָה וְאַחְדוּת, וּלְכָךְ אָמַר "וְעֹלָה לֹא הֶעֱלוּ בַקֹּדֶשׁ לֵאלֹהֵי יִשְׂרָאֵל" כִּי הָעוֹלָה בַּקֹּדֶשׁ תִּהְיֶה לֵאלֹהֵי יִשְׂרָאֵל. וְהַמַּלְאָךְ לִמֵּד לְמָנוֹחַ עִנְיַן הַקָּרְבָּנוֹת. אָמַר "אִם תַּעְצְרֵנִי לֹא אֹכַל בְּלַחְמֶךָ" (שופטים יג טז), שֶׁאִם יַעֲשֶׂה לוֹ לֶחֶם לֹא יְקַבֵּל מִמֶּנּוּ, כִּי הוּא פִּגּוּל וְזֶבַח תּוֹעֵבָה לַשֵּׁם, אֲבָל אִם תַּעֲשֶׂה עוֹלָה לַה' לְבַדּוֹ תַּעֲלֶנָּה, וְתִהְיֶה לְרָצוֹן עַל אִשֶּׁה ה'. וְאָז עָלָה בְּלַהַב הַמִּזְבֵּחַ. וְהִנֵּה הָעִנְיָן מְפֹרָשׁ וּמְבֹאָר, וַה' הַטּוֹב יְכַפֵּר בְּעַד:
@10 **וְאִם מִן הַצֹּאן קָרְבָּנוֹ** הַפָּרָשָׁה הַזּוֹ (פסוקים י-יג) בְּעוֹלַת הַצֹּאן וְדִינָהּ כְּדִין עוֹלַת הַבָּקָר בְּכָל מַעֲשֶׂה, וּלְכָךְ קִצֵּר בְּכָאן וְלֹא הִזְכִּיר "וְסָמַךְ וְנִרְצָה". וְהוֹסִיף לוֹמַר "עַל יֶרֶךְ הַמִּזְבֵּחַ צָפֹנָה לִפְנֵי ה'" (ויקרא א':י"א) לְבָאֵר כִּי לִפְנֵי ה' שֶׁכָּתוּב בְּבֶן הַבָּקָר (ויקרא א':ה') הוּא יֶרֶךְ הַמִּזְבֵּחַ בַּצָּפוֹן, וּפֵרוּשׁ "יֶרֶךְ הַמִּזְבֵּחַ" - צִדּוֹ, וְהוּא בַּצָּפוֹן, לִמֵּד כִּי כֶּבֶשׁ הַמִּזְבֵּחַ בַּדָּרוֹם וְשָׁם פְּנֵי הַמִּזְבֵּחַ שֶׁנֶּאֱמַר בָּהֶן "לִפְנֵי ה' אֶל פְּנֵי הַמִּזְבֵּחַ" (ויקרא ו':ז'). וְטַעַם הַשְּׁחִיטָה שֶׁהִיא בַּצָּפוֹן כְּבָר פֵּרַשְׁתִּי. וְאָמַר סְתָם "עַל הַמִּזְבֵּחַ סָבִיב" כִּי הוּא הַמִּזְבֵּחַ הַנִּזְכָּר (ויקרא א':ה') אֲשֶׁר פֶּתַח אֹהֶל מוֹעֵד. וְלֹא הִזְכִּיר "וְהִפְשִׁיט", שֶׁכְּבָר הֻזְכַּר (ויקרא א':ו'). וְאָמַר "וְעָרַךְ הַכֹּהֵן אֹתָם" לְלַמֵּד כִּי דַּי בְּכֹהֵן אֶחָד כְּמוֹ שֶׁפֵּרַשְׁתִּי (רמב"ן על ויקרא א':ו'), כִּי הַפָּרָשִׁיּוֹת לְמֵדוֹת זוֹ מִזּוֹ, מַה שֶׁיְּחַסֵּר בְּאַחַת יְבָאֵר בָּאַחֶרֶת:
@14 **מִן הַתֹּרִים אוֹ מִן בְּנֵי הַיּוֹנָה** בָּחַר הַכָּתוּב בִּשְׁנֵי הַמִּינִים הָאֵלֶּה בִּשְׁבִיל שֶׁהֵן מְצוּיִין וּקְרוֹבִים לְהִתָּפֵשׂ יוֹתֵר, כַּאֲשֶׁר הִזְכִּירוּ רַבּוֹתֵינוּ (ויקרא רבה כז ו), "שֵׂה כְשָׂבִים וְשֵׂה עִזִּים", שֶׁיַּקְרִיב מִן הַגְּדֵלִים עַל אֲבוּסוֹ וְלֹא יִצְטָרֵךְ לָשֵׂאת כֵּלָיו תִּלְיוֹ וְקַשְׁתּוֹ לָצוּד צַיִד לְהָבִיא. אֲבָל רָצָה בַּתּוֹרִים הַגְּדוֹלִים בַּעֲבוּר פְּרִישׁוּתָן וְהִדָּבְקָם, כַּיָּדוּעַ מֵהֶם שֶׁכֵּיוָן שֶׁאָבַד בֶּן זוּגוֹ לֹא יִדְבַּק בְּאַחֵר לְעוֹלָם, וְכֵן יִשְׂרָאֵל דְּבוּקִים בַּה' אֱלֹהֵיהֶם וְלֹא יִדְבְּקוּ בְּאֵל אַחֵר לְעוֹלָם. אֲבָל הַיּוֹנִים קַנָּאִים מְאֹד, וּבְקִנְאָתָם יִתְפָּרְדוּ וְיַחֲלִיפוּ, עַל כֵּן לֹא בָּחַר בָּהֶם אֶלָּא הַקְּטַנִּים קֹדֶם שֶׁיִּזְדַּוְּגוּ, כִּי הַיּוֹנָה בְּקַטְנוּתָהּ אָז תּוֹפֶסֶת אַהֲבָה בְּקֵן גִּדּוּלֶיהָ יוֹתֵר מִשְּׁאָר הָעוֹפוֹת. וְהִזְכִּירוּ רַבּוֹתֵינוּ כִּי כָל הָעוֹפוֹת אִם יִגַּע אָדָם בַּקֵּן שֶׁלָּהֶם לָקַחַת מִשָּׁם אֶפְרוֹחִים אוֹ בֵּיצִים יַעַזְבוּהוּ וְלֹא יְקַנְּנוּ בּוֹ לְעוֹלָם, וְהַיּוֹנָה לֹא תַּעַזְבֶנּוּ בְּשׁוּם עִנְיָן, וְכֵן יִשְׂרָאֵל לֹא יַחֲלִיפוּ בּוֹרְאָם וְתוֹרָתוֹ לְעוֹלָם, אֶלָּא אוֹ יְהוּדִי אוֹ צָלוּב (שמות רבה מב ט). וְלֹא בָּחַר בַּתַּרְנְגוֹלִים לְזִמַּת זְנוּתָם. וְהָרַב אָמַר בְּמוֹרֶה הַנְּבֻכִים (ג מו) כִּי הַטַּעַם בְּהַקְרָבַת גְּדוֹלֵי הַתּוֹרִים וְאֶפְרוֹחֵי הַיּוֹנִים כִּי הוּא הַטּוֹב שֶׁבָּהֶם, מִפְּנֵי שֶׁהַגָּדוֹל בַּיּוֹנִים אֵין עֲרֵבוּת בּוֹ. וְאֵין זֶה אֱמֶת, כִּי קְטַנֵּי הַיּוֹנִים כִּמְעַט שֶׁאֵין רְאוּיִין לַאֲכִילָה מִפְּנֵי רֹטְבָא עוֹדְפָנִית שֶׁבָּהֶם, אֲבָל אִם נָחוּשׁ לְטִבְעָם בַּאֲכִילָה יִתָּכֵן שֶׁנִּבְחֲרוּ לִסְגֻלָּתָם כִּי הַתּוֹרִים סְגֻלָּתָם חִדּוּד הַשֵּׂכֶל, וְאֶפְרוֹחֵי הַיּוֹנִים סְגֻלָּתָם לְתוֹעֶלֶת גְּדוֹלָה בִּמְבֻטְּלֵי הָאֵיבָרִים כְּפַלְגָּס וְכַיּוֹצֵא בּוֹ:
@15 **וְהִקְרִיבוֹ הַכֹּהֵן אֶל הַמִּזְבֵּחַ** הַהַקְרָבָה הַזּוֹ הִיא הַעֲלָאָה שֶׁיַּעֲלֶה הָעוֹף אֶל הַמִּזְבֵּחַ וְשָׁם יִמְלֹק אוֹתוֹ, שֶׁהַמְּלִיקָה אֵינָהּ אֶלָּא בְּרֹאשׁוֹ שֶׁל מִזְבֵּחַ. וּמִפְּנֵי זֶה דָּרְשׁוּ (זבחים סה), "הַכֹּהֵן" - וְכִי עוֹלֶה עַל הַלֵּב שֶׁהַזָּר קָרֵב לְגַבֵּי מִזְבֵּחַ, אִם כֵּן לָמָּה נֶאֱמַר "הַכֹּהֵן וּמָלַק", מְלַמֵּד שֶׁלֹּא תְּהֵא הַמְּלִיקָה אֶלָּא בְּעַצְמוֹ שֶׁל כֹּהֵן. **וּמָלַק וְהִקְטִיר וְנִמְצָה** אֶפְשָׁר לוֹמַר כֵּן, מֵאַחַר שֶׁהוּא מַקְטִיר הוּא מוֹצֶה, אֶלָּא מַה הַקְטָרָה הָרֹאשׁ בְּעַצְמוֹ וְהַגּוּף בְּעַצְמוֹ אַף מְלִיקָה הָרֹאשׁ בְּעַצְמוֹ וְהַגּוּף בְּעַצְמוֹ. וּפְשׁוּטוֹ שֶׁל מִקְרָא מְסֹרָס הוּא, וּמָלַק וְהִקְטִיר וְקֹדֶם הַקְטָרָה וְנִמְצָה דָמוֹ כְּבָר, לְשׁוֹן רַשִׁ"י (רש"י על ויקרא א':ט"ו). וְלֹא יִתָּכֵן לוֹמַר שֶׁיִּמְלֹק אֶת הָרֹאשׁ וְיַקְטִירֶנּוּ וְאַחֲרֵי כֵן וְנִמְצָה דַּם הַגּוּף עַל קִיר הַמִּזְבֵּחַ וְהִקְטִיר אוֹתוֹ, לְפִי שֶׁאֵין אֵבָרִים קְרֵבִין לְעוֹלָם בְּשׁוּם קָרְבָּן אֶלָּא לְאַחַר הַרְצָאַת דָּמִים, כִּי הַדָּם הוּא בַּנֶּפֶשׁ יְכַפֵּר בְּכָל הַקָּרְבָּנוֹת. וּלְפִיכָךְ דָּרְשׁוּ כֵן, שֶׁלֹּא בָּא הַכָּתוּב אֶלָּא לְהַקִּישׁ מְלִיקָה לְהַקְטָרָה, שֶׁיְּהֵא בִּשְׁנֵיהֶם הָרֹאשׁ בְּעַצְמוֹ וְהַגּוּף בְּעַצְמוֹ. אֲבָל פְּשׁוּטוֹ שֶׁל מִקְרָא, וּמָלַק אֶת רֹאשׁוֹ לְהַקְטִיר הַמִּזְבֵּחַ, יְלַמֵּד עַל הַמְּלִיקָה שֶׁתִּהְיֶה לְהַקְטִיר הָרֹאשׁ כַּאֲשֶׁר יַקְטִיר הַגּוּף, כְּמוֹ שֶׁאָמַר (ויקרא א':י"ז) "וְהִקְטִיר אוֹתוֹ הַכֹּהֵן", כִּי דֶּרֶךְ הַכָּתוּב בְּכָל הַקָּרְבָּנוֹת לוֹמַר כֵּן כְּמוֹ שֶׁפֵּרַשְׁתִּי (רמב"ן על ויקרא א':ו') בְּנִתְחֵי הָעוֹלָה. אֲבָל אָמַר בְּכָאן (ויקרא א':י"ז) "וְהִקְטִיר אוֹתוֹ הַכֹּהֵן" וְלֹא אָמַר וְהִקְטִיר אֶת הַכֹּל, כִּי שְׁתֵּי הַקְטָרוֹת הֵן, יַקְטִיר הָרֹאשׁ וְיָסִיר הַמֻּרְאָה וְשִׁסַּע אוֹתוֹ וְיַקְטִיר הַגּוּף, כְּמוֹ שֶׁשָּׁנִינוּ בִּזְבָחִים (שם):
@16 **וְהֵסִיר אֶת מֻרְאָתוֹ בְּנֹצָתָהּ** מְקוֹם הָרְעִי, זֶה הַזֶּפֶק. **בְּנוֹצָתָהּ** עִם בְּנֵי מֵעֶיהָ. וְנוֹצָה לְשׁוֹן דָּבָר מָאוּס, וְכֵן "כִּי נָצוּ גַּם נָעוּ" (איכה ד טו), וְזֶהוּ שֶׁתִּרְגֵּם אוּנְקְלוֹס (תרגום אונקלוס על ויקרא א':ט"ז) "בְּאֻכְלֵהּ". וְזֶהוּ מִדְרָשׁוֹ שֶׁל אַבָּא יוֹסֵי בֶּן חָנָן (תורת כהנים פרשה ז ט) שֶׁאָמַר נוֹטֵל אֶת הַקֻּרְקְבָן עִמָּהּ. וְרַבּוֹתֵינוּ אָמְרוּ (זבחים סה), קוֹדֵר אֶת הַזֶּפֶק בְּסַכִּין כְּעֵין אֲרֻבָּה וְנוֹטְלוֹ עִם הַנּוֹצָה, לְשׁוֹן רַשִׁ"י (רש"י על ויקרא א':ט"ז). וְאֵינֶנּוּ נָכוֹן, שֶׁאֵין נוֹצָה בְּשׁוּם מָקוֹם אֶלָּא נוֹצָה מַמָּשׁ, וְכֵן "כִּי נָצוּ גַּם נָעוּ" יֹאמַר שֶׁהֶעֱלוּ נוֹצָה לְעוֹפֵף מִמְּקוֹמָם אֶל הַגּוֹלָה, וְגַם יָנוּעוּ שָׁם שֶׁלֹּא מָצְאוּ מָנוֹחַ. וְכָמוֹהוּ "כִּי נָצֹא תֵּצֵא" (ירמיהו מח ט). וְהַמְּתַרְגֵּם הַיְּרוּשַׁלְמִי אָמַר בּוֹ "אֲרֵי יִתְקוֹטְטוּ אַף יִטַּלְטְלוּ", עֲשָׂאוֹ מִן "כִּי יִנָּצוּ אֲנָשִׁים" (דברים כה יא), יֹאמַר כִּי הֵם נִצִּים בְּכָל הָעַמִּים וְנוֹדְדִים מֵהֶם וְלֹא יוֹסִיפוּ לָגוּר בְּתוֹכָם, וְיָפֶה פֵּרֵשׁ. אֲבָל לְשׁוֹן נוֹצָה לֹא יִמָּצֵא כְּדִבְרֵי הָרַב. וּמִדְרָשׁוֹ שֶׁל אַבָּא יוֹסֵי שֶׁהִצְרִיךְ לִטֹּל אַף הַקֻּרְקְבָן עִמָּהּ, מִפְּנֵי שֶׁהַזֶּפֶק וְהַוֶּשֶׁט עִם הַקֻּרְקְבָן כְּלֵי הַמַּאֲכָל הַכֹּל בִּכְלַל מֻרְאָתוֹ, כִּי בַּקֻּרְקְבָן יַעֲשֶׂה הָרְעִי, וְלֹא חָלַק אַבָּא יוֹסֵי כְּלָל עַל מַה שֶׁאָמַר תַּנָּא קַמָּא יִטְּלֶנּוּ עִם הַנּוֹצָה, שֶׁהֲרֵי שָׁנִינוּ בַּמִּשְׁנָה בְּמַסֶּכֶת זְבָחִים פֶּרֶק שִׁשִּׁי (זבחים נד), בָּא לוֹ לַגּוּף וְהֵסִיר אֶת הַמֻּרְאָה וְאֶת הַנּוֹצָה וְאֶת בְּנֵי מֵעַיִם הַיּוֹצְאִים עִמָּהּ וְהִשְׁלִיכָם לְבֵית הַדֶּשֶׁן, וּמִשְׁנָה זוֹ מִשְׁנַת אַבָּא יוֹסֵי הִיא, וְקָתָנֵי נוֹצָה. וְדַעַת אוּנְקְלוֹס כְּדַעַת חֲכָמִים, שֶׁאֵינוֹ מֵסִיר רַק הַזֶּפֶק בְּנוֹצָתוֹ עִם הָאֹכֶל הַכָּנוּס בּוֹ שֶׁהוּא הַמֻּרְאָה, וּלְפִי שֶׁהַכֹּהֵן תּוֹפֵס בַּזֶּפֶק וּמֵסִיר בּוֹ אֶת הַמֻּרְאָה אָמַר "יָת זְפָקֵיהּ בְּאֻכְלֵהּ", כְּאִלּוּ הוּא אֻכְלֵהּ בִּזְפָקֵיהּ, כִּי "אֻכְלֵהּ" תַּרְגּוּם "מֻרְאָתוֹ", וּ"זְפָקֵיהּ" תַּרְגּוּם "נוֹצָתָהּ", שֶׁהַכָּתוּב אָמַר שֶׁיָּסִיר הַמֻּרְאָה, שֶׁהוּא הָאֹכֶל, בְּנוֹצָתָהּ שֶׁעָלֶיהָ, שֶׁנּוֹטֵל הַזֶּפֶק בְּעוֹרוֹ וּבְנוֹצָה שֶׁעָלָיו. וְכָךְ אָמַר אוּנְקְלוֹס (שמות כג כא) "אֲרֵי בִּשְׁמִי מֵימְרֵהּ", וּכְפִי הָעִבְרִי יֹאמַר "אֲרֵי שְׁמִי בְּמֵימְרֵהּ", אֲבָל הָפַךְ תַּרְגּוּמוֹ לְצֹרֶךְ דָּבָר שֶׁיָּדַע בּוֹ. וְתִרְגֵּם "וְאֵת שְׁתֵּי קְצוֹת שְׁתֵּי הָעֲבֹתֹת" (שם כח כה) כֵּן בְּהִפּוּךְ "וְיָת תַּרְתֵּין גְּדִילָן דְּעַל תְּרֵין סִטְרוֹהִי", וְכֵן רַבִּים:
@17 **בִּכְנָפָיו** עִם כְּנָפָיו, אֵינוֹ צָרִיךְ לִמְרֹט כַּנְפֵי נוֹצָתוֹ. "כְּנָפָיו", נוֹצָה מַמָּשׁ, לְשׁוֹן רַשִׁ"י (רש"י על ויקרא א':י"ז). וְאֵינֶנּוּ נָכוֹן, שֶׁאִם כֵּן לֹא יַזְכִּיר הַכָּתוּב מֵאֵי זֶה מָקוֹם יְשַׁסַּע אוֹתוֹ, אִם מִלְּפָנָיו אוֹ מִגַּבּוֹ. אֲבָל פֵּרוּשׁוֹ וְשִׁסַּע אוֹתוֹ בִּמְקוֹם כְּנָפָיו, כִּי הַבֵּי"ת בֵּי"ת הַכְּלִי, כְּאָמְרְךָ בָּאָרוֹן בַּבַּיִת אוֹ בַּשָּׂדֶה. וְאֵין "כְּנָפָיו" נוֹצָה, אֲבָל הוּא כְּכָל הַכְּנָפַיִם שֶׁבַּכָּתוּב, "כֹּל צִפּוֹר כָּל כָּנָף" (בראשית ז יד), "יִפְרֹשׁ כְּנָפָיו לְתֵימָן" (איוב לט כו), וְכֵן "בִּכְנַף מְעִילוֹ" (שמואל א טו כז). וְ"נוֹצָה" הוּא הַשֵּׂעָר אֲשֶׁר עַל גּוּף הָעוֹפוֹת, כְּעִנְיָן שֶׁכָּתוּב (יחזקאל יז ג) "הַנֶּשֶׁר הַגָּדוֹל גְּדוֹל הַכְּנָפַיִם אֶרֶךְ הָאֵבֶר מָלֵא הַנּוֹצָה", וְכֵן שָׁנִינוּ (טהרות א ג) הַכְּנָפַיִם וְהַנּוֹצָה טְמֵאוֹת וּמְטַמְּאוֹת וּמִצְטָרְפוֹת, וְאָמְרוּ (תורת כהנים אחרי פרק יב ב), פְּרָט לַחַרְטוֹם וְלַצִּפָּרְנַיִם וְלַכְּנָפַיִם וְלַנּוֹצָה:
@18 **וְיָצַק וְנָתַן וֶהֱבִיאָהּ** מְלַמֵּד שֶׁיְּצִיקָה וּבְלִילָה כְּשֵׁרָה בְּזָר. **הַכֹּהֲנִים וְקָמַץ** מִקְּמִיצָה וְאֵילָךְ מִצְוַת כְּהֻנָּה, לְשׁוֹן רַשִׁ"י (רש"י על ויקרא ב':א'). וְצָרִיךְ שֶׁנְּבָאֵר שֶׁאֵין מִצְוַת כְּהֻנָּה מַתְחֶלֶת בַּקְּמִיצָה, שֶׁהֲרֵי הַגָּשָׁה קוֹדֶמֶת לַקְּמִיצָה וְהִיא פְּסוּלָה בְּזָר, כְּמוֹ שֶׁאָמַר (ויקרא ב':ח') "וְהִקְרִיבָהּ אֶל הַכֹּהֵן וְהִגִּישָׁהּ אֶל הַמִּזְבֵּחַ", וְאח"כ "וְהֵרִים הַכֹּהֵן אֶת אַזְכָּרָתָהּ" (ויקרא ב':ט'), שֶׁהוּא הַקֹּמֶץ, שֶׁהֲרֵי הַכֹּהֵן הוּא מַגִּישָׁהּ אֶל הַמִּזְבֵּחַ לְקֶרֶן מַעֲרָבִית דְּרוֹמִית ואח"כ קוֹמֵץ. וְכָךְ שָׁנִינוּ (קידושין לו), הַסְּמִיכוֹת וְהַתְּנוּפוֹת וְהַהַגָּשׁוֹת וְהַקְּמִיצוֹת נוֹהֲגוֹת בָּאֲנָשִׁים וְאֵין נוֹהֲגוֹת בַּנָּשִׁים. וְאָמְרוּ, הַגָּשׁוֹת דִּכְתִיב "זֹאת תּוֹרַת הַמִּנְחָה הַקְרֵב אֹתָהּ בְּנֵי אַהֲרֹן" (ויקרא ו':ז') וְלֹא בְּנוֹת אַהֲרֹן. א"כ הַהַגָּשָׁה בִּבְנֵי אַהֲרֹן הִיא. אֲבָל מָה שֶׁאָמְרוּ (מנחות ט) "מִקְּמִיצָה וְאֵילָךְ מִצְוַת כְּהֻנָּה" כַּוָּנָתָם כִּי מִקְּמִיצָה זוֹ הַכְּתוּבָה בַּפָּסוּק הַזֶּה וְאֵילָךְ מִצְוַת כְּהֻנָּה, לֹא בַּדְּבָרִים שֶׁהִקְדִּים הַכָּתוּב בְּכָאן לַקְּמִיצָה, שֶׁהֲרֵי בְּפָרָשָׁה זוֹ הִזְכִּיר יְצִיקָה וּנְתִינַת לְבוֹנָה וַהֲבָאָה אֶל הַכֹּהֵן וּקְמִיצָה, וְלֹא הֻזְכְּרָה כָּאן הַגָּשָׁה אֶל הַמִּזְבֵּחַ, נִמְצָא שֶׁכָּל הָאֲמוּרִין כָּאן קֹדֶם קְמִיצָה כְּשֵׁרִין בְּזָר, שֶׁהֵם יְצִיקָה וּבְלִילָה וַהֲבָאָה:
@28 **כָּל הַמִּנְחָה אֲשֶׁר תַּקְרִיבוּ לַה' לֹא תֵעָשֶׂה חָמֵץ** אָסַר לְהָבִיא הַמִּנְחָה חָמֵץ, וְאַחַר כָּךְ אָמַר "לֹא תַקְטִירוּ מִמֶּנּוּ", לֶאֱסֹר שֶׁלֹּא יַחְמִיץ הַקֹּמֶץ וְיַקְטִירֶנּוּ וְיִכָּנֵס בִּכְלַל "לֹא תַקְטִירוּ מִמֶּנּוּ אִשֶּׁה". כָּל הַקְטָרָה לְשׁוֹן קְטֹרֶת הַסַּמִּים, שֶׁהַפַּטָּמִין אוֹמְרִים יָפֶה הָיָה הַדְּבַשׁ לַקְּטֹרֶת אֶלָּא שֶׁאֲסָרַתּוּ הַתּוֹרָה (תורת כהנים פרשה יב ד). וְאָמַר "מִמֶּנּוּ" לֶאֱסֹר מִקְצָתוֹ, כְּלוֹמַר חֲצִי קֹמֶץ, וְכֵן עַל עֵרוּבוֹ לוֹקֶה מֵרִבּוּי הַכָּתוּב שֶׁאָמַר "כִּי כָל שְׂאֹר וְכָל דְּבַשׁ" כְּמוֹ שֶׁמְּפֹרָשׁ בִּמְנָחוֹת (נח) וּבִפְסָחִים (מג). וְטַעַם הַכָּתוּב שֶׁיַּזְכִּיר "מִנְחָה הִיא" (פסוק ו טו) וְיִכְתֹּב "הוּא", וְכֵן בְּכָל מָקוֹם מִפָּרָשַׁת "הִנֵּה אָנֹכִי שֹׁלֵחַ מַלְאָךְ" (שמות כג כ), וְכֵן "הָאִשָּׁה הַהִוא" (במדבר ה לא דברים יז ה) בַּעֲבוּר שֶׁהַנְּקֵבָה בִּכְלַל הַזָּכָר בְּכֹחַ. וְטַעַם הַשְּׂאוֹר וְהַדְּבַשׁ יִתָּכֵן שֶׁהוּא כְּדִבְרֵי הָרַב בְּמוֹרֶה הַנְּבֻכִים (ג מו), אָמַר שֶׁמָּצָא בְּסִפְרֵיהֶם שֶׁהַמִּנְהָג הָיָה לְעוֹבְדֵי ע"ז לְהַקְרִיב כָּל מִנְחָתָם חָמֵץ וּלְעָרֵב הַדְּבַשׁ בְּכָל קָרְבְּנֵיהֶם, וְלָכֵן אֲסָרָם לַגָּבוֹהַּ. וְכָזֶה אָמְרוּ רַבּוֹתֵינוּ (ספרי שופטים קמו) בַּמַּצֵּבָה, שֶׁהָיְתָה נִבְחֶרֶת בִּימֵי הָאָבוֹת וְאַחַר כָּךְ שְׂנֵאָהּ הַשֵּׁם מִפְּנֵי שֶׁעֲשָׂאוּהָ חוֹק לַע"ז, כְּמוֹ שֶׁאָמַר "אֲשֶׁר שָׂנֵא ה' אֱלֹהֶיךָ" (דברים טז כב). וּבְטַעַם הַמֶּלַח אָמַר גַּם כֵּן בַּעֲבוּר שֶׁהֵם יִמְאֲסוּ אוֹתוֹ וְלֹא יַקְרִיבוּהוּ כְּלָל. וְיִתָּכֵן מִפְּנֵי שֶׁאֵינוֹ דֶּרֶךְ כָּבוֹד לִהְיוֹת לֶחֶם הַשֵּׁם תָּפֵל מִבְּלִי מֶלַח, כְּטַעַם "הַקְרִיבֵהוּ נָא לְפֶחָתֶךָ" (מלאכי א ח), וּלְפִיכָךְ מִעֲטוּ הָעֵצִים וְהַדָּם שֶׁאֵין טְעוּנִים מֶלַח (מנחות כ), אוֹ שֶׁיֵּשׁ בְּכָל אֵלֶּה סוֹד נֶעֱלָם מִמֶּנּוּ. וְאָמַר הַכָּתוּב בִּשְׂאוֹר וּדְבַשׁ לְשׁוֹן רַבִּים, כִּי עִם אַהֲרֹן וּבָנָיו יְדַבֵּר, וְחָזַר וְאָמַר "וְכָל קָרְבַּן מִנְחָתְךָ בַּמֶּלַח תִּמְלָח", כִּי יַחְזֹר אֶל מֵבִיא הַמִּנְחָה שֶׁאָמַר בּוֹ בִּתְחִלַּת הַפָּרָשָׁה (ויקרא ב':ז') "וְאִם מִנְחַת מַרְחֶשֶׁת קָרְבָּנֶךָ". וְהַטַּעַם כִּי הַמְּלִיחָה כְּשֵׁרָה בְּזָר, כְּמוֹ יְצִיקָה וּבְלִילָה. וְטַעַם "עַל כָּל קָרְבָּנְךָ" עַל כָּל קָרְבְּנוֹתֶיךָ, שֶׁכָּל הַקָּרְבָּנוֹת טְעוּנִין מֶלַח כְּמוֹ הַמִּנְחָה:
@30 **וְלֹא תַשְׁבִּית מֶלַח בְּרִית אֱלֹהֶיךָ** שֶׁהַבְּרִית כְּרוּתָה לַמֶּלַח מִשֵּׁשֶׁת יְמֵי בְּרֵאשִׁית שֶׁהֻבְטְחוּ הַמַּיִם הַתַּחְתּוֹנִים לִקְרַב בַּמִּזְבֵּחַ בַּמֶּלַח וְנִסּוּךְ הַמַּיִם בֶּחָג, לְשׁוֹן רַשִׁ"י (רש"י על ויקרא ב':י"ג). וּמִדְרַשׁ חֲכָמִים הוּא. וְר"א אָמַר (אבן עזרא על ויקרא ב':י"ג) עַל דֶּרֶךְ הַפְּשָׁט הִכְנַסְתִּיךָ בִּבְרִית וְהִשְׁבַּעְתִּיךָ שֶׁלֹּא תַּקְרִיב תָּפֵל וְלֹא יֵאָכֵל, כִּי הוּא דֶּרֶךְ בִּזָּיוֹן. וּבַעֲבוּר שֶׁהוּא בְּרִית בַּקָּרְבָּנוֹת יַעֲשֶׂה הַכָּתוּב זֹאת הַבְּרִית אָב לְכָל הַבְּרִיתוֹת, וְיֹאמַר בְּמַתְּנוֹת כְּהֻנָּה (במדבר יח יט) וּבְמַלְכוּת דָּוִד (דהי"ב יג ה) "בְּרִית מֶלַח" כִּי הוּא קַיָּם כִּבְרִית הַמֶּלַח בַּקָּרְבָּנוֹת. אֲבָל ר' אַבְרָהָם פֵּרֵשׁ שָׁם בְּרִית כְּרוּתָה, מִגִּזְרַת "אֶרֶץ מְלֵחָה" (ירמיהו יז ו), וּמְקוֹם הַמֶּלַח נִכְרָת. וְאֵין טַעַם לִדְבָרָיו. וּמִפְּנֵי שֶׁאָמַר בְּכָאן "בְּרִית אֱלֹהֶיךָ" וְלֹא אָמַר "בְּרִית ה'" כִּלְשׁוֹן הַפָּרָשָׁה וּכְדֶרֶךְ כָּל הַקָּרְבָּנוֹת, אוֹ שֶׁיֹּאמַר "בְּרִית ה' אֱלֹהֶיךָ", אֲנִי סוֹבֵר בּוֹ עִנְיָן שֶׁהַמֶּלַח - מַיִם וּבְכֹחַ הַשֶּׁמֶשׁ הַבָּא בָּהֶם יֵעָשׂוּ מֶלַח, וְהַמַּיִם בְּתוֹלְדֹתָם יְרַוּוּ הָאָרֶץ וְיוֹלִידוּ וְיַצְמִיחוּ, וְאַחֲרֵי הֱיוֹתָם מֶלַח יַכְרִיתוּ כָּל מָקוֹם וְיִשְׂרְפוּ, לֹא תִזָּרַע וְלֹא תַצְמִחַ. וְהִנֵּה הַבְּרִית כְּלוּלָה מִכָּל הַמִּדּוֹת, וְהַמַּיִם וְהָאֵשׁ בָּאִים בָּהּ, וְעָדֶיהָ תֵּאתֶה וּבָאָה הַמֶּמְשָׁלָה הָרִאשֹׁנָה מַמְלֶכֶת הַשֵּׁם כַּמֶּלַח שֶׁיִּתֵּן טַעַם בְּכָל הַמַּאֲכָלִים, וּתְקַיֵּם וְתַכְרִית בִּמְלִיחוּתָהּ, וְהִנֵּה הַמֶּלַח כַּבְּרִית. וְלָכֵן אָמַר הַכָּתוּב (דהי"ב יג ה) "הֲלֹא לָכֶם לָדַעַת כִּי ה' אֱלֹהֵי יִשְׂרָאֵל נָתַן מַמְלָכָה לְדָוִד עַל יִשְׂרָאֵל לְעוֹלָם לוֹ וּלְבָנָיו בְּרִית מֶלַח עוֹלָם", כִּי הוּא גַּם כֵּן מִדָּתוֹ שֶׁל דָּוִד, וְלָכֵן אָמַר בַּקָּרְבָּנוֹת (במדבר שם) "בְּרִית מֶלַח עוֹלָם הִיא", כִּי הַבְּרִית מֶלַח הָעוֹלָם בּוֹ יִתְקַיֵּם וְיִכָּרֵת. וּכְבָר הוֹרֵיתִיךָ (שמות לא יג) לְהִתְבּוֹנֵן מִדְּבָרֵינוּ בִּמְקוֹמוֹת אֲחֵרִים פֵּרוּשׁ שָׁלֹשׁ תֵּבוֹת הַלָּלוּ "בְּרִית עוֹלָם הִיא":
@31 **וְאִם תַּקְרִיב מִנְחַת בִּכּוּרִים** הֲרֵי אִם מְשַׁמֵּשׁ בִּלְשׁוֹן כִּי, שֶׁהֲרֵי אֵין זֶה רְשׁוּת, שֶׁהֲרֵי בְּמִנְחַת הָעֹמֶר הַכָּתוּב מְדַבֵּר שֶׁהִיא חוֹבָה, וְכֵן "וְאִם יִהְיֶה הַיֹּבֵל לִבְנֵי יִשְׂרָאֵל" (במדבר לו ד), לְשׁוֹן רַשִׁ"י (רש"י על ויקרא ב':י"ד). וְהַנָּכוֹן כִּי בַּעֲבוּר שֶׁלֹּא יְצַוֶּה עַתָּה לַעֲשׂוֹת הַמִּצְוָה הַזֹּאת אָמַר כֵּן. יֹאמַר כִּי תַּקְרִיב מִנְחַת הַמַּחֲבַת תַּעֲשֶׂנָּה כֵן, וְאִם תַּקְרִיב מִנְחַת מַרְחֶשֶׁת כָּכָה תַּעֲשֶׂה, וְאִם מִנְחַת בִּכּוּרִים תִּהְיֶה הַמִּנְחָה אֲשֶׁר תַּקְרִיב כַּמִּשְׁפָּט הַזֶּה תַּעֲשֶׂה אֹתָהּ, וְהִנֵּה הָ"אִם" כִּפְשׁוּטוֹ. וְטַעַם "וְאִם יִהְיֶה הַיֹּבֵל לִבְנֵי יִשְׂרָאֵל" כִּי אָמְרוּ גַּם אִם יִנְחֲלוּ בְּנֵי יִשְׂרָאֵל אֶת הָאָרֶץ כָּל הַיָּמִים וְיִזְכּוּ לְקַדֵּשׁ אֶת שְׁנַת הַיּוֹבֵל, לֹא תַּחְזֹר לָנוּ הַנַּחֲלָה. וְאֶפְשָׁר גַּם כֵּן שֶׁאָמַר, וְאִם תַּקְרִיב מִנְחַת בִּכּוּרִים כֵּן תַּעֲשֶׂה, כְּאוֹמֵר אִם יְבִיאֲךָ ה' אֱלֹהֶיךָ אֶל הָאָרֶץ וְתִקְצֹר אֶת קְצִירָהּ וְתָבִיא מִנְחַת בִּכּוּרִים, כֵּן תַּעֲשֶׂה אוֹתָהּ, כִּי יְרֻשַּׁת הָאָרֶץ בִּתְנַאי יִזְכְּרֶנָּה לָהֶם, כְּמוֹ שֶׁאָמַר (דברים יא כב כג) "אִם שָׁמֹר תִּשְׁמְרוּן אֶת כָּל הַמִּצְוָה הַזֹּאת וְגוֹ' וְהוֹרִישׁ ה' אֶת כָּל הַגּוֹיִם מִלִּפְנֵיכֶם". וְכֵן בִּמְקוֹמוֹת רַבִּים:
@34 **וְאִם זֶבַח שְׁלָמִים קָרְבָּנוֹ וְגוֹ' אִם זָכָר אִם נְקֵבָה** הַטַּעַם בָּעוֹלָה שֶׁיִּהְיֶה זָכָר וּבַשְּׁלָמִים שֶׁיִּהְיוּ אִם זָכָר אִם נְקֵבָה וּבַחַטָּאת שֶׁתִּהְיֶה נְקֵבָה, דָּבָר בָּרוּר הוּא, כִּי הָעוֹלָה כִּשְׁמָהּ, וְהַשְּׁלָמִים מִלְּשׁוֹן "וְכָל חֶפְצִי יַשְׁלִם" (ישעיהו מד כח), "אֲבָנִים שְׁלֵמוֹת" (דברים כז ו), וְהַחַטָּאת לְכַפֵּר פָּנָיו בַּמִּנְחָה הַהוֹלֶכֶת לְפָנָיו, וּכְבָר כָּתַבְתִּי זֶה (בראשית מו א), וְהָאָשָׁם זָכָר בַּעֲבוּר כִּי הַחַטָּאת בְּחַיָּבֵי כְּרֵתוֹת, שֶׁתָּשׁוּב הַנֶּפֶשׁ אֶל הָאֱלֹהִים אֲשֶׁר נְתָנָהּ, וְהָאָשָׁם לֹא יָבֹא עַל חִיּוּב כָּרֵת, וּכְאִלּוּ הוּא לְרֵיחַ נִיחוֹחַ כְּעוֹלָה, וּשְׂעִיר הַנָּשִׂיא בַּעֲבוּר כִּי הוּא הַמּוֹלֵךְ אֲשֶׁר לוֹ הַמִּשְׁפָּט וְהַלּוֹחֵם מִלְחֲמוֹת הַשֵּׁם וְעַל חַרְבּוֹ יִחְיֶה, כְּדֶרֶךְ שְׂעִירֵי עֲבוֹדָה זָרָה:
@38 **וְהִקְטִירוּ אֹתוֹ בְנֵי אַהֲרֹן** כִּנּוּי לָאִשֶּׁה הַנִּזְכָּר (ויקרא ג':ג') "וְהִקְרִיב מִזֶּבַח הַשְּׁלָמִים אִשֶּׁה לַה'", וְהוּא שָׁוֶה עִם מַה שֶׁאָמַר לְמַטָּה (ויקרא ג':ט"ז) "וְהִקְטִירָם" כִּי שָׁם יִרְמֹז לְכָל הָאֵמוּרִין. וּמִדְרָשׁוֹ (תו"כ פרשה יד י) "וְהִקְטִירוּ אוֹתוֹ" (כאן) "וְהִקְטִירוֹ" (ויקרא ג':י"א) "וְהִקְטִירָם" (ויקרא ג':ט"ז), מַה ת"ל, "וְהִקְטִירוּ אוֹתוֹ" הַכָּשֵׁר וְלֹא הַפָּסוּל, "וְהִקְטִירוּ" שֶׁלֹּא יְעָרֵב חֲלָבִים בַּחֲלָבִים, "וְהִקְטִירָם" כֻּלָּם כְּאַחַת:
@42 **חֶלְבּוֹ הָאַלְיָה תְמִימָה** שֵׁם חֵלֶב בִּלְשׁוֹן הַקֹּדֶשׁ - הַשֻּׁמָּן הַנִּפְרָד שֶׁאֵינוֹ עִם הַבָּשָׂר כְּדָבָר אֶחָד, כִּי הַשֻּׁמָּן הַמִּתְעָרֵב בַּבָּשָׂר שֶׁאֵינוֹ נִפְרָד מִמֶּנּוּ יִקָּרֵא שֻׁמָּן, כְּעִנְיָן שֶׁאָמַר הַכָּתוּב "וַיִּשְׁמַן יְשֻׁרוּן" (דברים לב טו), "וַיֹּאכְלוּ וַיִּשְׂבְּעוּ וַיַּשְׁמִינוּ" (נחמיה ט כה), "הַשְׁמֵן לֵב הָעָם הַזֶּה" (ישעיהו ו י), "וּבְשָׂרִי כָּחַשׁ מִשָּׁמֶן" (תהלים קט כד), "וְהָיָה דָּשֵׁן וְשָׁמֵן" (ישעיהו ל כג), "כְּמוֹ חֵלֶב וָדֶשֶׁן תִּשְׂבַּע נַפְשִׁי" (תהלים סג ו), וְכֵן בְּכָל מָקוֹם, וְהַחֵלֶב הוּא הַנִּפְרָד אֲשֶׁר עָלָיו קְרוּם וְנִקְלָף, לֹא יִתְעָרֵב הַלָּשׁוֹן בָּהֶן בְּשׁוּם מָקוֹם, כְּאָמְרֵנוּ "בָּשָׂר שָׁמֵן" לֹא "בְּשַׂר חֵלֶב", וְכֵן בִּשְׁאָר לְשׁוֹנוֹת הַגּוֹיִם שְׁמוֹתֵיהֶן חֲלוּקִין. וְיֹאמַר דֶּרֶךְ הַשְׁאָלָה בַּכָּתוּב (במדבר יח ל) "בַּהֲרִימְכֶם אֶת חֶלְבּוֹ מִמֶּנּוּ", כִּי הַטּוֹב אֲשֶׁר יוּרַם מִן הַתְּבוּאָה יְכַנֶּה אוֹתוֹ בְּחֵלֶב, כַּאֲשֶׁר הַחֵלֶב מוּרָם בַּקָּרְבָּנוֹת, "חֵלֶב כִּלְיוֹת חִטָּה" (דברים לב יד), יְדַמֶּה הַחִטָּה לַכְּלָיוֹת וְאֶת הַחֵלֶב אֲשֶׁר בָּם, כַּאֲשֶׁר יֹאמַר (שם) "וְדַם עֵנָב תִּשְׁתֶּה חָמֶר", וְאֵין הַיַּיִן דָּם, "וְאִכְלוּ אֶת חֵלֶב הָאָרֶץ" (בראשית מה יח), שֶׁיֹּאכְלוּ כָּל חֵלֶב שׁוֹר וְכֶשֶׂב וָעֵז וְכָל הַחַיָּה, דֶּרֶךְ מָשָׁל זֶה, וְהִנֵּה אֵין בָּאַלְיָה חֵלֶב כְּלָל, אֲבָל יֵשׁ בָּהּ שֻׁמָּן שֶׁאֵינוֹ נִפְרָד כְּמוֹ שֶׁיֵּשׁ בְּכָל נֵתַח טוֹב יָרֵךְ וְכָתֵף. וְכֵן יָדְעוּ הָרוֹפְאִים בְּטִבְעֵיהֶם שֶׁאֵין הַחֵלֶב נַעֲשֶׂה לְעוֹלָם סָמוּךְ לָעוֹר, וְלֹא בְּאֵבָר שֶׁיָּנוּעַ תָּמִיד. וְאָמְרוּ כִּי טֶבַע הַשֻּׁמָּן שֶׁאֵינוֹ נִפְרָד מִן הַבָּשָׂר בַּצְּלָעוֹת וּבַצְּדָדִין, וּבָאַלְיָה הוּא חַם וְלַח, וְהַנִּפְרָד מִן הַבָּשָׂר כְּמוֹ אֲשֶׁר עַל הַכְּלָיוֹת קַר וְלַח וְגַס וְעָבֶה, וְקָשֶׁה לְהִתְבַּשֵּׁל בָּאִצְטוֹמְכָה, וּמְמַהֵר לִכְלוֹת, וְיוֹלִיד לֵחָה לְבָנָה וְסוֹתֵם. וְאִם כֵּן הַכָּתוּב שֶׁאָמַר (ויקרא ג':י"ז) "כָּל חֵלֶב וְכָל דָּם לֹא תֹאכֵלוּ" אֵין שֻׁמָּן שֶׁעַל גַּבֵּי הָאַלְיָה בִּכְלָל, כִּי אֵינֶנּוּ חֵלֶב בִּשְׁמוֹ וּבְטִבְעוֹ, וְאִם הָיָה כָּל שֻׁמָּן חֵלֶב אִם כֵּן יֵאָסֵר כָּל שֻׁמָּן שֶׁבַּבְּהֵמָה בַּכְּתֵפוֹת וּבַצְּדָדִין, כִּי הַכָּתוּב לֹא אָמַר "כָּל חֵלֶב אֲשֶׁר יַקְרִיבוּ לַה' לֹא תֹאכֵלוּ", אֲבָל אָמַר כִּי כָּל בְּהֵמָה אֲשֶׁר תִּקְרַב עַל הַמִּזְבֵּחַ יֵאָסֵר כָּל חֵלֶב שֶׁבָּהּ. וְלֹא יִתָּכֵן שֶׁנֹּאמַר שֶׁאָסַר מַה שֶׁנַּקְרִיב מִן הַבְּהֵמָה, שֶׁאִם כֵּן יִהְיוּ הַכְּלָיוֹת וְהַיּוֹתֶרֶת עַל הַכָּבֵד אֲסוּרִים. אֲבָל כָּל הַנִּקְרָא חֵלֶב נֶאֱסָר אע"פ שֶׁאֵינוֹ קָרֵב לַמִּזְבֵּחַ, כְּגוֹן הַחֵלֶב אֲשֶׁר עַל הַטְּחוֹל, וְשֶׁאֵינוֹ נִקְרָא חֵלֶב מֻתָּר, אעפ"י שֶׁהוּא קָרֵב, כְּגוֹן הַכְּלָיוֹת וְהַיּוֹתֶרֶת מִן הַכָּבֵד, וְכֵן הָאַלְיָה. וְכֵן אָמַר הַכָּתוּב בַּמִּלּוּאִים בַּצִּוּוּי "וְלָקַחְתָּ מִן הָאַיִל הַחֵלֶב וְהָאַלְיָה" (שמות כט כב), וּבַמַּעֲשֶׂה "וַיִּקַּח אֶת הַחֵלֶב וְאֶת הָאַלְיָה" (ויקרא ח':כ"ה), כִּי אֵין הָאַלְיָה חֵלֶב. וְהַכָּתוּב הַזֶּה שֶׁאָמַר "חֶלְבּוֹ הָאַלְיָה תְמִימָה" פֵּרוּשׁוֹ שֶׁיַּקְרִיב מִמֶּנּוּ חֶלְבּוֹ בְּאַלְיָה תְּמִימָה, כִּי כַּאֲשֶׁר יָסִיר הָאַלְיָה תְּמִימָה עַד הֶעָצֶה, יוּסַר עִמָּהּ חֵלֶב רַב אֲשֶׁר הוּא מְחֻבָּר בָּהּ בַּצַּד הַפְּנִימִי. וְכָךְ אָמְרוּ בְּת"כ (ויקרא יט ב), לְהָבִיא אֶת הַחֵלֶב הַסָּמוּךְ לָאַלְיָה, זֶה הַחֵלֶב שֶׁבֵּין הַפְּקוֹקָלוֹת. וְעַל דַּעְתִּי עוֹד שִׁעוּר הַכָּתוּב הַזֶּה כְּמוֹ הַכָּתוּב הָאַחֵר (ויקרא ז':ג') "וְאֵת כָּל חֶלְבּוֹ יַקְרִיב מִמֶּנּוּ אֵת הָאַלְיָה", אַף כָּאן יֹאמַר וְהִקְרִיב מִזֶּבַח הַשְּׁלָמִים אִשֶּׁה לַה' כָּל חֶלְבּוֹ, בִּשְׁנֵי הַפְּסוּקִים יִכְלֹל תְּחִלָּה שֶׁיַּקְרִיב כָּל חֶלְבּוֹ, וְאַחֲרֵי כֵן פֵּרֵט וְהִזְכִּיר כָּל מַה שֶׁיַּקְרִיב מִמֶּנּוּ, וְאֵין כָּל הַנִּפְרָטִים חֵלֶב, כִּי שְׁתֵּי הַכְּלָיוֹת וְהַיּוֹתֶרֶת עַל הַכָּבֵד אֵינָן בִּכְלַל חֵלֶב כְּלָל. וְכָךְ אָמַר בְּפָרָשַׁת בַּיּוֹם הַשְּׁמִינִי (ויקרא ט':י') "וְאֶת הַחֵלֶב וְאֶת הַכְּלָיֹת וְאֶת הַיֹּתֶרֶת מִן הַכָּבֵד", הִזְכִּיר הַחֵלֶב לְבַדּוֹ וּשְׁאָר הַקְּרֵבִים לְבַדָּן, כַּאֲשֶׁר אָמַר (שמות כט כב) "מִן הָאַיִל הַחֵלֶב וְהָאַלְיָה", אִם כֵּן אַף הָאַלְיָה אֵינָהּ קְרֵבָה בִּכְלַל חֶלְבּוֹ, אֲבָל אָמַר שֶׁיַּקְרִיב מִזֶּבַח הַשְּׁלָמִים כָּל חֶלְבּוֹ, וְאַחַר כָּךְ פֵּרֵשׁ כָּל הַקְּרָבַיִם אֲשֶׁר הֵם חֵלֶב וַאֲשֶׁר אֵינָם חֵלֶב. וְהַכָּתוּב שֶׁאָמַר בַּחַטָּאת (ויקרא ד':ל"א) "וְאֶת כָּל חֶלְבָּהּ יָסִיר כַּאֲשֶׁר הוּסַר חֵלֶב מֵעַל זֶבַח הַשְּׁלָמִים" אֵין עִנְיָנוֹ בַּחֵלֶב לְבַדּוֹ, שֶׁאִם כֵּן לֹא יִהְיוּ הַכְּלָיוֹת וְהַיּוֹתֶרֶת עַל הַכָּבֵד קְרֵבִים בַּחַטָּאת, אֲבָל עִנְיָנוֹ שֶׁיָּסִיר הַחֵלֶב עִם כָּל הַמּוּסָרִים עִמּוֹ בְּזֶבַח הַשְּׁלָמִים, וְכֵן "וְאֶת כָּל חֶלְבָּהּ יָסִיר כַּאֲשֶׁר יוּסַר חֵלֶב הַכֶּשֶׂב מִזֶּבַח הַשְּׁלָמִים" (שם לה), שֶׁיְּסִירֶנּוּ כַּהֲסָרָתוֹ בְּזֶבַח הַשְּׁלָמִים עִם כָּל הַמּוּסָרִים שָׁם, לְרַבּוֹת הָאַלְיָה בְּחֶלְבָּהּ. וְכֵן "וַיָּשִׂימוּ אֶת הַחֲלָבִים עַל הֶחָזוֹת וַיַּקְטֵר אֶת הַחֲלָבִים הַמִּזְבֵּחָה" (ויקרא ט':כ') עִם כָּל הַמּוּסָרִים עִמָּהֶם. וְהֻצְרַכְתִּי לְהַאֲרִיךְ בָּזֶה לִסְתֹּם פִּיהֶם שֶׁל צַדּוּקִים יִמָּחֶה שְׁמָם, כִּי בְּדִבְרֵי תּוֹרָה נֶאֱמַר "עֲנֵה כְסִיל כְּאִוַּלְתּוֹ" (משלי כו ה), וְאָמְרוּ (אבות ב יט), הֱוֵי שָׁקוּד לִלְמֹד תּוֹרָה כְּדֵי שֶׁתָּשִׁיב לָאֶפִּיקוֹרוֹס. וְהַגָּאוֹן רַב סְעַדְיָה בָּרַח לָהֶם, שֶׁאָמַר כִּי "חֶלְבּוֹ הָאַלְיָה" יֶחְסַר וָי"ו, "וְהָאַלְיָה". וְר"א הֵשִׁיב (אבן עזרא על ויקרא ז':כ') שֶׁהָיָה רָאוּי לִהְיוֹת "חֶלְבּוֹ אַלְיָתוֹ" אוֹ "הַחֵלֶב הָאַלְיָה", וְאֵינָהּ תְּשׁוּבָה, כִּי מָצִינוּ "וְכָל יִשְׂרָאֵל וּזְקֵנָיו וְשֹׁטְרִים וְשֹׁפְטָיו" (יהושע ח לג). וְעוֹד אַזְכִּיר (רמב"ן על ויקרא ז':כ"ה) טָעוּת גָּדוֹל שֶׁטָּעָה ר"א בְּטַעֲנוֹתָיו עִמָּהֶם, הֵרַע לוֹמַר מֵהֶם. אֲבָל פֵּרוּשׁ הַגָּאוֹן אֵינֶנּוּ נָכוֹן, וְכָל שֶׁכֵּן שֶׁאֵינֶנּוּ מֻכְרָח לְהַתִּיר בּוֹ. וְהַמִּדְרָשׁ שֶׁעָשׂוּ רַבּוֹתֵינוּ (חולין קיז) "כָּל חֵלֶב שׁוֹר וְכֶשֶׂב וָעֵז" (ויקרא ז':כ"ג), שֶׁלֹּא אָסַר אֶלָּא חֵלֶב הַשָּׁוֶה בְּכֻלָּם, מִדְרָשׁ הָגוּן הוּא, אֲבָל שֶׁלֹּא לִתֵּן פִּתְחוֹן פֶּה לְבַעַל הַדִּין לַחְלֹק הֻצְרַכְנוּ לִרְאָיוֹת וּטְעָנוֹת שֶׁכָּתַבְנוּ:
@45 **וְאִם עֵז קָרְבָּנוֹ** הִזְכִּיר הַמִּין אִם מִמִּין הָעִזִּים קָרְבָּנוֹ כְּדַעַת אוּנְקְלוֹס (תרגום אונקלוס על ויקרא ג':י"ב) שֶׁאָמַר "מִן בְּנֵי עִזַּיָּא", וְכֵן מַה שֶׁאָמַר בָּעוֹלָה (ויקרא א':י') "מִן הַכְּשָׂבִים אוֹ מִן הָעִזִּים" מִמִּינָם. וְעַל דַּעְתִּי לֹא יַקְפִּיד לְשׁוֹן הַקֹּדֶשׁ בְּשֵׁם הַבְּהֵמוֹת, כִּי בְּרֻבָּם שֵׁם אֶחָד לַזָּכָר וְלַנְּקֵבָה, כְּגָמָל וַחֲמוֹר וְשָׁפָן וְאַרְנֶבֶת וַחֲזִיר, וּבָעוֹפוֹת יוֹנָה וְתוֹר, וְגַם בַּמִּינִים אֲשֶׁר לָהֶם שֵׁמוֹת לַזָּכָר וְלַנְּקֵבָה, כְּגוֹן שׁוֹר וּפָרָה כֶּשֶׂב כִּשְׂבָּה תַּיִשׁ וְעֵז, לֹא יַקְפִּיד וְאָמַר שֶׂה וְשׁוֹר לִנְקֵבָה, כְּעִנְיָן שֶׁכָּתוּב (ויקרא כ"ב:כ"ח) "וְשׁוֹר אוֹ שֶׂה אֹתוֹ וְאֶת בְּנוֹ" וְהוּא בְּפָרָה וְכִשְׂבָּה בִּלְבַד, כְּדַעַת הָאוֹמֵר אֵין חוֹשְׁשִׁין לְזֶרַע הָאָב (חולין עח). וְכֵן "מִן הָעִזִּים זָכָר תָּמִים יַקְרִיבֶנּוּ" (ויקרא א':י'), מִן הַתְּיָשִׁים, "וְאִם עֵז קָרְבָּנוֹ" זָכָר אוֹ נְקֵבָה, וְכֵן "וְאִם לֹא תַגִּיעַ יָדוֹ דֵּי שֶׂה" (ויקרא ה':ז'), כִּשְׂבָּה אוֹ שְׂעִירַת עִזִּים:
@52 **נֶפֶשׁ כִּי תֶחֱטָא בִשְׁגָגָה** בַּעֲבוּר הֱיוֹת הַמַּחְשָׁבָה בַּנֶּפֶשׁ וְהִיא הַשּׁוֹגֶגֶת, הִזְכִּיר כָּאן "נֶפֶשׁ". וְטַעַם הַקָּרְבָּנוֹת עַל הַנֶּפֶשׁ הַשּׁוֹגֶגֶת, מִפְּנֵי שֶׁכָּל הָעֲוֹנוֹת יוֹלִידוּ גְּנַאי בַּנֶּפֶשׁ, וְהֵם מוּם בָּהּ, וְלֹא תִּזְכֶּה לְהַקְבִּיל פְּנֵי יוֹצְרָהּ רַק בִּהְיוֹתָהּ טְהוֹרָה מִכָּל חֵטְא. וְלוּלֵי זֶה הָיוּ טִפְּשֵׁי הָעַמִּים זוֹכִים לָבֹא לְפָנָיו. וְלָכֵן הַנֶּפֶשׁ הַשּׁוֹגֶגֶת תַּקְרִיב קָרְבָּן, שֶׁתִּזְכֶּה לְקָרְבָה אֶל הָאֱלֹהִים אֲשֶׁר נְתָנָהּ, וּבַעֲבוּר זֶה גַּם כֵּן הִזְכִּיר "נֶפֶשׁ". וְרַבּוֹתֵינוּ דָּרְשׁוּ (ת"כ כאן) "נֶפֶשׁ" לְרַבּוֹת הַגֵּרִים וְהָעֲבָדִים. וְלֹא הִזְכִּיר בְּחַטַּאת כֹּהֵן הַמָּשִׁיחַ "וְכִפֶּר עָלָיו וְנִסְלַח לוֹ" כַּאֲשֶׁר הִזְכִּיר בִּשְׁאָר הַחוֹטְאִים, בַּקָּהָל וּבַנָּשִׂיא וּבַהֶדְיוֹט, אוּלַי לְרֹב מַעֲלָתוֹ לֹא יִתְכַּפֵּר וְנִסְלַח לוֹ לְגַמְרֵי עַד שֶׁיִּתְפַּלֵּל וְיִתְחַנֵּן לֵאלֹהָיו, כִּי מַלְאַךְ ה' צְבָאוֹת הוּא וְצָרִיךְ לִהְיוֹתוֹ נָקִי וּטֳהָר יָדַיִם. וְלֹא הִזְכִּיר כָּאן בְּפָרִים הַנִּשְׂרָפִים בְּהַקְטָרַת הָאֵמוּרִים "רֵיחַ נִיחוֹחַ" וְלֹא "אִשֶּׁה לַה'", וְהַטַּעַם בַּעֲבוּר הֱיוֹת מֵהֶם חֵלֶק בַּחוּץ אֵינֶנּוּ לְאִשֶּׁה לַה', וּבִשְׂעִיר הַנָּשִׂיא הִזְכִּיר כַּפָּרָה וְלֹא הִזְכִּיר "אִשֵּׁה רֵיחַ נִיחֹחַ לַה'" (במדבר כח ח), בַּעֲבוּר הֱיוֹת הַקָּרְבָּן שָׂעִיר. וּבְחַטַּאת הַיָּחִיד הִזְכִּיר "לְרֵיחַ נִיחוֹחַ לַה'" וְלֹא הִזְכִּיר "אִשֶּׁה", כִּי בְּיָדוּעַ שֶׁהוּא אִשֶּׁה, כִּי הַכַּוָּנָה כֻּלָּהּ בְּאִשֶּׁה לַה'. וְהַמַּשְׂכִּיל יָבִין:
@64 **וְנוֹדְעָה הַחַטָּאת אֲשֶׁר חָטְאוּ עָלֶיהָ** בְּיָדוּעַ שֶׁלֹּא יַקְרִיבוּ חַטָּאת עַד שֶׁיֵּדְעוּ שֶׁחָטְאוּ, אֲבָל דֶּרֶךְ הַלָּשׁוֹן שֶׁיֹּאמַר וְכַאֲשֶׁר יִוָּדַע לָהֶם שֶׁחָטְאוּ יָבִיאוּ קָרְבָּנָם, וְלֹא הִזְכִּיר כֵּן בַּמָּשִׁיחַ כִּי אֵין צֹרֶךְ. וְיִתָּכֵן שֶׁיְּצַוֶּה שֶׁלֹּא יִתְחַיְּבוּ בַּחַטָּאת הַזּוֹ אֶלָּא בִּידִיעָה, לֹא עַל הַסָּפֵק כְּאָשָׁם תָּלוּי. וְרַבּוֹתֵינוּ דָּרְשׁוּ (ת"כ כאן) שֶׁאִם יָדְעוּ שֶׁהוֹרוּ וְלֹא יָדְעוּ מָה הוֹרוּ יָכוֹל יְהוּ חַיָּבִים, ת"ל "וְנוֹדְעָה הַחַטָּאת" וְלֹא שֶׁיִּוָּדְעוּ הַחוֹטְאִים, וְלֹא הִזְכִּיר כֵּן בַּמָּשִׁיחַ בַּעֲבוּר שֶׁאָמַר (ויקרא ד':ג') "לְאַשְׁמַת הָעָם", הֲרֵי מָשִׁיחַ כְּצִבּוּר:
@72 **אֲשֶׁר נָשִׂיא יֶחֱטָא** לְשׁוֹן אַשְׁרֵי, אַשְׁרֵי הַדּוֹר שֶׁהַנָּשִׂיא מֵבִיא כַּפָּרָה עַל שִׁגְגָתוֹ, תּוֹרַת כֹּהֲנִים (חובה פרשה ה א). **אוֹ הוֹדַע אֵלָיו** אִם הוֹדַע, הַרְבֵּה "אוֹ" יֵשׁ שֶׁמְּשַׁמֵּשׁ בִּלְשׁוֹן "אִם" וְ"אִם" בִּמְקוֹם "אוֹ", וְכֵן "אוֹ נוֹדַע כִּי שׁוֹר נַגָּח הוּא" (שמות כא לו), לְשׁוֹן רַשִׁ"י (רש"י על ויקרא ד':כ"ב). וְר"א כָּתַב "אֲשֶׁר נָשִׂיא יֶחֱטָא" הָפוּךְ, אֲשֶׁר יֶחֱטָא נָשִׂיא, וְהוּא דָּבֵק לְמַעְלָה "וְאִם כָּל עֲדַת יִשְׂרָאֵל יִשְׁגּוּ", כְּאִלּוּ אָמַר וְאִם אֲשֶׁר יֶחֱטָא הוּא הַנָּשִׂיא, אוֹ הוֹדַע אֵלָיו חַטָּאתוֹ, הַכָּתוּב אָחַז דֶּרֶךְ קְצָרָה, וְהַטַּעַם שֶׁיִּוָּדַע לַנָּשִׂיא מֵעַצְמוֹ שֶׁחָטָא, אוֹ הוֹדַע אֵלָיו - הוֹדִיעוֹ אִישׁ אַחֵר שֶׁרָאָהוּ, וְיִהְיֶה דִּקְדּוּק "הוֹדַע" פֹּעַל עָבָר, כְּמוֹ "וְהֵצַר לְךָ" (דברים כח נב), וְיֶחְסַר הַמּוֹדִיעַ, כְּמוֹ "אֲשֶׁר יָלְדָה אֹתָהּ לְלֵוִי" (במדבר כו נט). וְאֵין צָרִיךְ לְכָל זֶה, כִּי שִׁמּוּשֵׁי "אֲשֶׁר" רַבִּים, יֵשׁ מֵהֶם יוֹרוּ עַל הַזְּמַן, כְּגוֹן "כַּאֲשֶׁר בָּא יוֹסֵף אֶל אֶחָיו" (בראשית לז כג), "כַּאֲשֶׁר כִּלּוּ לֶאֱכֹל אֶת הַשֶּׁבֶר" (שם מג ב) וְדוֹמֵיהֶם, אַף כָּאן כַּאֲשֶׁר נָשִׂיא יֶחֱטָא, וְיֶחְסַר כָּ"ף הָעֵת, וְכֵן "אֶת הַבְּרָכָה אֲשֶׁר תִּשְׁמְעוּ אֶל מִצְוֹת ה' אֱלֹהֵיכֶם" (דברים יא כז), כַּאֲשֶׁר תִּשְׁמְעוּ, "אֲשֶׁר רְאִיתֶם אֶת מִצְרַיִם הַיּוֹם לֹא תֹסִיפוּ לִרְאֹתָם עוֹד" (שמות יד יג), כַּאֲשֶׁר רְאִיתֶם, "שִׁבְעַת יָמִים תֹּאכַל מַצּוֹת אֲשֶׁר צִוִּיתִךָ" (שם לד יח), כַּאֲשֶׁר צִוִּיתִיךָ. וּפְעָמִים תֶּחְסַר הַמִּלָּה הַזּוֹ בֵּי"ת, "וַיְסִרֶהָ מִגְּבִירָה אֲשֶׁר עָשְׂתָה מִפְלֶצֶת לָאֲשֵׁרָה" (מלכים א טו יג), בַּאֲשֶׁר עָשְׂתָה מִפְלֶצֶת לָאֲשֵׁרָה, כְּטַעַם בַּעֲבוּר, כְּמוֹ "בַּאֲשֶׁר אַתְּ אִשְׁתּוֹ" (בראשית לט ט). וְטַעַם "אוֹ הוֹדַע אֵלָיו" עַל "וְאָשֵׁם", יֹאמַר כְּשֶׁיַּעֲשֶׂה אַחַת מִכָּל מִצְוֹת ה' אֲשֶׁר לֹא תֵעָשֶׂינָה וְאָשֵׁם לִהְיוֹת עָלָיו עֹנֶשׁ, אוֹ יִוָּדַע אֵלָיו וְיִתְכַּפֵּר לוֹ בְּקָרְבָּן, וְהַטַּעַם אוֹ יִהְיֶה אָשֵׁם אוֹ יָבִיא קָרְבָּן וְיִתְכַּפֵּר לוֹ. וְטַעַם "ה' אֱלֹהָיו" לוֹמַר כִּי אע"פ שֶׁהוּא הַמֶּלֶךְ הָאָדוֹן שֶׁאֵין עָלָיו מוֹרָא בָּשָׂר וָדָם, יֵשׁ לוֹ לִירֹא מֵה' אֱלֹהָיו כִּי הוּא אֲדוֹנֵי הָאֲדוֹנִים, וְכֵן "לְמַעַן יִלְמַד לְיִרְאָה אֶת ה' אֱלֹהָיו" (דברים יז יט), כְּלוֹמַר שֶׁיָּשִׂים אֶל לִבּוֹ כִּי יֵשׁ עָלָיו עֶלְיוֹן שֶׁהוּא אֱלֹהָיו אֲשֶׁר בְּיָדוֹ נַפְשׁוֹ וּמַמְלַכְתּוֹ:
@75 **וְאֶת דָּמוֹ יִשְׁפֹּךְ אֶל יְסוֹד מִזְבַּח הָעֹלָה** הוּא הַנִּזְכָּר, אֲבָל דֶּרֶךְ הַלָּשׁוֹן לְהַזְכִּיר הַשֵּׁם בִּמְקוֹם הַיְּדִיעָה, וְכֵן "וְסָמַךְ אֶת יָדוֹ עַל רֹאשׁ הַפָּר וְשָׁחַט אֶת הַפָּר" (ויקרא ד':ד'). וּלְרַבּוֹתֵינוּ בָּהֶם מִדְרָשִׁים כִּי תּוֹרַת ה' תְּמִימָה אֵין בָּהּ חָסֵר וְיָתֵר:
@86 **וְהוּא עֵד אוֹ רָאָה אוֹ יָדָע** אֵינָם שְׁלֹשָׁה עִנְיָנִים, כִּי אֵין עֵד בְּלֹא רְאִיָּה וּבְלֹא יְדִיעָה, אֲבָל יֹאמַר אִם שָׁמַע קוֹל אָלָה שֶׁנָּשְׂאוּ עָלָיו לְהַאֲלוֹתוֹ בְּדָבָר שֶׁהוּא עֵד, בֵּין בִּרְאִיָּה בֵּין בִּידִיעָה, אִם לֹא יַגִּיד יֵשׁ עָלָיו עָוֹן. וְהִנֵּה לֹא יִתְחַיֵּב בַּקָּרְבָּן הַזֶּה אֶלָּא אִם כֵּן יוֹדֵעַ עֵדוּת שֶׁיִּזְכֶּה מִמֶּנּוּ הַמַּשְׁבִּיעַ בְּדִינוֹ, וּלְכָךְ פֵּרְשׁוּ רַבּוֹתֵינוּ (שבועות לג) כִּי יֵשׁ עֵדוּת שֶׁתּוֹעִיל בִּרְאִיָּה בְּלֹא יְדִיעָה וְיֵשׁ שֶׁתּוֹעִיל בִּידִיעָה בְּלֹא רְאִיָּה, כֵּיצַד, מָנֶה מָנִיתִי לְךָ בִּפְנֵי פְּלוֹנִי וּפְלוֹנִי, וְטוֹעֵן לֹא הָיוּ דְּבָרִים מֵעוֹלָם, יָבוֹאוּ וְיָעִידוּ, זוֹ הִיא רְאִיָּה בְּלֹא יְדִיעָה. מָנֶה הוֹדֵיתָ לִי בִּפְנֵי פְּלוֹנִי וּפְלוֹנִי, יָבוֹאוּ וְיָעִידוּ, זוֹ הִיא יְדִיעָה בְּלֹא רְאִיָּה. וְעַל דֶּרֶךְ הַפְּשָׁט אֵין צָרִיךְ לִרְאִיָּה בְּלֹא יְדִיעָה, אֲבָל "אוֹ רָאָה" שֶׁהוּא רָאָה הַהַלְוָאָה אוֹ הַמִּקָּח לְגַמְרֵי, "אוֹ יָדַע" שֶׁשָּׁמַע אוֹתָם מוֹדִים בַּמַּעֲשֶׂה הַהוּא בִּפְנֵי עֵדִים וְלֹא רָאָה הַמַּעֲשֶׂה. וְלֹא אָמַר כָּאן "וְנֶעְלַם מִמֶּנּוּ" כִּי הוּא חַיָּב בְּמֵזִיד אוֹ בְּשִׁגְגַת הַשְּׁבוּעָה עִם זְדוֹן הָעֵדוּת, אֲבָל אִם הָיָה שָׁכוּחַ בָּעֵדוּת בִּשְׁעַת שְׁבוּעָה אֵין עָלָיו כְּלוּם:
@87 **וְנֶעְלַם מִמֶּנּוּ וְהוּא טָמֵא** שֶׁנֶּעֶלְמָה מִמֶּנּוּ הַטֻּמְאָה, **וְאָשֵׁם** בַּאֲכִילַת קָדָשִׁים אוֹ בִּיאַת מִקְדָּשׁ, לְשׁוֹן רַשִׁ"י (רש"י על ויקרא ה':ב'). וְאֵין הַכַּוָּנָה שֶׁיִּהְיוּ אֲכִילַת קָדָשִׁים וּבִיאַת מִקְדָּשׁ נִלְמָדִים מִן "וְאָשֵׁם", כִּי בְּכָל הַקָּרְבָּנוֹת לְמַעְלָה נֶאֱמַר כֵּן, אֲבָל הַפָּרָשָׁה הַזּוֹ תְּקַצֵּר בַּדָּבָר הַמּוּבָן, כִּי מִפְּנֵי שֶׁאֵין בִּנְגִיעַת נְבֵלָה וְשֶׁרֶץ שׁוּם חֵטְא וְלֹא הֻזְהֲרוּ מִמֶּנָּה אֲפִילּוּ הַכֹּהֲנִים, אִי אֶפְשָׁר שֶׁיְּחַיֵּב הַכָּתוּב בִּנְגִיעָתָם קָרְבָּן. אֲבָל אָמַר כִּי כַּאֲשֶׁר יִטְמָא הָאָדָם וְנֶעְלַם מִמֶּנּוּ הַטֻּמְאָה, אוֹ כַּאֲשֶׁר יִשָּׁבַע וְנֶעְלַם מִמֶּנּוּ הַשְּׁבוּעָה, וְיֶחֱטָא בְּהַעֲלָמָה שֶׁל אַחַת מֵאֵלֶּה, יִתְחַיֵּב לְהָבִיא קָרְבָּן. וּבְיָדוּעַ שֶׁאֵין בְּהַעֲלָמַת הַטֻּמְאָה חֵטְא זוּלָתִי שֶׁיֹּאכַל קָדָשִׁים אוֹ יָבֹא לַמִּקְדָּשׁ, וְאֵין בְּהַעֲלָמַת הַשְּׁבוּעָה חֵטְא זוּלָתִי שֶׁיַּעֲבֹר עָלֶיהָ. וְזֶה יִשּׁוּב פְּשׁוּטָן שֶׁל מִקְרָאוֹת בְּפָרָשָׁה זוֹ. וּלְרַבּוֹתֵינוּ בָּהּ עוֹד מִדְרָשִׁים לְחַזֵּק הָעִנְיָן הַזֶּה:
@90 **וְהִתְוַדָּה אֲשֶׁר חָטָא עָלֶיהָ וְהֵבִיא אֶת אֲשָׁמוֹ** אֵין הַסֵּדֶר כֵּן, אֲבָל הוּא מֵבִיא הַחַטָּאת וְסוֹמֵךְ עָלֶיהָ וּמִתְוַדֶּה, כְּעִנְיָן שֶׁנֶּאֱמַר לְהַלָּן (טז כא) "וְסָמַךְ אַהֲרֹן אֶת שְׁתֵּי יָדָיו עַל רֹאשׁ הַשָּׂעִיר הַחַי וְהִתְוַדָּה עָלָיו אֶת כָּל עֲוֹנֹת בְּנֵי יִשְׂרָאֵל". אֲבָל לֹא אָמַר כָּאן "וְסָמַךְ יָדוֹ" בַּעֲבוּר שֶׁפֵּרֵשׁ בְּכָל הַחַטָּאוֹת לְמַעְלָה שֶׁהֵם טְעוּנִים סְמִיכָה, וְכֵן בְּקָרְבְּנוֹת הַנְּדָבָה, וְלֹא פֵּרֵשׁ הַוִּדּוּי לְמַעְלָה בִּשְׁאָר הַחַטָּאוֹת. וְעַל דֶּרֶךְ הַפְּשָׁט יֵרָאֶה שֶׁאָמַר בְּכָאן "וְהִתְוַדָּה" בַּעֲבוּר כִּי שְׁבוּעַת הָעֵדוּת יָבִיאוּ קָרְבָּן עַל זְדוֹנָהּ, וְכֵן בִּשְׁבוּעַת הַפִּקָּדוֹן הִזְכִּיר (במדבר ה ז) "וְהִתְוַדּוּ אֶת חַטָּאתָם אֲשֶׁר עָשׂוּ", אֲבָל בְּחַטָּאת הַשְּׁגָגָה לֹא יַזְכִּיר וִדּוּי. אֲבָל עַל דַּעַת רַבּוֹתֵינוּ (ספרי זוטא נשא ה ה) "וְהִתְוַדָּה אֲשֶׁר חָטָא עָלֶיהָ" עַל כָּל הַנִּזְכָּרִים בַּפָּרָשָׁה, אַף טֻמְאַת מִקְדָּשׁ וְקָדָשָׁיו וּשְׁבוּעַת בִּטּוּי שֶׁהֵן בְּשׁוֹגֵג, וּשְׁאָר כָּל חַטָּאוֹת לָמַדְנוּ מִכָּאן. אֲבָל הִזְכִּיר הַוִּדּוּי בְּכָאן מִפְּנֵי שֶׁשְּׁבוּעַת הָעֵדוּת וּשְׁבוּעַת בִּטּוּי אֵין בִּזְדוֹנָן כָּרֵת וְהִצְרִיכָן וִדּוּי, וְכָל שֶׁכֵּן לְמַעְלָה בְּחַטָּאוֹת קְבוּעוֹת שֶׁיִּתְוַדֶּה עַל חַיָּבֵי כְּרֵיתוֹת. וְרַבּוֹתֵינוּ אָמְרוּ כִּי "וְהִתְוַדָּה אֲשֶׁר חָטָא עָלֶיהָ" כְּלָל לְכָל חַטָּאוֹת שֶׁטְּעוּנִין וִדּוּי, וְהַכָּתוּב בְּפָרָשַׁת נָשֹׂא (ה ו כ) "וְאָשְׁמָה הַנֶּפֶשׁ הַהִיא וְהִתְוַדּוּ אֶת חַטָּאתָם אֲשֶׁר עָשׂוּ", לְהָבִיא כָּל הָאֲשָׁמוֹת, כָּךְ מְפֹרָשׁ בְּסִפְרֵי (נשא ב). וְשָׁם דָּרְשׁוּ, "וְאָשְׁמָה הַנֶּפֶשׁ הַהִיא וְהִתְוַדּוּ" - בִּנְיַן אָב לְכָל הַמֵּתִים שֶׁיִּטָּעֲנוּ וִדּוּי:
@92 **וְאִם לֹא תַגִּיעַ יָדוֹ דֵּי שֶׂה** הֵקֵל הַכָּתוּב עַל הַחוֹטֵא בְּאֵלּוּ לְהָבִיא קָרְבָּן עוֹלֶה וְיוֹרֵד. וְיִתָּכֵן שֶׁהַטַּעַם בַּשְּׁבוּעוֹת מִפְּנֵי שֶׁאֵינָן חַיָּבֵי כְּרֵיתוֹת, וּבְטֻמְאַת מִקְדָּשׁ וְקָדָשָׁיו מִפְּנֵי שֶׁהוּא טוֹעֶה בִּדְבַר מִצְוָה, כִּי הַכֹּהֵן הָאוֹכֵל קָדָשִׁים וְהַבָּא לַמִּקְדָּשׁ לְהִשְׁתַּחֲווֹת אוֹ לְהַקְרִיב קָרְבָּן עוֹסֵק הוּא בַּמִּצְוָה וְדַעְתּוֹ לַשָּׁמַיִם, וּלְפִיכָךְ אע"פ שֶׁחָטָא בְּהַעֲלָמַת הַטֻּמְאָה רִבָּה לוֹ הַכָּתוּב כַּפָּרוֹת. וְאָמַר ר"א (אבן עזרא על ויקרא ה':ז') כִּי טַעַם "אֶחָד לְעֹלָה" שֶׁיִּקְרַב עַל הַמִּזְבֵּחַ כְּנֶגֶד הָאֵמוּרִין בְּחַטַּאת הַבְּהֵמָה. וְיָפֶה פֵּרֵשׁ:
@100 **וְהֵבִיא אֶת אֲשָׁמוֹ לַה'** נִקְרָא הַקָּרְבָּן הַזֶּה אָשָׁם, כְּמוֹ שֶׁאָמַר "בְּשֶׁקֶל הַקֹּדֶשׁ לְאָשָׁם", אֲבָל "וְהֵבִיא אֶת אֲשָׁמוֹ לַה'" הָאָמוּר לְמַעְלָה (ויקרא ה':ו') בְּקָרְבָּן עוֹלֶה וְיוֹרֵד, טַעְמוֹ וְהֵבִיא אֶת קָרְבָּנוֹ לַה', כִּי הַקָּרְבָּן הַהוּא חַטָּאת הוּא, כְּמוֹ שֶׁאָמַר (שם) "כִּשְׂבָּה אוֹ שְׂעִירַת עִזִּים לְחַטָּאת". וְלֹא נִתְבָּרֵר מָה טַעַם יִהְיֶה שֵׁם הַקָּרְבָּן הָאֶחָד "חַטָּאת" וְשֵׁם הָאֶחָד "אָשָׁם" וְכֻלָּן יָבֹאוּ עַל חֵטְא. וְלֹא נוּכַל לוֹמַר בַּעֲבוּר שֶׁהַחַטָּאת נְקֵבָה, כִּי יֵשׁ חַטָּאת זָכָר, שְׂעִירִים וּפָרִים, וְאֵין לוֹמַר שֶׁיְּהֵא מִפְּנֵי חֹמֶר הַחֵטְא, כִּי הִנֵּה הַמְּצֹרָע מֵבִיא שְׁנֵי קָרְבָּנוֹת, שֵׁם הָאֶחָד חַטָּאת וְהַשֵּׁנִי אָשָׁם. וְהַנִּרְאֶה בְּעֵינַי כִּי שֵׁם "אָשָׁם" מוֹרֶה עַל דָּבָר גָּדוֹל אֲשֶׁר הָעוֹשׂוֹ יִתְחַיֵּב לִהְיוֹת שָׁמֵם וְאָבֵד בּוֹ, מִלְּשׁוֹן "הַאֲשִׁימֵם אֱלֹהִים" (תהלים ה יא), "וְיֶאֶשְׁמוּ נְאוֹת מִדְבָּר", וְכֵן "תֶּאְשַׁם שֹׁמְרוֹן כִּי מָרְתָה בֵּאלֹהֶיהָ" (הושע יד א) וְכֵן "אֲשֵׁמִים אֲנַחְנוּ" (בראשית מב כא), נֶעֱנָשִׁים. וְחַטָּאת מוֹרָה עַל דָּבָר נָטָה בּוֹ מִן הַדֶּרֶךְ, מִלְּשׁוֹן "אֶל הַשַּׂעֲרָה וְלֹא יַחֲטִא" (שופטים כ טז). וְהִנֵּה אֲשַׁם גְּזֵלוֹת וַאֲשַׁם שִׁפְחָה חֲרוּפָה בַּעֲבוּר שֶׁהֵם בָּאִים אַף עַל הַמֵּזִיד יִקָּרֵא קָרְבָּנָם "אָשָׁם", וְכֵן אֲשַׁם הַנָּזִיר, אֲבָל אֲשַׁם מְעִילוֹת אע"פ שֶׁהוּא בְּשׁוֹגֵג בַּעֲבוּר שֶׁהוּא בְּקָדְשֵׁי ה' יִקָּרֵא הַקָּרְבָּן "אָשָׁם", כִּי הַחֵטְא הַגָּדוֹל יִתְחַיֵּב לִהְיוֹתוֹ אָשֵׁם בּוֹ, כַּאֲשֶׁר יִקָּרֵא מְעִילָה. וְעִנְיַן הַמְּצֹרָע בַּעֲבוּר שֶׁהַמְּצוֹרָע חָשׁוּב כְּמֵת, וְהִנֵּה הוּא כְּבָר שָׁמֵם וְאָבֵד, וְיִקָּרֵא קָרְבָּנוֹ הָרִאשׁוֹן "אָשָׁם", שֶׁיָּגֵן עָלָיו מִן הָאַשְׁמָה אֲשֶׁר הוּא שָׁמֵם בָּהּ, וְהַשֵּׁנִי "חַטָּאת", שֶׁהוּא מְכַפֵּר שִׁגְגוֹתָיו. וְטַעַם אָשָׁם תָּלוּי, מִפְּנֵי שֶׁבְּעָלָיו סָבוּר שֶׁאֵין עָלָיו עֹנֶשׁ, כִּי לֹא נוֹדַע שֶׁחָטָא, מִפְּנֵי זֶה הֶחְמִיר עָלָיו הַכָּתוּב בִּסְפֵקוֹ יוֹתֵר מִוַּדָּאוֹ וְהִצְרִיכוֹ אַיִל בְּכֶסֶף שְׁקָלִים, וְאִלּוּ נוֹדַע חֶטְאוֹ הָיָה מֵבִיא חַטָּאת בַּת דַּנְקָא, וּקְרָאוֹ "אָשָׁם", לֵאמֹר שֶׁהוּא בִּשְׁנֵי סְלָעִים כַּאֲשָׁמוֹת הַחֲמוּרִים, לִרְמֹז לוֹ שֶׁאִם יִהְיֶה נָקֵל בְּעֵינָיו וְלֹא יָבִיא כַּפָּרָתוֹ שָׁמֵם יִהְיֶה בַּעֲוֹנוֹ. וְזֶה טַעַם "אָשָׁם הוּא אָשֹׁם אָשַׁם לַה'" (ויקרא ה':י"ט), יֹאמַר כִּי הַקָּרְבָּן הַזֶּה אעפ"י שֶׁהוּא בָּא עַל הַסָּפֵק אָשָׁם הוּא, כִּי אָשֹׁם אָשַׁם לַה' הַיּוֹדֵעַ כָּל תַּעֲלוּמוֹת, וְאִם אוּלַי חָטָא לוֹ יַעֲנִישֶׁנּוּ. וְכֵן מַה שֶׁאָמַר לְמַעְלָה (ויקרא ה':ו') "וְהֵבִיא אֶת אֲשָׁמוֹ", בַּעֲבוּר כִּי מִן הַנִּזְכָּרִים מְזִידִין, כְּגוֹן שְׁבוּעַת הָעֵדוּת, יַזְכִּיר בּוֹ אָשָׁם, וְהוּא חַטָּאת. וְעַל דֶּרֶךְ הָאֱמֶת עוֹד הַקָּרְבָּן הַבָּא נְקֵבָה עַל חֵטְא יִקָּרֵא "חַטָּאת", וְהַזָּכָר יִקָּרֵא "אָשָׁם", וְהַשְּׂעִירִים וְהַפָּרִים יִקָּרְאוּ גַּם כֵּן "חַטָּאת" בַּעֲבוּר שֶׁהֵם לְחַטָּאת:
